class StreamHandler:
    def GET(self):
        _require_auth()
        params = web.input(request_id='', after_seq='')
        request_id = params.request_id
        if not request_id:
            raise web.badrequest()

        # Explicit query cursors are used by the frontend's manually-created
        # EventSource. Native EventSource reconnects remain compatible via the
        # standard Last-Event-ID request header.
        after_seq = _parse_sse_cursor(
            params.after_seq,
            web.ctx.env.get('HTTP_LAST_EVENT_ID', '0'),
        )

        web.header('Content-Type', 'text/event-stream; charset=utf-8')
        web.header('Cache-Control', 'no-cache')
        web.header('X-Accel-Buffering', 'no')

        return WebChannel().stream_response(request_id, after_seq)


class ChatHandler:
    def GET(self):
        # Explicitly declare HTML. With ``nosniff`` enabled, omitting this
        # header makes Chromium render the document source as plain text.
        web.header('Content-Type', 'text/html; charset=utf-8')
        web.header('Cache-Control', 'no-cache, no-store, must-revalidate')
        web.header('Pragma', 'no-cache')
        web.header('X-Content-Type-Options', 'nosniff')
        web.header('X-Frame-Options', 'DENY')
        web.header('Referrer-Policy', 'no-referrer')
        web.header('Permissions-Policy', 'camera=(), geolocation=(), payment=()')
        file_path = os.path.join(os.path.dirname(__file__), 'chat.html')
        with open(file_path, 'r', encoding='utf-8') as f:
            html = f.read()
        cache_bust = str(int(time.time()))
        html = re.sub(r'assets/js/console\.js(?:\?v=[^"\']*)?', f'assets/js/console.js?v={cache_bust}', html)
        html = re.sub(r'assets/js/notification-center\.js(?:\?v=[^"\']*)?', f'assets/js/notification-center.js?v={cache_bust}', html)
        html = re.sub(r'assets/css/console\.css(?:\?v=[^"\']*)?', f'assets/css/console.css?v={cache_bust}', html)
        # Inject the backend-resolved default language for first-load fallback.
        html = html.replace("{{COW_DEFAULT_LANG}}", i18n.get_language())
        from channel.web.page_revision import stamp_page
        return stamp_page(html)


