class WeixinQrHandler:
    """Handle WeChat QR code login from the web console.

    GET  /api/weixin/qrlogin          → fetch a new QR code
    POST /api/weixin/qrlogin          → poll QR status or start channel after login
    """

    _qr_state = {}

    @staticmethod
    def _qr_to_data_uri(data: str) -> str:
        """Generate a QR code as a PNG data URI."""
        try:
            import qrcode as qr_lib
            import io
            import base64
            qr = qr_lib.QRCode(error_correction=qr_lib.constants.ERROR_CORRECT_L, box_size=6, border=2)
            qr.add_data(data)
            qr.make(fit=True)
            img = qr.make_image(fill_color="black", back_color="white")
            buf = io.BytesIO()
            img.save(buf, format="PNG")
            b64 = base64.b64encode(buf.getvalue()).decode("ascii")
            return f"data:image/png;base64,{b64}"
        except ImportError:
            return ""

    @staticmethod
    def _get_running_channel():
        try:
            import sys
            mgr = getattr(sys.modules.get('__main__'), '_channel_mgr', None) or getattr(sys.modules.get('app'), '_channel_mgr', None)
            if mgr:
                return mgr.get_channel("weixin")
        except Exception:
            pass
        return None

    def GET(self):
        _require_sensitive_local_access()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            running_ch = self._get_running_channel()
            if running_ch and hasattr(running_ch, '_current_qr_url') and running_ch._current_qr_url:
                qr_image = self._qr_to_data_uri(running_ch._current_qr_url)
                return json.dumps({
                    "status": "success",
                    "qrcode_url": running_ch._current_qr_url,
                    "qr_image": qr_image,
                    "source": "channel",
                })

            from channel.weixin.weixin_api import WeixinApi, DEFAULT_BASE_URL
            base_url = conf().get("weixin_base_url") or DEFAULT_BASE_URL
            api = WeixinApi(base_url=base_url)
            qr_resp = api.fetch_qr_code()
            qrcode = qr_resp.get("qrcode", "")
            qrcode_url = qr_resp.get("qrcode_img_content", "")
            if not qrcode:
                return json.dumps({"status": "error", "message": "No QR code returned"})
            qr_image = self._qr_to_data_uri(qrcode_url)
            WeixinQrHandler._qr_state = {
                "qrcode": qrcode,
                "qrcode_url": qrcode_url,
                "base_url": base_url,
            }
            return json.dumps({"status": "success", "qrcode_url": qrcode_url, "qr_image": qr_image})
        except Exception as e:
            logger.error(f"[WebChannel] WeixinQr GET error: {e}")
            return json.dumps({"status": "error", "message": str(e)})

    def POST(self):
        _require_sensitive_local_access()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data())
            action = body.get("action", "poll")

            if action == "poll":
                return self._poll_status()
            elif action == "refresh":
                return self.GET()
            elif action == "unbind":
                return self._unbind()
            else:
                return json.dumps({"status": "error", "message": f"unknown action: {action}"})
        except Exception as e:
            logger.error(f"[WebChannel] WeixinQr POST error: {e}")
            return json.dumps({"status": "error", "message": str(e)})

    def _unbind(self):
        """Remove saved WeChat identity while keeping the channel available for re-scan."""
        cred_path = get_weixin_credentials_path()
        removed = False
        for path in (cred_path, cred_path + ".tmp"):
            try:
                if os.path.exists(path):
                    os.remove(path)
                    removed = True
            except OSError as error:
                logger.warning(f"[WebChannel] Unable to remove WeChat credential {path}: {error}")
                return json.dumps({"status": "error", "message": f"无法删除微信登录凭证：{error}"}, ensure_ascii=False)

        from channel.weixin.weixin_api import DEFAULT_BASE_URL
        conf()["weixin_token"] = ""
        conf()["weixin_base_url"] = DEFAULT_BASE_URL
        config_path = os.path.join(get_data_root(), "config.json")
        file_cfg = _read_config_file_for_write()
        file_cfg["weixin_token"] = ""
        file_cfg["weixin_base_url"] = DEFAULT_BASE_URL
        with open(config_path, "w", encoding="utf-8") as handle:
            json.dump(file_cfg, handle, indent=4, ensure_ascii=False)

        WeixinQrHandler._qr_state = {}
        running = self._get_running_channel()
        if running:
            try:
                running.stop()
                running.login_status = running.LOGIN_STATUS_IDLE
                running._current_qr_url = ""
            except Exception as error:
                logger.warning(f"[WebChannel] Failed to stop WeChat while unbinding: {error}")
        logger.info(f"[WebChannel] WeChat account unbound (credential removed={removed})")
        return json.dumps({"status": "success", "removed": removed}, ensure_ascii=False)

    def _poll_status(self):
        state = WeixinQrHandler._qr_state
        qrcode = state.get("qrcode", "")
        base_url = state.get("base_url", "")
        if not qrcode:
            return json.dumps({"status": "error", "message": "No active QR session"})

        from channel.weixin.weixin_api import WeixinApi, DEFAULT_BASE_URL
        api = WeixinApi(base_url=base_url or DEFAULT_BASE_URL)
        try:
            status_resp = api.poll_qr_status(qrcode, timeout=10)
        except Exception as e:
            return json.dumps({"status": "error", "message": str(e)})

        qr_status = status_resp.get("status", "wait")

        if qr_status == "confirmed":
            bot_token = status_resp.get("bot_token", "")
            bot_id = status_resp.get("ilink_bot_id", "")
            result_base_url = status_resp.get("baseurl", base_url)
            user_id = status_resp.get("ilink_user_id", "")

            if not bot_token or not bot_id:
                return json.dumps({"status": "error", "message": "Login confirmed but missing token"})

            cred_path = get_weixin_credentials_path()
            from channel.weixin.weixin_channel import _save_credentials
            _save_credentials(cred_path, {
                "token": bot_token,
                "base_url": result_base_url,
                "bot_id": bot_id,
                "user_id": user_id,
            })
            if user_id:
                from channel.channel_access_service import get_channel_access_service
                get_channel_access_service().auto_approve_owner("weixin", user_id)
            conf()["weixin_token"] = bot_token
            conf()["weixin_base_url"] = result_base_url

            WeixinQrHandler._qr_state = {}
            logger.info(f"[WebChannel] WeChat QR login confirmed: bot_id={bot_id}")

            return json.dumps({
                "status": "success",
                "qr_status": "confirmed",
                "bot_id": bot_id,
            })

        if qr_status == "expired":
            new_resp = api.fetch_qr_code()
            new_qrcode = new_resp.get("qrcode", "")
            new_qrcode_url = new_resp.get("qrcode_img_content", "")
            new_qr_image = self._qr_to_data_uri(new_qrcode_url)
            WeixinQrHandler._qr_state["qrcode"] = new_qrcode
            WeixinQrHandler._qr_state["qrcode_url"] = new_qrcode_url
            return json.dumps({
                "status": "success",
                "qr_status": "expired",
                "qrcode_url": new_qrcode_url,
                "qr_image": new_qr_image,
            })

        return json.dumps({"status": "success", "qr_status": qr_status})


class FeishuRegisterHandler:
    """飞书智能体应用一键创建（OAuth 设备授权流，基于 lark.register_app SDK）。

    GET  /api/feishu/register   → 启动注册：调用 SDK 生成二维码 URL，立即返回；
                                   后台线程继续轮询飞书侧直到用户扫码授权。
    POST /api/feishu/register   → 轮询当前会话状态（downloading / pending / done /
                                   error / expired）。桌面版首次启用时要先下载飞书
                                   SDK 包，此时二维码尚不存在，改由轮询补发。
                                   注册成功后不直接写 config，由前端再调
                                   /api/channels {action:'connect'} 走标准启用流程。
    """

    # 进程内单例状态（{url, expire_in, status, app_id, app_secret, error, thread}）。
    # 简单的本地自部署场景下不需要 session 隔离。
    _state = {}
    _lock = threading.Lock()

    @staticmethod
    def _qr_to_data_uri(data: str) -> str:
        """复用 WeixinQrHandler 的二维码渲染。"""
        return WeixinQrHandler._qr_to_data_uri(data)

    @classmethod
    def _reset_state(cls):
        with cls._lock:
            cls._state = {}

    @classmethod
    def _start_register_thread(cls):
        """启动一次新的注册会话。如已有进行中的会话，先取消（通过 cancel_event）。"""
        # 先取消可能存在的上一次会话，避免两个 SDK 线程并发 poll 同一个端点
        with cls._lock:
            old_cancel = cls._state.get("cancel_event") if cls._state else None
            if old_cancel is not None:
                old_cancel.set()
            cancel_event = threading.Event()
            cls._state = {"status": "starting", "cancel_event": cancel_event}

        def _worker():
            try:
                # Desktop builds don't bundle lark_oapi; fetch it on demand the
                # first time the user enables Feishu (requires network). Flag it
                # so the modal explains the wait instead of just spinning.
                from channel.feishu import lark_install
                if lark_install.needs_download():
                    with cls._lock:
                        cls._state["status"] = "downloading"
                lark_install.ensure(allow_install=True)
                import lark_oapi as lark
            except ImportError as e:
                with cls._lock:
                    cls._state["status"] = "error"
                    cls._state["error"] = (
                        "飞书 SDK 不可用，请联网后重试，"
                        "或手动执行 pip install -U 'lark-oapi>=1.5.5'（%s）" % e
                    )
                return

            def _on_qr(info):
                # SDK 拿到二维码 URL 后立即回调；写入 state 让前端 GET 立刻能拿到
                with cls._lock:
                    cls._state["url"] = info.get("url", "")
                    cls._state["expire_in"] = info.get("expire_in", 600)
                    cls._state["qr_image"] = cls._qr_to_data_uri(info.get("url", ""))
                    cls._state["status"] = "pending"
                logger.info(f"[FeishuRegister] QR ready, expire_in={info.get('expire_in')}s")

            def _on_status(info):
                # 过滤掉 polling 心跳（每 5 秒一次，纯噪音）；
                # 保留 slow_down / domain_switched 等真正的状态切换事件
                status = info.get("status")
                if status == "polling":
                    return
                logger.info(f"[FeishuRegister] SDK status: {info}")

            try:
                result = lark.register_app(
                    on_qr_code=_on_qr,
                    on_status_change=_on_status,
                    source="cowagent",
                    cancel_event=cancel_event,
                )
                with cls._lock:
                    cls._state["status"] = "done"
                    cls._state["app_id"] = result.get("client_id", "")
                    cls._state["app_secret"] = result.get("client_secret", "")
                logger.info(f"[FeishuRegister] App created: app_id={result.get('client_id')}")
            except Exception as e:
                err_msg = str(e)
                err_cls = e.__class__.__name__
                # 飞书 SDK 抛出的 AppExpiredError / AppAccessDeniedError / RegisterAppError
                if "Expired" in err_cls:
                    status = "expired"
                elif "Denied" in err_cls:
                    status = "denied"
                elif "abort" in err_msg.lower() or "cancel" in err_msg.lower():
                    # 被新一轮注册抢占，保持安静
                    return
                else:
                    status = "error"
                with cls._lock:
                    # 仅当当前 state 仍属于本次 worker 时才写入，避免覆盖更新的会话
                    if cls._state.get("cancel_event") is cancel_event:
                        cls._state["status"] = status
                        cls._state["error"] = err_msg
                logger.warning(f"[FeishuRegister] Register failed ({err_cls}): {err_msg}")

        threading.Thread(target=_worker, daemon=True, name="feishu-register").start()

    def GET(self):
        """启动一次新的注册会话。如果已有 pending/done 会话则覆盖。"""
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            self._start_register_thread()
            # 等待 SDK 拿到二维码 URL（最多 10s）。SDK 内部会马上回调 _on_qr。
            import time as _t
            for _ in range(100):
                with self._lock:
                    if self._state.get("url") or self._state.get("status") in (
                        "downloading", "error", "expired", "denied"
                    ):
                        break
                _t.sleep(0.1)
            with self._lock:
                if self._state.get("status") in ("error", "expired", "denied"):
                    return json.dumps({
                        "status": "error",
                        "message": self._state.get("error", "register failed"),
                    })
                if self._state.get("status") == "downloading":
                    # The SDK bundle is still coming down; the QR only exists
                    # once it lands, so hand the frontend over to polling.
                    return json.dumps({
                        "status": "success",
                        "register_status": "downloading",
                    })
                if not self._state.get("url"):
                    return json.dumps({
                        "status": "error",
                        "message": "等待飞书二维码超时，请重试",
                    })
                return json.dumps({
                    "status": "success",
                    "qrcode_url": self._state["url"],
                    "qr_image": self._state.get("qr_image", ""),
                    "expire_in": self._state.get("expire_in", 600),
                })
        except Exception as e:
            logger.error(f"[WebChannel] FeishuRegister GET error: {e}")
            return json.dumps({"status": "error", "message": str(e)})

    def POST(self):
        """轮询注册结果。"""
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = body.get("action", "poll")
            if action != "poll":
                return json.dumps({"status": "error", "message": f"unknown action: {action}"})

            with self._lock:
                status = self._state.get("status", "idle")
                if status == "done":
                    payload = {
                        "status": "success",
                        "register_status": "done",
                        "app_id": self._state.get("app_id", ""),
                        "app_secret": self._state.get("app_secret", ""),
                    }
                    # 一次性返回凭据后清掉，避免敏感信息长期驻留内存
                    self._state = {}
                    return json.dumps(payload)
                if status in ("error", "expired", "denied"):
                    return json.dumps({
                        "status": "success",
                        "register_status": status,
                        "message": self._state.get("error", ""),
                    })
                if status == "downloading":
                    return json.dumps({
                        "status": "success",
                        "register_status": "downloading",
                    })
                # pending / starting：还在等用户扫码。二维码可能是在 GET 返回
                # "downloading" 之后才生成的，带上让前端补渲染。
                payload = {"status": "success", "register_status": "pending"}
                if self._state.get("url"):
                    payload["qrcode_url"] = self._state["url"]
                    payload["qr_image"] = self._state.get("qr_image", "")
                return json.dumps(payload)
        except Exception as e:
            logger.error(f"[WebChannel] FeishuRegister POST error: {e}")
            return json.dumps({"status": "error", "message": str(e)})


class ToolsHandler:
    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            from agent.tools.tool_manager import ToolManager
            from agent.tools.reliability import ToolReliability
            from common import i18n
            tm = ToolManager()
            if not tm.tool_classes:
                tm.load_tools()
            catalog = tm.tool_catalog()
            health = tm.health_report()
            try:
                from intelligence_center.scrapling_adapter import scrapling_status
                scrapling = scrapling_status()
                catalog.setdefault("providers", []).append({
                    "id": "cli:scrapling",
                    "name": "Scrapling 网页提取",
                    "type": "cli",
                    "status": "ready" if scrapling.get("ready") else "missing_runtime",
                    "ready_count": 1 if scrapling.get("ready") else 0,
                    "tool_count": 1,
                    "transports": ["python"],
                })
                health.setdefault("checks", []).append({
                    "id": "cli:scrapling",
                    "provider": "cli",
                    "name": "Scrapling 网页提取",
                    "status": "ready" if scrapling.get("ready") else "missing_runtime",
                    "message": scrapling.get("message") or "",
                    "repairable": False,
                    "browser_ready": bool(scrapling.get("browser_ready")),
                    "mcp_ready": bool(scrapling.get("mcp_ready")),
                    "install_hint": scrapling.get("install_hint"),
                    "risk_note": scrapling.get("risk_note"),
                })
                health["total"] = len(health.get("checks") or [])
                health["issues"] = sum(1 for item in health.get("checks") or [] if item.get("status") in {"failed", "invalid_config", "missing_runtime"})
                health["status"] = "degraded" if health["issues"] else "healthy"
            except Exception as scrapling_error:
                logger.warning(f"[WebChannel] Scrapling health append skipped: {scrapling_error}")
            tools = catalog["tools"]
            lang = i18n.get_language()
            for item in tools:
                name = item.get("name", "")
                desc = item.get("description", "")
                if lang == i18n.ZH_HANT and desc:
                    item["description"] = i18n.to_traditional(desc)
                elif lang == "en" and name == "scheduler":
                    item["description"] = (
                            "Create, query and manage scheduled tasks (reminders, periodic tasks, etc.).\n\n"
                            "⚠️ IMPORTANT: Only use this tool when delayed or periodic execution is needed."
                        )
            return json.dumps({
                "status": "success",
                **catalog,
                "health": health,
                "reliability": ToolReliability().dashboard(),
            }, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Tools API error: {e}")
            return json.dumps({"status": "error", "message": str(e)})


class SkillsHandler:
    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            from agent.skills.service import SkillService
            from agent.skills.manager import SkillManager
            from common import i18n
            workspace_root = _get_workspace_root()
            runtime_bin = os.path.join(workspace_root, ".skill-runtime", "node", "node_modules", ".bin")
            if os.path.isdir(runtime_bin) and runtime_bin not in os.environ.get("PATH", "").split(os.pathsep):
                os.environ["PATH"] = runtime_bin + os.pathsep + os.environ.get("PATH", "")
            # Restore the Node location used by the bundled pnpm launcher after
            # every app restart; otherwise installed CLI shims exist but cannot run.
            if os.name == "nt" and not shutil.which("node"):
                from pathlib import Path
                pnpm_path = shutil.which("pnpm")
                if pnpm_path:
                    for parent in [os.path.dirname(pnpm_path), *list(Path(pnpm_path).parents)[:5]]:
                        node_dir = os.path.join(str(parent), "node", "bin")
                        if os.path.isfile(os.path.join(node_dir, "node.exe")):
                            os.environ["PATH"] = node_dir + os.pathsep + os.environ.get("PATH", "")
                            break
            manager = SkillManager(custom_dir=os.path.join(workspace_root, "skills"))
            service = SkillService(manager)
            skills = service.query()
            for skill in skills:
                skill_dir = os.path.join(workspace_root, "skills", str(skill.get("name") or ""))
                skill_file = os.path.join(skill_dir, "SKILL.md")
                content = ""
                try:
                    with open(skill_file, "r", encoding="utf-8") as handle: content = handle.read(12000)
                except OSError: pass
                lowered = content.lower()
                permissions = []
                for key, label in (("browser", "浏览器"), ("email", "邮箱"), ("filesystem", "文件"), ("shell", "命令执行"), ("api", "外部 API"), ("write", "写入操作")):
                    if key in lowered: permissions.append(label)
                skill["permissions"] = permissions
                skill["dependencies"] = sorted(set(re.findall(r"(?:requires?|dependencies?)\s*[:：]\s*([^\n]+)", content, re.IGNORECASE)))[:5]
                skill["version"] = next(iter(re.findall(r"(?:version|版本)\s*[:：]\s*([\w.\-]+)", content, re.IGNORECASE)), "未标注")
                # A Skill can be installed while the CLI/runtime it documents
                # is still missing.  Frontmatter such as
                # ``Bash(agent-browser:*)`` describes that external runtime;
                # expose it separately so "enabled" is not mistaken for
                # "ready to execute".
                runtime_commands = []
                for raw in re.findall(r"Bash\(([^:)\s]+)", content, re.IGNORECASE):
                    command = str(raw or "").strip()
                    if command and command.lower() not in {"bash", "cmd", "powershell", "pwsh"}:
                        runtime_commands.append(command)
                runtime_commands = list(dict.fromkeys(runtime_commands))
                if runtime_commands:
                    available = [cmd for cmd in runtime_commands if shutil.which(cmd)]
                    skill["runtime_commands"] = runtime_commands
                    skill["runtime_ready"] = bool(available)
                    skill["runtime_available"] = available
                    if not available:
                        skill["runtime_issue"] = f"缺少运行命令：{' / '.join(runtime_commands)}"
                        install_match = re.search(
                            r"(?:Install|安装)\s*[:：]\s*`?(?:npm|pnpm)\s+(?:i|install|add)\s+(?:-g\s+)?([@\w./-]+)",
                            content,
                            re.IGNORECASE,
                        )
                        package = install_match.group(1) if install_match else ""
                        safe_package = bool(re.fullmatch(r"(?:@[a-z0-9_.-]+/)?[a-z0-9_.-]+", package, re.IGNORECASE))
                        skill["runtime_repairable"] = safe_package and bool(shutil.which("pnpm"))
                        skill["runtime_install_hint"] = (
                            f"系统将为 CowAgent 单独安装 {package}，不会修改你的项目依赖。"
                            if safe_package else
                            "该技能没有提供可安全识别的一键安装方式，请查看技能说明中的依赖章节。"
                        )
            if i18n.get_language() == i18n.ZH_HANT:
                for skill in skills:
                    if isinstance(skill, dict):
                        for k, v in list(skill.items()):
                            if k in ("name", "description", "display_name") and isinstance(v, str):
                                skill[k] = i18n.to_traditional(v)
            params = web.input(query='')
            query = str(params.query or '').strip().lower()
            results = []
            market_statuses = {}
            from intelligence_center.skill_market_service import MARKETS
            if query:
                for skill in skills:
                    tags = list(skill.get("tags") or [])
                    haystack = " ".join(str(skill.get(key) or "") for key in ("name", "display_name", "description", "category")) + " " + " ".join(tags)
                    if query in haystack.lower():
                        results.append({
                            "id": f"local:{skill.get('name')}",
                            "name": skill.get("name"),
                            "display_name": skill.get("display_name") or skill.get("name"),
                            "description": skill.get("description") or "本地已安装技能",
                            "tags": tags or ["本地", "已安装"],
                            "provider": "本地技能",
                            "provider_name": "已安装",
                            "installed": True,
                            "enabled": bool(skill.get("enabled", True)),
                            "source": skill.get("source") or "custom",
                            "can_uninstall": (skill.get("source") or "custom") not in {"builtin", "custom"},
                            "runtime_ready": skill.get("runtime_ready"),
                            "runtime_issue": skill.get("runtime_issue", ""),
                            "command": "",
                        })
                try:
                    from cli.commands.skill import _ignore_unreachable_launcher_proxy
                    from intelligence_center.skill_market_service import search_skill_markets
                    _ignore_unreachable_launcher_proxy()
                    market_results, market_statuses = search_skill_markets(str(params.query))
                    installed_names = {str(item.get("name") or "") for item in skills}
                    for item in market_results:
                        item["installed"] = str(item.get("name") or "") in installed_names
                    results.extend(market_results)
                    # Installed skills always lead.  Everything else is ranked
                    # globally by popularity instead of being grouped by
                    # marketplace, so the most-used candidates surface first.
                    results.sort(key=lambda item: (
                        0 if item.get("installed") else 1,
                        -(int(item.get("downloads") or 0)),
                        str(item.get("display_name") or item.get("name") or "").casefold(),
                    ))
                except Exception as search_error:
                    logger.warning(f"[WebChannel] Skill market aggregation unavailable: {search_error}")
            try:
                training = Agent2Handler._service().self_training_status()
                self_training_candidates = training.get("skill_candidates", [])
                self_training_drafts = training.get("skill_drafts", [])
            except Exception:
                self_training_candidates = []
                self_training_drafts = []
            return json.dumps({"status": "success", "skills": skills, "results": results, "query": params.query, "markets": MARKETS, "market_statuses": market_statuses, "self_training_candidates": self_training_candidates, "self_training_drafts": self_training_drafts}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Skills API error: {e}")
            return json.dumps({"status": "error", "message": str(e)})

    def POST(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            from agent.skills.service import SkillService
            from agent.skills.manager import SkillManager
            body = json.loads(web.data())
            action = body.get("action")
            name = body.get("name")
            if action == "install":
                source = str(body.get("source") or name or "").strip()
                from cli.commands.skill import install_skill, normalize_skill_install_source
                source = normalize_skill_install_source(source)
                if not source:
                    return json.dumps({"status": "error", "message": "请输入技能名称或安装来源"}, ensure_ascii=False)
                result = install_skill(source)
                if result.error:
                    return json.dumps({"status": "error", "message": result.error, "messages": result.messages}, ensure_ascii=False)
                return json.dumps({"status": "success", "installed": result.installed, "messages": result.messages}, ensure_ascii=False)
            if not action or not name:
                return json.dumps({"status": "error", "message": "action and name are required"})
            workspace_root = _get_workspace_root()
            manager = SkillManager(custom_dir=os.path.join(workspace_root, "skills"))
            service = SkillService(manager)
            if action == "repair_runtime":
                import subprocess
                from pathlib import Path
                skill_file = os.path.join(workspace_root, "skills", str(name), "SKILL.md")
                try:
                    with open(skill_file, "r", encoding="utf-8") as handle:
                        content = handle.read(20000)
                except OSError:
                    return json.dumps({"status":"error","message":"技能说明文件不存在"},ensure_ascii=False)
                commands = list(dict.fromkeys(re.findall(r"Bash\(([^:)\s]+)", content, re.IGNORECASE)))
                missing = [cmd for cmd in commands if cmd.lower() not in {"bash","cmd","powershell","pwsh"} and not shutil.which(cmd)]
                if not missing:
                    return json.dumps({"status":"success","message":"运行环境已经可用"},ensure_ascii=False)
                match = re.search(r"(?:Install|安装)\s*[:：]\s*`?(?:npm|pnpm)\s+(?:i|install|add)\s+(?:-g\s+)?([@\w./-]+)",content,re.IGNORECASE)
                package = match.group(1) if match else ""
                if not re.fullmatch(r"(?:@[a-z0-9_.-]+/)?[a-z0-9_.-]+",package,re.IGNORECASE):
                    return json.dumps({"status":"error","message":"该技能没有提供可安全识别的一键安装命令，请查看技能说明。"},ensure_ascii=False)
                pnpm = shutil.which("pnpm")
                if not pnpm:
                    return json.dumps({"status":"error","message":"CowAgent 当前缺少受支持的 pnpm 安装器。"},ensure_ascii=False)
                runtime_root = os.path.join(workspace_root, ".skill-runtime", "node")
                os.makedirs(runtime_root, exist_ok=True)
                argv = [pnpm, "add", "--dir", runtime_root, package]
                if os.name == "nt" and pnpm.lower().endswith((".cmd", ".bat")):
                    argv = [os.environ.get("COMSPEC", "cmd.exe"), "/d", "/s", "/c", *argv]
                try:
                    completed = subprocess.run(argv, capture_output=True, text=True, timeout=300, encoding="utf-8", errors="replace")
                except subprocess.TimeoutExpired:
                    return json.dumps({"status":"error","message":"安装超过 5 分钟仍未完成，请检查网络后重试。"},ensure_ascii=False)
                if completed.returncode != 0:
                    detail = (completed.stderr or completed.stdout or "安装失败").strip()[-1500:]
                    return json.dumps({"status":"error","message":detail},ensure_ascii=False)
                runtime_bin = os.path.join(runtime_root, "node_modules", ".bin")
                if runtime_bin not in os.environ.get("PATH", "").split(os.pathsep):
                    os.environ["PATH"] = runtime_bin + os.pathsep + os.environ.get("PATH", "")
                # Some bundled pnpm launchers keep Node outside the public PATH.
                # Discover the sibling runtime so npm CLI shims can actually start.
                if not shutil.which("node") and os.name == "nt":
                    pnpm_path = os.path.abspath(pnpm)
                    for parent in [os.path.dirname(pnpm_path), *list(Path(pnpm_path).parents)[:5]]:
                        node_dir = os.path.join(str(parent), "node", "bin")
                        if os.path.isfile(os.path.join(node_dir, "node.exe")):
                            os.environ["PATH"] = node_dir + os.pathsep + os.environ.get("PATH", "")
                            break
                # allowed-tools frequently lists equivalent launch forms such as
                # `agent-browser` and `npx agent-browser`; any usable form is enough.
                available = [cmd for cmd in commands if shutil.which(cmd)]
                if not available:
                    return json.dumps({"status":"error","message":f"软件包已安装，但仍找不到可用运行命令：{' / '.join(missing)}"},ensure_ascii=False)
                selected = available[0]
                try:
                    check = subprocess.run([shutil.which(selected), "--version"], capture_output=True, text=True, timeout=20, encoding="utf-8", errors="replace")
                except (OSError, subprocess.TimeoutExpired) as verify_error:
                    logger.warning(f"[WebChannel] Skill runtime verify failed for {name}: {verify_error}")
                    return json.dumps({"status":"error","message":"安装已完成，但运行验证失败。请重试；若仍失败，请查看系统日志。"},ensure_ascii=False)
                if check.returncode != 0:
                    logger.warning(f"[WebChannel] Skill runtime verify failed for {name}: {(check.stderr or check.stdout)[-1500:]}")
                    return json.dumps({"status":"error","message":"安装已完成，但运行命令未能正常启动。请在系统日志中查看详细原因。"},ensure_ascii=False)
                return json.dumps({"status":"success","message":f"{name} 运行环境修复成功，已通过启动验证","installed_package":package,"available_command":selected},ensure_ascii=False)
            if action == "open":
                service.open({"name": name})
            elif action == "close":
                service.close({"name": name})
            elif action == "delete":
                current = next((item for item in service.query() if item.get("name") == name), {})
                if current.get("source") in {"builtin", "custom"}:
                    return json.dumps({"status":"error","message":"内置或本地自定义技能不能在这里卸载"},ensure_ascii=False)
                service.delete({"name": name})
            elif action == "update":
                source = str(body.get("source") or "").strip()
                if not source: return json.dumps({"status":"error","message":"更新时需要提供原 Skill Hub 名称或仓库地址"},ensure_ascii=False)
                from cli.commands.skill import install_skill
                result = install_skill(source)
                if result.error: return json.dumps({"status":"error","message":result.error},ensure_ascii=False)
                return json.dumps({"status":"success","installed":result.installed},ensure_ascii=False)
            else:
                return json.dumps({"status": "error", "message": f"unknown action: {action}"})
            return json.dumps({"status": "success"}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Skills POST error: {e}")
            return json.dumps({"status": "error", "message": str(e)})


class BrowserRuntimeHandler:
    def _status(self):
        runtime = {}
        try:
            runtime = _activate_isolated_skill_runtime(_get_workspace_root())
        except Exception as error:
            logger.warning(f"[WebChannel] Browser runtime env activation skipped: {error}")
        playwright_ok = False
        try:
            import playwright  # noqa: F401
            playwright_ok = True
        except Exception:
            playwright_ok = False
        browsers = {
            "chrome": shutil.which("chrome") or shutil.which("chrome.exe") or shutil.which("google-chrome"),
            "msedge": shutil.which("msedge") or shutil.which("msedge.exe"),
            "agent_browser": shutil.which("agent-browser"),
        }
        ready = playwright_ok or bool(browsers.get("chrome") or browsers.get("msedge") or browsers.get("agent_browser"))
        missing = []
        if not playwright_ok:
            missing.append("Playwright")
        if not (browsers.get("chrome") or browsers.get("msedge") or browsers.get("agent_browser")):
            missing.append("Chrome/Edge 或 agent-browser")
        return {
            "ready": ready,
            "playwright": playwright_ok,
            "browsers": browsers,
            "runtime": runtime,
            "missing": missing,
            "message": "浏览器运行环境可用" if ready else "浏览器运行环境未就绪",
        }

    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            return json.dumps({"status": "success", **self._status()}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Browser runtime status error: {e}")
            return json.dumps({"status": "error", "message": str(e)}, ensure_ascii=False)

    def POST(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "repair")
            if action != "repair":
                return json.dumps({"status": "error", "message": f"unknown action: {action}"}, ensure_ascii=False)
            before = self._status()
            if before.get("ready"):
                return json.dumps({"status": "success", **before}, ensure_ascii=False)
            try:
                from cli.commands.install import run_install_browser
                code = run_install_browser()
            except Exception as install_error:
                logger.error(f"[WebChannel] Browser runtime repair error: {install_error}")
                return json.dumps({"status": "error", "message": f"浏览器运行环境修复失败：{install_error}", "before": before}, ensure_ascii=False)
            after = self._status()
            if code == 0 and after.get("ready"):
                return json.dumps({"status": "success", **after, "message": "浏览器运行环境修复成功"}, ensure_ascii=False)
            return json.dumps({"status": "error", "message": "已执行修复，但浏览器运行环境仍未就绪。请查看系统日志或切换人工接管。", "before": before, "after": after, "exit_code": code}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Browser runtime repair POST error: {e}")
            return json.dumps({"status": "error", "message": str(e)}, ensure_ascii=False)


