    def _candidate_roots(self):
        roots = []
        for raw in (_get_workspace_root(), os.getcwd(), os.path.dirname(sys.executable)):
            if raw:
                roots.append(os.path.abspath(raw))
        try:
            current = os.path.abspath(os.path.dirname(sys.executable))
            for _ in range(10):
                roots.append(current)
                parent = os.path.dirname(current)
                if parent == current:
                    break
                current = parent
        except Exception:
            pass
        try:
            current = os.path.abspath(os.getcwd())
            for _ in range(6):
                roots.append(current)
                parent = os.path.dirname(current)
                if parent == current:
                    break
                current = parent
        except Exception:
            pass
        seen = set()
        result = []
        for root in roots:
            key = root.lower()
            if key not in seen:
                seen.add(key)
                result.append(root)
        return result

    def _activate_env(self):
        try:
            return _activate_isolated_skill_runtime(_get_workspace_root())
        except Exception as error:
            logger.warning(f"[WebChannel] Agent-Reach runtime env activation skipped: {error}")
            return {}

    def _command(self, name):
        try:
            found = shutil.which(name)
            if found:
                return found
            script_dir = os.path.dirname(sys.executable)
            candidates = [os.path.join(script_dir, name)]
            for root in self._candidate_roots():
                if os.name == "nt":
                    candidates.extend([
                        os.path.join(root, ".venv", "Scripts", name),
                        os.path.join(root, ".venv", "Scripts", f"{name}.exe"),
                        os.path.join(root, ".venv", "Scripts", f"{name}.cmd"),
                    ])
                else:
                    candidates.append(os.path.join(root, ".venv", "bin", name))
            if os.name == "nt":
                candidates.extend([
                    os.path.join(script_dir, f"{name}.exe"),
                    os.path.join(script_dir, f"{name}.cmd"),
                    os.path.join(script_dir, f"{name}.bat"),
                ])
            for candidate in candidates:
                if os.path.isfile(candidate):
                    return candidate
        except Exception:
            return None
        return None

    def _run(self, args, timeout=60, env=None):
        import subprocess
        run_env = (env or os.environ.copy()).copy()
        script_dir = os.path.dirname(sys.executable)
        if script_dir and script_dir not in run_env.get("PATH", "").split(os.pathsep):
            run_env["PATH"] = script_dir + os.pathsep + run_env.get("PATH", "")
        completed = subprocess.run(
            args,
            capture_output=True,
            text=True,
            timeout=timeout,
            encoding="utf-8",
            errors="replace",
            env=run_env,
        )
        output = "\n".join(part for part in [completed.stdout, completed.stderr] if part).strip()
        return completed.returncode, output[-8000:]

    def _python_executable(self):
        candidates = []
        for root in self._candidate_roots():
            if os.name == "nt":
                candidates.append(os.path.join(root, ".venv", "Scripts", "python.exe"))
            else:
                candidates.append(os.path.join(root, ".venv", "bin", "python"))
        candidates.append(sys.executable)
        for candidate in candidates:
            try:
                if candidate and os.path.isfile(candidate):
                    return candidate
            except Exception:
                continue
        return sys.executable

    def _install_temp_dir(self):
        candidates = []
        local_app = os.environ.get("LOCALAPPDATA")
        if local_app:
            candidates.append(os.path.join(local_app, "CowAgent", "Temp", "agent-reach"))
        user_profile = os.environ.get("USERPROFILE")
        if user_profile:
            candidates.append(os.path.join(user_profile, "AppData", "Local", "CowAgent", "Temp", "agent-reach"))
        candidates.append(os.path.join(_get_workspace_root(), "agent_reach_tmp"))
        candidates.append(os.path.join(_get_workspace_root(), ".agent-reach-tmp"))
        for path in candidates:
            try:
                os.makedirs(path, exist_ok=True)
                probe = os.path.join(path, ".write_test")
                with open(probe, "w", encoding="utf-8") as handle:
                    handle.write("ok")
                try:
                    os.remove(probe)
                except OSError:
                    pass
                return path
            except Exception:
                continue
        return os.environ.get("TEMP") or os.environ.get("TMP") or _get_workspace_root()

    def _short_path(self, path):
        if os.name != "nt":
            return path
        try:
            import ctypes
            buffer = ctypes.create_unicode_buffer(4096)
            result = ctypes.windll.kernel32.GetShortPathNameW(str(path), buffer, len(buffer))
            if result:
                return buffer.value
        except Exception:
            pass
        return path

    def _config_path(self):
        base = os.path.join(get_data_root(), "integrations")
        os.makedirs(base, exist_ok=True)
        return os.path.join(base, self.CONFIG_FILE)

    def _health_path(self):
        base = os.path.join(get_data_root(), "intelligence_center")
        os.makedirs(base, exist_ok=True)
        return os.path.join(base, "agent_reach_health.json")

    def _persist_health(self, payload):
        try:
            item = {
                "checked_at": datetime.datetime.now().astimezone().isoformat(timespec="seconds"),
                "installed": bool(payload.get("installed")),
                "command": payload.get("command") or "",
                "doctor_ok": bool(payload.get("doctor_ok")),
                "message": payload.get("message") or "",
                "doctor_output": str(payload.get("doctor_output") or "")[-1500:],
                "enabled_sources": payload.get("enabled_sources") or [],
                "degraded_sources": payload.get("degraded_sources") or [],
                "source_strategy": payload.get("source_strategy") or {},
                "preflight_summary": payload.get("preflight_summary") or {},
                "fallback": "复杂来源不可用时自动降级到普通搜索/RSS，并把失败写入训练样本。",
            }
            with open(self._health_path(), "w", encoding="utf-8") as handle:
                json.dump(item, handle, ensure_ascii=False, indent=2)
        except Exception as error:
            logger.debug(f"[AgentReach] persist health skipped: {error}")

    def _load_configs(self):
        path = self._config_path()
        if not os.path.exists(path):
            return {}
        try:
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            return data if isinstance(data, dict) else {}
        except Exception as error:
            logger.warning(f"[WebChannel] Agent-Reach config load failed: {error}")
            return {}

    def _save_configs(self, data):
        path = self._config_path()
        tmp = f"{path}.tmp"
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(data, handle, ensure_ascii=False, indent=2)
        os.replace(tmp, path)

    def _mask_secret(self, value):
        value = str(value or "")
        if not value:
            return ""
        if len(value) <= 8:
            return "*" * len(value)
        return f"{value[:4]}{'*' * max(4, len(value) - 8)}{value[-4:]}"

    def _safe_configs_for_ui(self):
        configs = self._load_configs()
        result = {}
        for pid, item in configs.items():
            if not isinstance(item, dict):
                continue
            secret = item.get("secret") or item.get("token") or item.get("cookie") or ""
            result[pid] = {
                "platform": pid,
                "enabled": bool(item.get("enabled", True)),
                "auth_type": item.get("auth_type", "token"),
                "account": item.get("account", ""),
                "cookie_file": item.get("cookie_file", ""),
                "note": item.get("note", ""),
                "configured": bool(secret or item.get("cookie_file")),
                "secret_masked": self._mask_secret(secret),
            }
        return result

    def _capability_meta(self, pid, fallback_name=""):
        meta = dict(self.SOURCE_CAPABILITIES.get(pid) or {})
        if not meta:
            meta = {
                "name": fallback_name or pid,
                "category": "其他来源",
                "icon": "fa-link",
                "zero_config": False,
                "permission_scope": "按平台配置",
                "risk": "中",
                "backends": ["Agent-Reach"],
                "fallback_backends": ["普通网页搜索"],
                "use_cases": ["补充检索"],
                "recommended_for": ["深度研究"],
            }
        return meta

    def _configured(self, configs, pid):
        cfg = configs.get(pid, {}) if isinstance(configs.get(pid), dict) else {}
        return bool(cfg.get("secret") or cfg.get("cookie_file"))

    def _source_catalog(self, platforms):
        by_id = {item.get("id"): item for item in (platforms or []) if isinstance(item, dict)}
        catalog = []
        for pid, meta in self.SOURCE_CAPABILITIES.items():
            item = by_id.get(pid, {})
            ready = bool(item.get("ready"))
            configured = bool(item.get("configured"))
            requires_config = bool(item.get("requires_config"))
            if ready:
                status = "ready"
                status_label = "可用"
            elif requires_config:
                status = "needs_config" if not configured else "configured_but_inactive"
                status_label = "需配置" if not configured else "已配置待检测"
            else:
                status = "unavailable"
                status_label = "待安装"
            catalog.append({
                "id": pid,
                "name": meta.get("name") or item.get("name") or pid,
                "category": meta.get("category") or "其他来源",
                "icon": meta.get("icon") or "fa-link",
                "ready": ready,
                "configured": configured,
                "requires_config": requires_config,
                "status": status,
                "status_label": status_label,
                "command": item.get("command") or "",
                "hint": item.get("hint") or self.PLATFORM_HINTS.get(pid) or "安装 Agent-Reach 后可作为来源使用。",
                "zero_config": bool(meta.get("zero_config")),
                "auth_required": requires_config,
                "permission_scope": meta.get("permission_scope") or "",
                "risk": meta.get("risk") or "中",
                "backends": meta.get("backends") or [],
                "fallback_backends": meta.get("fallback_backends") or [],
                "use_cases": meta.get("use_cases") or [],
                "recommended_for": meta.get("recommended_for") or [],
            })
        return catalog

    def _source_strategy(self, catalog):
        ready = [item for item in (catalog or []) if item.get("ready")]
        degraded = [item for item in (catalog or []) if item.get("requires_config") and not item.get("ready")]
        ready_ids = {item.get("id") for item in ready}
        primary = [item for item in ready if item.get("id") in {"rss", "web", "github", "v2ex", "youtube", "bilibili"}]
        if not primary:
            primary = [item for item in ready if item.get("id") in {"web", "rss"}] or ready[:3]
        fallback = []
        for item in catalog or []:
            if item.get("id") in ready_ids:
                continue
            if item.get("id") in {"web", "rss"} or item.get("fallback_backends"):
                fallback.append(item)
        return {
            "primary_sources": [item.get("id") for item in primary[:6]],
            "primary_labels": [item.get("name") for item in primary[:6]],
            "fallback_sources": [item.get("id") for item in fallback[:6]],
            "degraded_sources": [item.get("id") for item in degraded],
            "policy": "官方/RSS/网页/GitHub 优先；视频与社区补充热度；登录型平台只在已配置时启用；不可用时自动降级到普通搜索和 Web 兜底。",
            "quality_gate": [
                "必须读取原文或结构化条目后再总结",
                "同一事件去重，只保留最可靠来源",
                "登录型平台未授权时跳过，不伪造结果",
                "结果需保留可点击原文链接",
            ],
        }

    def _preflight_summary(self, catalog):
        ready = [item for item in (catalog or []) if item.get("ready")]
        needs_config = [item for item in (catalog or []) if item.get("requires_config") and not item.get("ready")]
        zero_ready = [item for item in ready if item.get("zero_config")]
        checks = [
            {
                "name": "免登录公开来源",
                "status": "success" if zero_ready else "warning",
                "message": f"已可用 {len(zero_ready)} 个：{ '、'.join([x.get('name') for x in zero_ready[:5]]) }" if zero_ready else "暂无免登录来源可用，复杂搜索会降级。",
            },
            {
                "name": "登录型来源",
                "status": "warning" if needs_config else "success",
                "message": f"{len(needs_config)} 个来源未配置授权；需要时会跳过并降级。" if needs_config else "已配置的登录型来源可参与路由。",
            },
            {
                "name": "结果质量门禁",
                "status": "success",
                "message": "已启用去重、原文链接、登录源跳过和主备源策略。",
            },
        ]
        return {
            "ready_count": len(ready),
            "zero_config_ready_count": len(zero_ready),
            "needs_config_count": len(needs_config),
            "checks": checks,
            "risk_level": "low" if len(zero_ready) >= 2 else ("medium" if ready else "high"),
        }

    def _platforms(self, installed):
        platforms = []
        configs = self._load_configs()
        optional_config = {"github", "youtube", "bilibili"}
        for pid, name, commands in self.ZERO_CONFIG_PLATFORMS:
            meta = self._capability_meta(pid, name)
            available = [cmd for cmd in commands if self._command(cmd)]
            if pid in {"web", "rss", "v2ex", "xiaoyuzhou"}:
                ready = installed
            elif pid == "github":
                ready = installed and (bool(available) or bool(configs.get(pid, {}).get("secret")))
            elif pid == "doctor":
                ready = installed
            else:
                cfg = configs.get(pid, {}) if isinstance(configs.get(pid), dict) else {}
                ready = installed and (bool(available) or bool(cfg.get("secret")) or bool(cfg.get("cookie_file")))
            platforms.append({
                "id": pid,
                "name": name,
                "ready": ready,
                "requires_config": pid in optional_config,
                "configured": self._configured(configs, pid),
                "command": ", ".join(available),
                "hint": self.PLATFORM_HINTS.get(pid, "无需配置，安装 Agent-Reach 后可直接使用。"),
                "category": meta.get("category"),
                "icon": meta.get("icon"),
                "zero_config": bool(meta.get("zero_config")),
                "permission_scope": meta.get("permission_scope"),
                "risk": meta.get("risk"),
                "backends": meta.get("backends") or [],
                "fallback_backends": meta.get("fallback_backends") or [],
                "use_cases": meta.get("use_cases") or [],
            })
        for pid, name in self.AUTH_PLATFORMS:
            meta = self._capability_meta(pid, name)
            cfg = configs.get(pid, {}) if isinstance(configs.get(pid), dict) else {}
            configured = bool(cfg.get("secret") or cfg.get("cookie_file"))
            platforms.append({
                "id": pid,
                "name": name,
                "ready": installed and configured and bool(cfg.get("enabled", True)),
                "requires_config": True,
                "configured": configured,
                "command": "已配置" if configured else "",
                "hint": self.PLATFORM_HINTS.get(pid, "需要配置 Cookie / Token 后启用。"),
                "category": meta.get("category"),
                "icon": meta.get("icon"),
                "zero_config": bool(meta.get("zero_config")),
                "permission_scope": meta.get("permission_scope"),
                "risk": meta.get("risk"),
                "backends": meta.get("backends") or [],
                "fallback_backends": meta.get("fallback_backends") or [],
                "use_cases": meta.get("use_cases") or [],
            })
        return platforms

    def _status(self, run_doctor=False):
        runtime = self._activate_env()
        command = self._command("agent-reach")
        installed = bool(command)
        doctor_output = ""
        doctor_ok = False
        if installed and run_doctor:
            try:
                code, doctor_output = self._run([command, "doctor"], timeout=80)
                doctor_ok = code == 0
            except Exception as error:
                doctor_output = str(error)
        platforms = self._platforms(installed)
        source_catalog = self._source_catalog(platforms)
        source_strategy = self._source_strategy(source_catalog)
        preflight_summary = self._preflight_summary(source_catalog)
        payload = {
            "installed": installed,
            "command": command or "",
            "runtime": runtime,
            "doctor_ok": doctor_ok,
            "doctor_output": doctor_output,
            "platforms": platforms,
            "configs": self._safe_configs_for_ui(),
            "available": bool(installed and doctor_ok),
            "fallback_strategy": "未就绪时复杂来源降级到普通搜索/RSS；同时进入 Harness 诊断和训练样本。",
            "capability_layer": True,
            "source_catalog": source_catalog,
            "source_strategy": source_strategy,
            "applications": self.APPLICATIONS,
            "preflight_summary": preflight_summary,
            "enabled_sources": [item.get("id") for item in source_catalog if item.get("ready")],
            "degraded_sources": [item.get("id") for item in source_catalog if item.get("requires_config") and not item.get("ready")],
            "recommended_next_actions": [
                "优先配置 GitHub Token 或 gh CLI，提升开源项目与 Release 检索稳定性",
                "每日科技热点建议启用 RSS/网页作为主源，YouTube/B站/社媒作为补充源",
                "小红书、LinkedIn、雪球等登录型来源只在有明确授权时启用",
            ],
            "message": "Agent-Reach 已安装，可作为互联网能力底座使用。" if installed else "Agent-Reach 尚未安装；可点击“安装/更新”从 GitHub 安装。",
        }
        self._persist_health(payload)
        return payload

    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            return json.dumps({"status": "success", **self._status(False)}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Agent-Reach status error: {e}")
            return json.dumps({"status": "error", "message": str(e)}, ensure_ascii=False)

    def POST(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "doctor").strip().lower()
            self._activate_env()
            command = self._command("agent-reach")
            if action == "doctor":
                if not command:
                    return json.dumps({"status": "error", **self._status(False), "message": "Agent-Reach 尚未安装，无法运行 doctor。"}, ensure_ascii=False)
                code, output = self._run([command, "doctor"], timeout=80)
                payload = self._status(False)
                payload.update({"doctor_ok": code == 0, "doctor_output": output, "message": "doctor 检查完成" if code == 0 else "doctor 检查发现问题，请查看输出。"})
                payload["available"] = bool(payload.get("installed") and payload.get("doctor_ok"))
                self._persist_health(payload)
                return json.dumps({"status": "success" if code == 0 else "error", **payload}, ensure_ascii=False)
            if action in {"install", "update"}:
                if action == "install" and command:
                    payload = self._status(False)
                    payload["message"] = "Agent-Reach 已安装，无需重复安装。需要重新检查请点击 doctor；需要升级请使用强制更新。"
                    return json.dumps({"status": "success", **payload}, ensure_ascii=False)
                pip_args = [self._python_executable(), "-m", "pip", "install", "--upgrade", "--no-cache-dir", "--no-input", "https://github.com/Panniantong/agent-reach/archive/main.zip"]
                try:
                    temp_dir = self._install_temp_dir()
                    install_env = os.environ.copy()
                    temp_dir = self._short_path(temp_dir)
                    install_env.update({"TMP": temp_dir, "TEMP": temp_dir, "TMPDIR": temp_dir, "PYTHONUTF8": "1"})
                    code, output = self._run(pip_args, timeout=300, env=install_env)
                except Exception as install_error:
                    logger.error(f"[WebChannel] Agent-Reach install error: {install_error}")
                    return json.dumps({"status": "error", **self._status(False), "message": f"Agent-Reach 安装失败：{install_error}"}, ensure_ascii=False)
                payload = self._status(False)
                setup_output = ""
                if code == 0 and payload.get("installed"):
                    try:
                        setup_code, setup_output = self._run([payload["command"], "install", "--env=auto", "--safe"], timeout=300)
                    except Exception as setup_error:
                        setup_code, setup_output = 1, str(setup_error)
                    payload = self._status(False)
                    payload["doctor_output"] = "\n\n".join(part for part in [output, setup_output] if part)[-8000:]
                    if setup_code == 0:
                        payload["message"] = "Agent-Reach 安装/更新成功，已完成安全模式初始化。建议继续点击 doctor 查看各平台状态。"
                        return json.dumps({"status": "success", **payload}, ensure_ascii=False)
                    payload["message"] = "Agent-Reach CLI 已安装，但安全模式初始化发现问题；可继续点击 doctor 查看缺失依赖。"
                    return json.dumps({"status": "error", **payload}, ensure_ascii=False)
                payload["doctor_output"] = output
                if code == 0 and payload.get("installed"):
                    payload["message"] = "Agent-Reach 安装/更新成功。建议继续点击 doctor 完成平台依赖检查。"
                    return json.dumps({"status": "success", **payload}, ensure_ascii=False)
                if re.search(r"permission denied|拒绝访问|errno 13|winerror 5", output, re.I):
                    payload["message"] = "安装失败：Windows 拒绝访问 pip 临时解压目录。已改用独立临时目录；如果仍失败，请以普通桌面方式重启 CowAgent，或把杀毒/受控文件夹访问放行 CowAgent 后重试。"
                else:
                    payload["message"] = "已尝试安装/更新，但当前环境未检测到 agent-reach 命令。可能是网络无法访问 GitHub、pip 安装失败，或包未生成命令入口；请查看下方输出。"
                return json.dumps({"status": "error", **payload}, ensure_ascii=False)
            if action == "save_config":
                platform = str(body.get("platform") or "").strip().lower()
                allowed = {pid for pid, *_ in self.ZERO_CONFIG_PLATFORMS} | {pid for pid, _ in self.AUTH_PLATFORMS}
                if platform not in allowed:
                    return json.dumps({"status": "error", **self._status(False), "message": "请选择有效的接入来源。"}, ensure_ascii=False)
                configs = self._load_configs()
                old = configs.get(platform, {}) if isinstance(configs.get(platform), dict) else {}
                secret = str(body.get("secret") or "").strip()
                cookie_file = str(body.get("cookie_file") or "").strip()
                configs[platform] = {
                    "enabled": bool(body.get("enabled", True)),
                    "auth_type": str(body.get("auth_type") or old.get("auth_type") or "token").strip(),
                    "account": str(body.get("account") or "").strip(),
                    "secret": secret if secret else old.get("secret", ""),
                    "cookie_file": cookie_file,
                    "note": str(body.get("note") or "").strip(),
                    "updated_at": datetime.datetime.now().isoformat(timespec="seconds"),
                }
                self._save_configs(configs)
                payload = self._status(False)
                payload["message"] = f"{platform} 来源配置已保存。"
                return json.dumps({"status": "success", **payload}, ensure_ascii=False)
            if action == "delete_config":
                platform = str(body.get("platform") or "").strip().lower()
                configs = self._load_configs()
                configs.pop(platform, None)
                self._save_configs(configs)
                payload = self._status(False)
                payload["message"] = f"{platform} 来源配置已删除。"
                return json.dumps({"status": "success", **payload}, ensure_ascii=False)
            return json.dumps({"status": "error", "message": f"unknown action: {action}"}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Agent-Reach POST error: {e}")
            return json.dumps({"status": "error", "message": str(e)}, ensure_ascii=False)


