class IntelligencePreflightHandler:
    """Pre-save checks for automation tasks.

    This mirrors Ona's "authorize during first use" idea: when a user creates
    a task, we check notification channels, fallback route and artifact settings
    before the task is saved, so problems surface immediately instead of after
    the first scheduled run.
    """

    @staticmethod
    def _notification_targets(payload: dict) -> list:
        targets = payload.get("notifications")
        if isinstance(targets, list):
            return targets
        return []

    @staticmethod
    def _target_channel(target: dict) -> str:
        target = target or {}
        target_type = str(target.get("type") or "").strip()
        if target_type == "webhook":
            return "webhook"
        return str(target.get("channel") or target_type or "").strip()

    @staticmethod
    def _schedule_preview(payload: dict) -> dict:
        schedule_type = str(payload.get("schedule_type") or "daily").strip().lower()
        schedule = str(payload.get("schedule") or "").strip()
        interval = int(payload.get("interval_minutes") or 0)
        now = datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8)))
        label = schedule or ("每隔一段时间" if schedule_type == "interval" else "每天09:00")
        next_run = ""
        try:
            if schedule_type == "interval" and interval > 0:
                next_run_at = now + datetime.timedelta(minutes=interval)
                next_run = next_run_at.strftime("%Y-%m-%d %H:%M")
                label = f"每隔 {interval} 分钟"
            else:
                text = schedule or "每天09:00"
                match = re.search(r"(\d{1,2})[:：](\d{2})", text)
                hour, minute = (9, 0)
                if match:
                    hour = max(0, min(23, int(match.group(1))))
                    minute = max(0, min(59, int(match.group(2))))
                next_run_at = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
                if next_run_at <= now:
                    next_run_at += datetime.timedelta(days=1)
                if schedule_type == "weekly" or "每周" in text:
                    weekday_map = {"一": 0, "二": 1, "三": 2, "四": 3, "五": 4, "六": 5, "日": 6, "天": 6}
                    target_weekday = None
                    for key, value in weekday_map.items():
                        if key in text:
                            target_weekday = value
                            break
                    if target_weekday is not None:
                        days = (target_weekday - now.weekday()) % 7
                        candidate = now.replace(hour=hour, minute=minute, second=0, microsecond=0) + datetime.timedelta(days=days)
                        if candidate <= now:
                            candidate += datetime.timedelta(days=7)
                        next_run_at = candidate
                next_run = next_run_at.strftime("%Y-%m-%d %H:%M")
                label = text
        except Exception:
            next_run = ""
        return {"schedule_type": schedule_type, "schedule": label, "next_run": next_run, "timezone": "Asia/Shanghai"}

    def POST(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            payload = body.get("payload") if isinstance(body.get("payload"), dict) else body
            kind = str(body.get("kind") or payload.get("kind") or "automation")
            warnings = []
            errors = []
            checks = []

            name = str(payload.get("name") or "").strip()
            if not name:
                errors.append("任务名称不能为空")

            schedule_preview = self._schedule_preview(payload)
            artifact_type = str(payload.get("artifact_type") or "report").strip()
            artifact_tags = payload.get("artifact_tags") or []
            if not artifact_type:
                warnings.append("未设置产物类型，系统会默认保存为 report")
            if not artifact_tags:
                warnings.append("未设置产物标签，系统会自动使用默认标签")

            targets = self._notification_targets(payload)
            will_queue = False
            web_fallback = True
            if not targets:
                warnings.append("未配置外部通知，系统会使用 Web 消息中心兜底；如企业微信/微信可用，也会按默认通道发送")
                checks.append({"name": "通知兜底", "status": "success", "message": "Web 消息中心可用"})
            else:
                for target in targets:
                    channel = self._target_channel(target)
                    if channel == "channel":
                        channel = str(target.get("name") or "")
                    if not channel:
                        warnings.append("发现一个通知目标未选择通道")
                        continue
                    if channel == "webhook" and str((target or {}).get("url") or "").strip():
                        webhook_url = str((target or {}).get("url") or "").strip()
                        parsed = urlparse(webhook_url)
                        configured = parsed.scheme in ("http", "https") and bool(parsed.netloc)
                        health = {
                            "channel": "webhook",
                            "label": "Webhook",
                            "active": True,
                            "configured": configured,
                            "ok": configured,
                            "level": "success" if configured else "error",
                            "message": "自定义 Webhook 地址格式有效" if configured else "自定义 Webhook 地址格式无效",
                            "next_action": "保存后建议发送测试" if configured else "请填写完整 http/https Webhook 地址",
                        }
                    else:
                        health = ChannelHealthHandler._channel_health(channel)
                    status = "success" if health.get("ok") else ("warning" if health.get("configured") or health.get("active") else "error")
                    message = health.get("message") or "状态未知"
                    checks.append({
                        "name": health.get("label") or channel,
                        "channel": channel,
                        "receiver": str((target or {}).get("receiver") or (target or {}).get("url") or health.get("receiver_hint") or ""),
                        "status": status,
                        "message": message,
                        "next_action": health.get("next_action") or "",
                        "can_send": bool(health.get("can_send") or health.get("ok")),
                        "connection_state": health.get("connection_state") or "",
                        "connection_state_label": health.get("connection_state_label") or "",
                    })
                    if channel == "web":
                        continue
                    if status == "error":
                        warnings.append(f"{health.get('label') or channel} 当前不可用：{message}")
                    elif status == "warning":
                        warnings.append(f"{health.get('label') or channel} 需要关注：{message}")
                    if channel == "weixin" and health.get("token_ready") is False:
                        warnings.append("绿微信发送令牌未就绪：任务结果会先进入待发送队列，刷新会话后自动补发")
                        will_queue = True
                    if status in ("error", "warning") and channel in {"weixin", "wecom_bot", "wechatcom_app", "email", "webhook"}:
                        will_queue = True

            has_web = any((self._target_channel(t) == "web") for t in targets)
            if targets and not has_web:
                warnings.append("建议保留 Web 消息中心兜底，避免外部通道异常时丢失任务结果")

            agent_reach_preview = {}
            try:
                prompt_text = " ".join(str(payload.get(key) or "") for key in ("name", "description", "prompt", "query", "rules", "source", "sources"))
                wants_internet = bool(re.search(r"新闻|热点|搜索|联网|网页|RSS|GitHub|视频|社媒|小红书|Reddit|YouTube|B站|来源|简报|研究", prompt_text, re.I))
                if wants_internet:
                    agent_reach_preview = AgentReachHandler()._status(False)
                    preflight = agent_reach_preview.get("preflight_summary") or {}
                    strategy = agent_reach_preview.get("source_strategy") or {}
                    checks.append({
                        "name": "Agent-Reach 来源能力",
                        "channel": "agent_reach",
                        "status": "success" if preflight.get("risk_level") == "low" else "warning",
                        "message": f"可用来源 {preflight.get('ready_count', 0)} 个；主源：{'、'.join(strategy.get('primary_labels') or []) or '普通搜索/RSS 降级'}",
                        "next_action": "建议在来源中心补齐 GitHub/RSS/视频或登录型平台授权" if preflight.get("risk_level") != "low" else "来源能力可用，保存后会按主备策略执行",
                        "can_send": True,
                        "connection_state": preflight.get("risk_level") or "",
                        "connection_state_label": "来源风险",
                    })
                    if preflight.get("risk_level") == "high":
                        warnings.append("Agent-Reach 来源能力不足：复杂联网任务会降级到普通搜索/RSS")
            except Exception as error:
                agent_reach_preview = {"status": "error", "message": str(error)}

            decision = {}
            try:
                from intelligence_center.decision_engine import decision_engine
                decision = decision_engine().task_preflight(payload, checks, schedule_preview)
                if decision.get("notification_risk") in {"medium", "high"}:
                    for item in decision.get("missing_items") or []:
                        if item == "weixin_session_refresh":
                            warning = "绿微信会话需要刷新：建议先发一句消息给 Agent，或启用企业微信/Web 兜底"
                        else:
                            warning = f"预检发现 {item} 存在风险，建议保存前检查"
                        if warning not in warnings:
                            warnings.append(warning)
            except Exception:
                decision = {}

            status = "error" if errors else ("warning" if warnings else "success")
            return json.dumps({
                "status": status,
                "kind": kind,
                "errors": errors,
                "warnings": warnings,
                "checks": checks,
                "decision": decision,
                "schedule_preview": schedule_preview,
                "delivery_preview": {
                    "target_count": len(targets),
                    "web_fallback": web_fallback,
                    "will_queue_on_failure": will_queue,
                    "artifact_type": artifact_type or "report",
                    "artifact_tags": artifact_tags or ["自动化", "报告"],
                },
                "agent_reach_preview": {
                    "enabled_sources": agent_reach_preview.get("enabled_sources") or [],
                    "degraded_sources": agent_reach_preview.get("degraded_sources") or [],
                    "source_strategy": agent_reach_preview.get("source_strategy") or {},
                    "preflight_summary": agent_reach_preview.get("preflight_summary") or {},
                } if agent_reach_preview else {},
                "message": "；".join(errors or warnings[:2]) or "预检通过",
            }, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error), "errors": [str(error)]}, ensure_ascii=False)


