class IntelligenceRunsHandler:
    @staticmethod
    def _scheduler_instance_skip_runs():
        items = []
        try:
            from pathlib import Path
            from agent.tools.scheduler.task_store import TaskStore
            store = TaskStore(str(Path(get_data_root()) / "scheduler" / "tasks.json"))
            for task in store.list_tasks():
                if task.get("last_run_status") != "skipped_instance":
                    continue
                run_id = f"scheduler-skip-{task.get('id') or uuid.uuid4().hex[:8]}"
                at = task.get("last_run_at") or datetime.datetime.now().isoformat(timespec="seconds")
                reason = task.get("last_result_summary") or "旧实例已跳过本次执行。"
                items.append({
                    "id": run_id,
                    "task_id": task.get("id") or "",
                    "task_name": task.get("name") or "定时任务",
                    "kind": "scheduler",
                    "kind_label": "定时任务",
                    "trigger": "scheduled",
                    "status": "skipped_instance",
                    "started_at": at,
                    "finished_at": at,
                    "duration_ms": 0,
                    "result_summary": reason,
                    "failure_reason": reason,
                    "error": "",
                    "notification_results": [],
                    "notification_summary": "未发送：实例保护已阻止旧实例执行",
                    "stages": [
                        {"name": "实例唯一性校验", "status": "skipped_instance", "at": at, "message": reason},
                        {"name": "执行保护", "status": "success", "at": at, "message": "任务未执行、未发送通知，避免旧实例重复触发。"},
                    ],
                    "logs": [
                        f"[{at}] 实例唯一性校验：{reason}",
                        f"[{at}] 已跳过执行，避免旧实例重复触发。",
                    ],
                    "task_snapshot": task,
                    "readonly": True,
                })
        except Exception:
            pass
        return items

    @staticmethod
    def _news_fallback_sources(task):
        from urllib.parse import parse_qs
        domains = []
        for source in list(task.get("sources") or []) + list(task.get("official_sources") or []):
            host = urlparse(str(source)).hostname or ""
            host = host.lower().removeprefix("www.")
            if host == "news.google.com":
                query = parse_qs(urlparse(str(source)).query).get("q", [""])[0]
                domains.extend(re.findall(r"\bsite:([a-zA-Z0-9.-]+)", query))
            elif host:
                domains.append(host)
        domains = list(OrderedDict.fromkeys(domains))[:18]
        topic = " ".join([str(task.get("name") or "AI 科技热点")] + [str(x) for x in (task.get("keywords") or [])[:4]]).strip()
        if not domains:
            domains = ["36kr.com", "qbitai.com", "jiqizhixin.com", "infoq.cn", "openai.com", "anthropic.com"]
        feeds = []
        for index in range(0, len(domains), 4):
            group = domains[index:index + 4]
            query = f"{topic} ({' OR '.join('site:' + domain for domain in group)}) when:7d"
            feeds.append(f"https://news.google.com/rss/search?q={quote(query)}&hl=zh-CN&gl=CN&ceid=CN:zh-Hans")
        return feeds[:6]

    @staticmethod
    def _recovery_retry_patch(kind, run, preferred=None, policy=None):
        snapshot = dict(run.get("task_snapshot") or {})
        policy = policy or {}
        if policy.get("enabled", True) is False:
            return {}, []
        patch = {}
        actions = []
        preferred_text = " ".join(str(x.get("action") if isinstance(x, dict) else x) for x in (preferred or []))
        if policy.get("allow_web_fallback", True) and (run.get("notification_failure") or "Web" in preferred_text):
            patch["notifications"] = [{"type": "channel", "channel": "web", "receiver": "web_user", "name": "Web 消息提醒"}]
            actions.append("通知失败：本次重试已临时改为发送到 Web")
        empty_text = " ".join(str(run.get(key) or "") for key in ("status", "empty_reason", "failure_reason", "recovery_suggestion", "error"))
        if kind == "news" and any(flag in empty_text for flag in ("暂无", "无合格", "没有匹配", "来源", "筛选", "空")):
            rules = dict(snapshot.get("rules") or {})
            include = list(rules.get("include") or [])
            # Mandatory keywords are user constraints, not a recovery heuristic.
            raw_sources = [str(x) for x in (snapshot.get("sources") or []) if str(x).strip()]
            sources = [x.replace("when:1d", "when:7d").replace("when%3A1d", "when%3A7d") for x in raw_sources] if policy.get("allow_expand_time", True) else raw_sources
            fallback_sources = IntelligenceRunsHandler._news_fallback_sources(snapshot) if policy.get("allow_switch_sources", True) else []
            if not policy.get("allow_expand_time", True):
                fallback_sources = [x.replace("when%3A7d", "when%3A1d") for x in fallback_sources]
            combined = list(OrderedDict.fromkeys(sources + fallback_sources))
            if combined:
                patch["sources"] = combined[:18]
                if policy.get("allow_expand_time", True) and policy.get("allow_switch_sources", True):
                    actions.append("搜索无内容：本次重试已扩展到最近 7 天并加入备用来源")
                elif policy.get("allow_expand_time", True):
                    actions.append("搜索无内容：本次重试已扩展到最近 7 天")
                elif policy.get("allow_switch_sources", True):
                    actions.append("搜索无内容：本次重试已加入备用来源")
        if kind == "briefing" and any(flag in empty_text for flag in ("暂无", "无合格", "没有匹配", "来源", "筛选", "空")):
            raw_sources = [str(x) for x in (snapshot.get("sources") or []) if str(x).strip()]
            sources = [x.replace("when:1d", "when:7d").replace("when%3A1d", "when%3A7d") for x in raw_sources] if policy.get("allow_expand_time", True) else raw_sources
            fallback_sources = IntelligenceRunsHandler._news_fallback_sources(snapshot) if policy.get("allow_switch_sources", True) else []
            if not policy.get("allow_expand_time", True):
                fallback_sources = [x.replace("when%3A7d", "when%3A1d") for x in fallback_sources]
            if sources or fallback_sources:
                patch["sources"] = list(OrderedDict.fromkeys(sources + fallback_sources))[:18]
                actions.append("日报无内容：本次重试已按恢复策略扩大来源或时间范围")
        if any(flag in empty_text.lower() for flag in ("browser is not available", "devtoolsactiveport", "cdp", "chrome exited", "playwright", "浏览器")):
            patch["recovery_mode"] = "browser_static_or_search_fallback"
            actions.append("浏览器失败：本次重试优先走静态解析或普通搜索兜底")
        # Historical recommendations must not be reported as actions executed now.
        return patch, actions

    @staticmethod
    def _recovery_explanations(actions, preferred=None, reason=""):
        preferred = preferred or []
        rows = []
        for action in [str(x) for x in (actions or []) if str(x).strip()]:
            matched = next((item for item in preferred if action in str(item.get("action") or "") or str(item.get("action") or "") in action), None)
            success_rate = None
            attempts = 0
            if matched:
                success_rate = round(float(matched.get("success_rate") or 0) * 100, 1)
                attempts = int(matched.get("attempts") or 0)
            if "Web" in action or "通知" in action:
                expected = "解决原通知通道失败时用户收不到结果的问题。"
            elif "7 天" in action or "7天" in action or "来源" in action:
                expected = "解决时间范围过窄、来源当天无更新或站点读取失败导致的空结果。"
            elif "必须包含" in action or "关键词" in action:
                expected = "解决筛选条件过严导致候选被全部过滤的问题。"
            elif "浏览器" in action or "静态解析" in action:
                expected = "解决浏览器运行环境不可用时任务无法继续的问题。"
            else:
                expected = "提高本次重试生成内容、发送通知和保存结果的成功率。"
            if success_rate is not None and attempts:
                why = f"本机历史中该动作成功率约 {success_rate}%，已有 {attempts} 次样本。"
                confidence = "high" if attempts >= 3 else "low"
            elif success_rate is not None:
                why = f"本机历史中该动作成功率约 {success_rate}%。"
                confidence = "low"
            else:
                why = reason or "根据失败原因自动选择推荐参数。"
                confidence = "rule"
            rows.append({
                "phase": "按推荐参数重试",
                "action": action,
                "why": why,
                "expected": expected,
                "success_rate": success_rate,
                "attempts": attempts,
                "confidence": confidence,
                "scope": "仅临时用于本次重试，结束后恢复原任务配置。",
            })
        return rows[:8]

    @staticmethod
    def _config_restore_patch(original):
        keys = (
            "name", "sources", "keywords", "schedule", "schedule_type", "interval_minutes", "enabled",
            "max_items", "notifications", "rules", "official_sources", "repositories", "urls",
            "include_types", "folder", "max_messages", "currencies", "source_url", "artifact_type",
            "artifact_tags", "kind", "filters", "topics", "competitors", "notify_on_unchanged",
        )
        return {key: deepcopy(original[key]) for key in keys if key in original}

    def GET(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            params = web.input(id="", query="", status="", trigger="", recovery="", limit="20", offset="0")
            synthetic = self._scheduler_instance_skip_runs()
            if params.id:
                found = next((item for item in synthetic if item.get("id") == params.id), None)
                if found:
                    return json.dumps({"status": "success", "run": _attach_execution_audit(found, max_items=16)}, ensure_ascii=False)
                return json.dumps({"status": "success", "run": _attach_execution_audit(_automation_run_service().get(params.id), max_items=16)}, ensure_ascii=False)
            result = _automation_run_service().list(params.query, params.status, params.trigger, int(params.limit or 20), int(params.offset or 0), params.recovery)
            items = [_attach_execution_audit(dict(item), max_items=6) for item in result["items"]]
            total = result["total"]
            if not params.recovery:
                query = str(params.query or "").strip().lower()
                status = str(params.status or "").strip()
                trigger = str(params.trigger or "").strip()
                extra = synthetic
                if query:
                    extra = [x for x in extra if query in json.dumps(x, ensure_ascii=False).lower()]
                if status:
                    extra = [x for x in extra if x.get("status") == status]
                if trigger:
                    extra = [x for x in extra if x.get("trigger") == trigger]
                if extra:
                    items = sorted(list(items) + [_attach_execution_audit(dict(x), max_items=6) for x in extra], key=lambda x: x.get("started_at", ""), reverse=True)[:int(params.limit or 20)]
                    total += len(extra)
            return json.dumps({"status": "success", "runs": items, "total": total, "has_more": result["has_more"]}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def DELETE(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body=json.loads(web.data() or b"{}"); ids=body.get("ids") or ([body.get("id")] if body.get("id") else [])
            deleted=_automation_run_service().delete(ids, bool(body.get("all")))
            return json.dumps({"status":"success","deleted":deleted},ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status":"error","message":str(error)},ensure_ascii=False)

    @classmethod
    def retry_run(cls, run_id="", task_id="", kind=""):
        run_id = str(run_id or "").strip()
        task_id = str(task_id or "").strip()
        kind = str(kind or "").strip()
        if run_id:
            run = _automation_run_service().get(run_id)
            task_id = task_id or str(run.get("task_id") or "")
            kind = kind or str(run.get("kind") or "")
        else:
            run = {}
        if not task_id or not kind:
            raise ValueError("缺少需要重试的任务信息")
        services = {
            "news": _news_assistant_service,
            "github": _github_monitor_service,
            "website": _website_monitor_service,
            "forex": _forex_query_service,
            "briefing": _daily_briefing_service,
            "social": _extended_task_service,
            "product": _extended_task_service,
            "ops": _extended_task_service,
            "email": _email_secretary_service,
            "maintenance": _maintenance_task_service,
        }
        factory = services.get(kind)
        if not factory:
            raise ValueError(f"暂不支持重试该任务类型：{kind}")
        service = factory()
        original = next((dict(x) for x in service.list_tasks() if str(x.get("id")) == task_id), {})
        reason_text = " ".join(str((run or {}).get(key) or "") for key in ("empty_reason", "failure_reason", "recovery_suggestion", "error"))
        preferred = []
        recovery_policy = {}
        try:
            from intelligence_center.agent2_service import Agent2Service
            agent2 = Agent2Service(os.path.join(get_data_root(), "intelligence_center"), get_data_root(), conf())
            settings = agent2._read().get("settings") or {}
            recovery_policy = settings.get("recovery_policy") or {}
            preferred = agent2.recommended_recovery_actions(kind, reason_text, 3)
        except Exception:
            preferred = []
        patch, recovery_actions = cls._recovery_retry_patch(kind, run if run_id else {"task_snapshot": original}, preferred, recovery_policy)
        outcome = "failed"
        result = {}
        def record_recovery(outcome_value, result_value=None):
            if not recovery_actions:
                return
            try:
                from intelligence_center.agent2_service import Agent2Service
                Agent2Service(os.path.join(get_data_root(), "intelligence_center"), get_data_root(), conf()).observe_recovery_attempt({
                    "kind": kind,
                    "task_id": task_id,
                    "task_name": original.get("name") or task_id,
                    "reason": reason_text,
                    "actions": recovery_actions,
                    "outcome": outcome_value,
                    "run_id": (result_value or {}).get("run_id", ""),
                })
            except Exception:
                pass

        if patch and hasattr(service, "_update"):
            service._update(task_id, patch)
        try:
            result = service.run(task_id, "recovery")
            new_run = _automation_run_service().get(result.get("run_id")) if result.get("run_id") else {}
            outcome = "success" if new_run.get("status") == "success" else ("empty" if new_run.get("status") == "empty" else "failed")
            if result.get("run_id"):
                _automation_run_service().annotate_recovery_retry(
                    result.get("run_id"),
                    run_id,
                    recovery_actions,
                    outcome,
                    cls._recovery_explanations(recovery_actions, preferred, reason_text),
                )
        except Exception:
            outcome = "failed"
            record_recovery(outcome)
            raise
        finally:
            if patch and original and hasattr(service, "_update"):
                latest = next((dict(x) for x in service.list_tasks() if str(x.get("id")) == task_id), {})
                restore = cls._config_restore_patch(original)
                for key in ("last_run_at", "last_status"):
                    if latest.get(key):
                        restore[key] = latest.get(key)
                service._update(task_id, restore)
        if recovery_actions:
            result = result or {}
            result["recovery_retry_actions"] = recovery_actions
            record_recovery(outcome, result)
        return result or {}

    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            if body.get("action") == "resend_notifications":
                result = _automation_run_service().resend_notifications(body.get("run_id", ""))
            elif body.get("action") == "resolve_interrupted":
                result = _automation_run_service().resolve_interrupted(body.get('run_id', ''), body.get('confirmed'), body.get('note', ''))
            else:
                result = self.retry_run(body.get("run_id", ""), body.get("task_id", ""), body.get("kind", ""))
            return json.dumps({"status": "success", **result}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


def _notification_is_web_fallback(item):
    """Return True when a notification record is the automatic Web fallback copy."""
    if not isinstance(item, dict):
        return False
    return bool(
        item.get("web_fallback")
        or item.get("fallback")
        or item.get("delivery_status") in ("web_fallback", "fallback")
        or str(item.get("target") or "").startswith("Web（自动补发")
        or "补发到 Web" in str(item.get("message") or "")
    )


def _read_execution_audit_events(limit=2000):
    try:
        path = Path(get_data_root()) / "intelligence_center" / "execution_audit.json"
        data = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
        events = data.get("events") if isinstance(data, dict) else []
        if not isinstance(events, list):
            return []
        return sorted(events[-int(limit or 2000):], key=lambda x: str(x.get("created_at") or ""))
    except Exception:
        return []


def _parse_audit_time(value):
    try:
        text = str(value or "").strip()
        if not text:
            return None
        return datetime.datetime.fromisoformat(text.replace("Z", "+00:00"))
    except Exception:
        return None


def _execution_audit_for(task_id="", run_id="", channel="", receiver="", around_at="", max_items=12):
    """Return compact execution replay events for UI troubleshooting."""
    task_id = str(task_id or "").strip()
    run_id = str(run_id or "").strip()
    channel = str(channel or "").strip()
    receiver = str(receiver or "").strip()
    around = _parse_audit_time(around_at)
    matched = []
    for item in _read_execution_audit_events():
        if task_id and str(item.get("task_id") or "") != task_id:
            continue
        if run_id and str(item.get("run_id") or "") and str(item.get("run_id") or "") != run_id:
            continue
        if channel and str(item.get("channel") or "") and str(item.get("channel") or "") != channel:
            continue
        if receiver and receiver not in {"web_user", "configured_webhook"} and str(item.get("receiver") or "") and str(item.get("receiver") or "") != receiver:
            continue
        if around:
            at = _parse_audit_time(item.get("created_at"))
            if at:
                try:
                    if abs((at - around).total_seconds()) > 2 * 60 * 60:
                        continue
                except Exception:
                    pass
        matched.append(item)
    if not matched and task_id:
        # Fall back to the newest task-level trace. This keeps old scheduler
        # records useful even when they predate run_id support.
        for item in _read_execution_audit_events():
            if str(item.get("task_id") or "") == task_id:
                matched.append(item)
    matched = sorted(matched, key=lambda x: str(x.get("created_at") or ""), reverse=True)[:int(max_items or 12)]
    return list(reversed(matched))


def _execution_audit_summary(events):
    events = [item for item in (events or []) if isinstance(item, dict)]
    if not events:
        return ""
    failed = sum(1 for item in events if str(item.get("status") or "") in {"failed", "error"})
    fallback = any(str(item.get("stage") or "") == "fallback" for item in events)
    success = sum(1 for item in events if str(item.get("status") or "") == "success")
    if failed:
        return f"执行轨迹：{failed} 个异常" + ("，已兜底" if fallback else "")
    if fallback:
        return "执行轨迹：已启用兜底"
    if success:
        return f"执行轨迹：{success} 步通过"
    return "执行轨迹已记录"


def _pending_delivery_summary_for_run(item, limit=5):
    if not isinstance(item, dict):
        return {}
    task_id = str(item.get("task_id") or item.get("id") or "").strip()
    task_name = str(item.get("task_name") or item.get("name") or "").strip()
    run_id = str(item.get("run_id") or item.get("id") or "").strip()
    try:
        from pathlib import Path
        path = Path(get_data_root()) / "intelligence_center" / "pending_deliveries.json"
        data = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
        rows = data.get("items") if isinstance(data, dict) else []
    except Exception:
        rows = []
    if not isinstance(rows, list):
        rows = []

    matched = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        row_run_id = str(row.get("run_id") or "").strip()
        row_task_id = str(row.get("task_id") or "").strip()
        row_task_name = str(row.get("task_name") or "").strip()
        if run_id and row_run_id and row_run_id == run_id:
            matched.append(row)
        elif task_id and row_task_id and row_task_id == task_id:
            matched.append(row)
        elif task_name and row_task_name and row_task_name == task_name:
            matched.append(row)
    if not matched:
        return {}

    def _status(value):
        value = str(value or "pending").strip().lower()
        return value if value in {"pending", "delivered", "abandoned"} else "pending"

    pending = [row for row in matched if _status(row.get("status")) == "pending"]
    delivered = [row for row in matched if _status(row.get("status")) == "delivered"]
    abandoned = [row for row in matched if _status(row.get("status")) == "abandoned"]
    latest = sorted(matched, key=lambda x: str(x.get("updated_at") or x.get("created_at") or ""), reverse=True)[: max(1, int(limit or 5))]
    original_failed = any((result or {}).get("success") is False for result in item.get("notification_results") or [])
    web_fallback = bool(item.get("web_fallback_notification")) or any(
        (result or {}).get("web_fallback") or (result or {}).get("fallback") or str((result or {}).get("channel") or "") == "web"
        for result in item.get("notification_results") or []
    )
    return {
        "total": len(matched),
        "pending": len(pending),
        "delivered": len(delivered),
        "abandoned": len(abandoned),
        "original_failed": bool(original_failed),
        "web_fallback": bool(web_fallback),
        "latest": [
            {
                "id": row.get("id") or "",
                "channel": row.get("channel") or "",
                "receiver": row.get("receiver") or "",
                "task_name": row.get("task_name") or task_name or "自动任务",
                "status": _status(row.get("status")),
                "attempts": row.get("attempts") or 0,
                "max_attempts": row.get("max_attempts") or 0,
                "reason": row.get("last_error") or row.get("reason") or "",
                "updated_at": row.get("updated_at") or row.get("created_at") or "",
            }
            for row in latest
        ],
    }


def _attach_execution_audit(item, max_items=12):
    if not isinstance(item, dict):
        return item
    task_id = item.get("task_id") or item.get("id") or ""
    run_id = item.get("run_id") or item.get("id") or ""
    channel = item.get("channel") or item.get("target") or ""
    receiver = item.get("receiver") or ""
    around = item.get("created_at") or item.get("started_at") or item.get("updated_at") or item.get("finished_at") or ""
    trace = _execution_audit_for(task_id=task_id, run_id=run_id, channel=channel, receiver=receiver, around_at=around, max_items=max_items)
    if trace:
        item["execution_audit"] = trace
        item["execution_audit_summary"] = _execution_audit_summary(trace)
    pending_delivery_summary = _pending_delivery_summary_for_run(item)
    if pending_delivery_summary:
        item["pending_delivery_summary"] = pending_delivery_summary
    return item


class IntelligenceNotificationsHandler:
    def GET(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            from pathlib import Path
            params = web.input(query="", status="", channel="", limit="50", offset="0")
            path = Path(get_data_root()) / "intelligence_center" / "notification_events.json"
            try:
                data = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
            except Exception:
                data = {}
            events = data.get("events") if isinstance(data, dict) else []
            if not isinstance(events, list):
                events = []
            try:
                pending_path = Path(get_data_root()) / "intelligence_center" / "pending_deliveries.json"
                pending_data = json.loads(pending_path.read_text(encoding="utf-8")) if pending_path.exists() else {}
                pending_items = pending_data.get("items") if isinstance(pending_data, dict) else []
                if isinstance(pending_items, list):
                    for pending in pending_items[-200:]:
                        pending_status = str(pending.get("status") or "pending")
                        events.append({
                            "id": f"pending-{pending.get('id')}",
                            "task_id": pending.get("task_id") or "",
                            "task_name": pending.get("task_name") or "待补发通知",
                            "target": pending.get("channel") or "",
                            "channel": pending.get("channel") or "",
                            "receiver": pending.get("receiver") or "",
                            "success": pending_status == "delivered",
                            "message": pending.get("last_error") or pending.get("reason") or "",
                            "summary": "通知已进入待补发队列，通道恢复后会自动补发。" if pending_status == "pending" else ("通知已自动补发成功。" if pending_status == "delivered" else "通知补发多次失败，已停止自动补发。"),
                            "created_at": pending.get("updated_at") or pending.get("created_at") or "",
                            "run_id": pending.get("run_id") or "",
                            "delivery_status": f"pending_{pending_status}",
                            "pending_id": pending.get("id") or "",
                            "attempts": pending.get("attempts") or 0,
                            "max_attempts": pending.get("max_attempts") or 0,
                        })
            except Exception:
                pass
            items = sorted(events, key=lambda x: str(x.get("created_at") or ""), reverse=True)
            needle = str(params.query or "").strip().lower()
            if needle:
                items = [
                    item for item in items
                    if needle in " ".join(str(item.get(key, "")) for key in ("task_id", "task_name", "target", "receiver", "message", "summary")).lower()
                ]
            status = str(params.status or "").strip()
            if status == "success":
                items = [item for item in items if item.get("success") is True and not _notification_is_web_fallback(item)]
            elif status == "failed":
                items = [item for item in items if item.get("success") is False]
            elif status in ("web_fallback", "fallback"):
                items = [item for item in items if _notification_is_web_fallback(item)]
            channel = str(params.channel or "").strip()
            if channel:
                items = [
                    item for item in items
                    if str(item.get("channel") or "") == channel or str(item.get("target") or "") == channel
                ]
            deduped = []
            seen_session_alerts = set()
            for item in items:
                task_id = str(item.get("task_id") or "")
                if task_id.startswith("channel-session-"):
                    key = (task_id, str(item.get("channel") or ""), str(item.get("receiver") or ""))
                    if key in seen_session_alerts:
                        continue
                    seen_session_alerts.add(key)
                deduped.append(item)
            items = deduped
            offset = max(0, int(params.offset or 0))
            limit = max(1, min(int(params.limit or 50), 200))
            page = items[offset:offset + limit]
            page = [_attach_execution_audit(dict(item), max_items=8) for item in page]
            return json.dumps({
                "status": "success",
                "events": page,
                "total": len(items),
                "has_more": offset + limit < len(items),
            }, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


class IntelligencePendingDeliveriesHandler:
    @staticmethod
    def _read_items():
        from pathlib import Path
        path = Path(get_data_root()) / "intelligence_center" / "pending_deliveries.json"
        try:
            data = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
        except Exception:
            data = {}
        items = data.get("items") if isinstance(data, dict) else []
        return items if isinstance(items, list) else []

    @staticmethod
    def _safe_item(item):
        item = item if isinstance(item, dict) else {}
        report = str(item.get("report") or "")
        return {
            "id": item.get("id") or "",
            "created_at": item.get("created_at") or "",
            "updated_at": item.get("updated_at") or item.get("created_at") or "",
            "task_id": item.get("task_id") or "",
            "task_name": item.get("task_name") or "自动任务",
            "run_id": item.get("run_id") or "",
            "channel": item.get("channel") or "",
            "receiver": item.get("receiver") or "",
            "status": item.get("status") or "pending",
            "attempts": item.get("attempts") or 0,
            "max_attempts": item.get("max_attempts") or 0,
            "reason": item.get("last_error") or item.get("reason") or "",
            "delivered_at": item.get("delivered_at") or "",
            "abandoned_at": item.get("abandoned_at") or "",
            "report_preview": _sanitize_agent_reach_visible_content(report[:260]) if report else "",
            "report_size": len(report),
        }

    def GET(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            params = web.input(query="", status="", channel="", limit="100")
            items = [self._safe_item(item) for item in self._read_items()]
            query = str(params.query or "").strip().lower()
            if query:
                items = [
                    item for item in items
                    if query in " ".join(str(item.get(key, "")) for key in ("id", "task_id", "task_name", "run_id", "channel", "receiver", "reason", "report_preview")).lower()
                ]
            status = str(params.status or "").strip()
            if status:
                items = [item for item in items if str(item.get("status") or "") == status]
            channel = str(params.channel or "").strip()
            if channel:
                items = [item for item in items if str(item.get("channel") or "") == channel]
            items = sorted(items, key=lambda x: str(x.get("updated_at") or x.get("created_at") or ""), reverse=True)
            summary = {
                "total": len(items),
                "pending": sum(1 for item in items if item.get("status") == "pending"),
                "delivered": sum(1 for item in items if item.get("status") == "delivered"),
                "abandoned": sum(1 for item in items if item.get("status") == "abandoned"),
            }
            try:
                limit = max(1, min(500, int(params.limit or 100)))
            except Exception:
                limit = 100
            return json.dumps({"status": "success", "summary": summary, "items": items[:limit]}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[IntelligencePendingDeliveries] GET error: {error}", exc_info=True)
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "").strip()
            ids = body.get("ids") or []
            if not isinstance(ids, list):
                ids = [ids]
            channel = str(body.get("channel") or "").strip()
            from plugins.intelligence_center.notifications import NotificationDispatcher
            if action == "retry_selected":
                result = NotificationDispatcher.process_pending_delivery_ids(ids, limit=int(body.get("limit") or 50))
                return json.dumps({"status": "success", "message": f"已尝试补发 {result.get('processed', 0)} 条，成功 {result.get('delivered', 0)} 条", **result}, ensure_ascii=False)
            if action == "retry_all":
                result = NotificationDispatcher.process_pending_deliveries(channel=channel, limit=int(body.get("limit") or 50))
                return json.dumps({"status": "success", "message": f"已尝试补发 {result.get('processed', 0)} 条，成功 {result.get('delivered', 0)} 条", **result}, ensure_ascii=False)
            if action == "abandon_selected":
                result = NotificationDispatcher.abandon_pending_delivery_ids(ids, reason=str(body.get("reason") or "用户手动放弃补发"))
                return json.dumps({"status": "success", "message": f"已放弃 {result.get('updated', 0)} 条待补发", **result}, ensure_ascii=False)
            return json.dumps({"status": "error", "message": "未知操作"}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[IntelligencePendingDeliveries] POST error: {error}", exc_info=True)
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


class IntelligenceSelfHealingHandler:
    """Read-only timeline of automatic remediation actions."""

    @staticmethod
    def _item(kind, title, summary, status="info", at="", task_id="", task_name="", run_id="", channel="", action="", source="", details=None):
        seed = "|".join([str(kind), str(title), str(at), str(task_id), str(run_id), str(channel), str(action), str(summary)[:80]])
        return {
            "id": hashlib.sha256(seed.encode("utf-8", errors="ignore")).hexdigest()[:16],
            "kind": kind,
            "title": title,
            "summary": summary,
            "status": status,
            "at": at,
            "task_id": task_id,
            "task_name": task_name or "系统自愈",
            "run_id": run_id,
            "channel": channel,
            "action": action,
            "source": source,
            "details": details or {},
        }

    @staticmethod
    def _read_json(path):
        try:
            path = Path(path)
            data = json.loads(path.read_text(encoding="utf-8")) if path.exists() else {}
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    @staticmethod
    def _handled_path(root):
        return Path(root) / "self_healing_handled.json"

    @classmethod
    def _handled_map(cls, root):
        data = cls._read_json(cls._handled_path(root))
        handled = data.get("items") if isinstance(data.get("items"), dict) else {}
        return handled

    @classmethod
    def _save_handled(cls, root, handled):
        path = cls._handled_path(root)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = Path(f"{path}.tmp")
        tmp.write_text(json.dumps({"items": handled or {}}, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(path)

    @classmethod
    def _all_items(cls, root):
        handled = cls._handled_map(root)
        items = cls._audit_items() + cls._notification_items(root) + cls._pending_items(root) + cls._backend_items(root)
        dedup = {}
        for item in items:
            if item.get("id") in handled:
                item["handled"] = True
                item["handled_at"] = handled.get(item.get("id"), {}).get("handled_at") or ""
                item["handled_reason"] = handled.get(item.get("id"), {}).get("reason") or ""
            dedup[item.get("id")] = item
        return sorted(dedup.values(), key=lambda x: str(x.get("at") or ""), reverse=True)

    @staticmethod
    def _filter_items(items, query="", status="", kind="", channel=""):
        query = str(query or "").strip().lower()
        if query:
            items = [item for item in items if query in " ".join(str(item.get(k, "")) for k in ("title", "summary", "task_name", "channel", "action")).lower()]
        status = str(status or "").strip()
        if status:
            items = [item for item in items if str(item.get("status") or "") == status]
        kind = str(kind or "").strip()
        if kind:
            items = [item for item in items if str(item.get("kind") or "") == kind or str(item.get("action") or "") == kind]
        channel = str(channel or "").strip()
        if channel:
            items = [item for item in items if str(item.get("channel") or "") == channel]
        return items

    @staticmethod
    def _recent_items(items, hours=24):
        try:
            cutoff = datetime.datetime.now() - datetime.timedelta(hours=max(1, int(hours or 24)))
        except Exception:
            cutoff = datetime.datetime.now() - datetime.timedelta(hours=24)
        recent = []
        for item in items:
            raw = str(item.get("at") or "").strip()
            if not raw:
                continue
            try:
                at = datetime.datetime.fromisoformat(raw.replace("Z", "+00:00").replace("+08:00", ""))
            except Exception:
                continue
            if at >= cutoff:
                recent.append(item)
        return recent

    @staticmethod
    def _status_from_audit(value):
        value = str(value or "").strip().lower()
        if value in {"success", "ok", "delivered"}:
            return "success"
        if value in {"failed", "error", "abandoned"}:
            return "failed"
        if value in {"warning", "skipped"}:
            return "warning"
        return "info"

    @classmethod
    def _audit_items(cls):
        output = []
        action_stages = {
            "pending_enqueue": ("补发队列", "通知已进入待补发队列"),
            "pending_retry": ("自动补发", "系统尝试补发通知"),
            "pending_policy": ("补发策略", "按策略跳过或调整补发"),
            "fallback": ("兜底处理", "系统启用了兜底处理"),
            "decision": ("决策动作", "系统生成了自动处理建议"),
            "notification_policy": ("通知策略", "系统按任务类型调整通知通道"),
            "channel_preflight": ("通道预检", "发送前检查通道状态"),
            "cleanup_stale_locks": ("清理旧锁", "系统清理了过期调度锁"),
            "cleanup_stale_claims": ("清理旧运行", "系统清理了过期运行记录"),
            "reconnect": ("通道重连", "系统触发通道重连"),
        }
        for event in _read_execution_audit_events(limit=2500):
            stage = str(event.get("stage") or "").strip()
            details = event.get("details") if isinstance(event.get("details"), dict) else {}
            actions = details.get("actions") or []
            has_decision = bool(details.get("decision") or details.get("failure_decision") or details.get("content_decision") or details.get("archive_decision"))
            if stage not in action_stages and not actions and not has_decision:
                continue
            title, default_summary = action_stages.get(stage, ("自动修复动作", "系统记录了一次自动处理动作"))
            message = str(event.get("message") or "").strip()
            if actions:
                message = "；".join(str(x) for x in actions[:4] if str(x).strip()) or message
            output.append(cls._item(
                "audit", title, message or default_summary, cls._status_from_audit(event.get("status")),
                event.get("created_at") or "", event.get("task_id") or "",
                event.get("task_name") or event.get("task_id") or "自动任务",
                event.get("run_id") or "", event.get("channel") or "", stage, "execution_audit", details,
            ))
        return output

    @classmethod
    def _notification_items(cls, root):
        output = []
        data = cls._read_json(Path(root) / "notification_events.json")
        for event in data.get("events") or []:
            if not isinstance(event, dict):
                continue
            if _notification_is_web_fallback(event):
                output.append(cls._item(
                    "notification", "Web 兜底保存",
                    event.get("verification_message") or event.get("message") or "原通道发送异常，结果已保存到 Web 消息中心。",
                    "success" if event.get("success") else "warning",
                    event.get("created_at") or "", event.get("task_id") or "", event.get("task_name") or "自动任务",
                    event.get("run_id") or "", event.get("channel") or "web", "web_fallback", "notification_events",
                    {"delivery_status": event.get("delivery_status") or "", "target": event.get("target") or ""},
                ))
            elif event.get("skipped"):
                output.append(cls._item(
                    "notification", "跳过不可用通道", event.get("message") or "发送前检测到通道不可用，已跳过该通道。",
                    "warning", event.get("created_at") or "", event.get("task_id") or "", event.get("task_name") or "自动任务",
                    event.get("run_id") or "", event.get("channel") or "", "skip_unhealthy_channel", "notification_events",
                    {"delivery_status": event.get("delivery_status") or ""},
                ))
        return output

    @classmethod
    def _pending_items(cls, root):
        output = []
        data = cls._read_json(Path(root) / "pending_deliveries.json")
        for item in data.get("items") or []:
            if not isinstance(item, dict):
                continue
            status = str(item.get("status") or "pending")
            title = {"pending": "等待自动补发", "delivered": "自动补发成功", "abandoned": "停止自动补发"}.get(status, "补发队列更新")
            output.append(cls._item(
                "pending", title,
                item.get("last_error") or item.get("reason") or ("通道恢复后会自动补发。" if status == "pending" else "补发状态已更新。"),
                {"pending": "warning", "delivered": "success", "abandoned": "failed"}.get(status, "info"),
                item.get("updated_at") or item.get("created_at") or "", item.get("task_id") or "", item.get("task_name") or "自动任务",
                item.get("run_id") or "", item.get("channel") or "", f"pending_{status}", "pending_deliveries",
                {"pending_id": item.get("id") or "", "attempts": item.get("attempts") or 0, "max_attempts": item.get("max_attempts") or 0, "receiver": item.get("receiver") or ""},
            ))
        return output

    @classmethod
    def _backend_items(cls, root):
        output = []
        data = cls._read_json(Path(root) / "backend_restart_actions.json")
        for item in data.get("actions") or []:
            if not isinstance(item, dict):
                continue
            output.append(cls._item(
                "backend", "安全重启后端", item.get("message") or item.get("reason") or "系统记录了一次后端安全重启动作。",
                cls._status_from_audit(item.get("status") or "warning"), item.get("created_at") or item.get("updated_at") or "",
                "", "后端服务", "", "", "restart_backend", "backend_restart_actions",
                {k: v for k, v in item.items() if k not in {"message", "reason"}},
            ))
        return output

    def GET(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            params = web.input(query="", status="", kind="", channel="", limit="100")
            root = Path(get_data_root()) / "intelligence_center"
            items = self._filter_items(self._all_items(root), params.query, params.status, params.kind, params.channel)
            summary = {
                "total": len(items),
                "success": sum(1 for item in items if item.get("status") == "success"),
                "warning": sum(1 for item in items if item.get("status") == "warning"),
                "failed": sum(1 for item in items if item.get("status") == "failed"),
                "pending": sum(1 for item in items if item.get("action") == "pending_pending" and not item.get("handled")),
                "handled": sum(1 for item in items if item.get("handled")),
            }
            try:
                limit = max(1, min(500, int(params.limit or 100)))
            except Exception:
                limit = 100
            return json.dumps({"status": "success", "summary": summary, "items": items[:limit]}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[IntelligenceSelfHealing] GET error: {error}", exc_info=True)
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "").strip()
            item_id = str(body.get("id") or "").strip()
            root = Path(get_data_root()) / "intelligence_center"
            if action in {"mark_handled", "ignore"}:
                if not item_id:
                    raise ValueError("缺少自愈记录 ID")
                handled = self._handled_map(root)
                handled[item_id] = {
                    "handled_at": datetime.datetime.now().isoformat(timespec="seconds"),
                    "reason": str(body.get("reason") or ("已忽略" if action == "ignore" else "已处理"))[:200],
                    "action": action,
                }
                self._save_handled(root, handled)
                return json.dumps({"status": "success", "message": "已标记处理"}, ensure_ascii=False)
            if action == "retry_pending":
                pending_id = str(body.get("pending_id") or "").strip()
                if not pending_id:
                    raise ValueError("缺少待补发记录 ID")
                from plugins.intelligence_center.notifications import NotificationDispatcher
                result = NotificationDispatcher.process_pending_delivery_ids([pending_id], limit=1)
                if item_id and result.get("delivered"):
                    handled = self._handled_map(root)
                    handled[item_id] = {
                        "handled_at": datetime.datetime.now().isoformat(timespec="seconds"),
                        "reason": "已补发成功",
                        "action": action,
                    }
                    self._save_handled(root, handled)
                return json.dumps({"status": "success", "message": f"已尝试补发，成功 {result.get('delivered', 0)} 条", **result}, ensure_ascii=False)
            if action in {"retry_visible_pending", "mark_visible_handled", "mute_visible_24h"}:
                query = body.get("query") or ""
                status = body.get("status") or ""
                kind = body.get("kind") or ""
                channel = body.get("channel") or ""
                items = self._filter_items(self._all_items(root), query, status, kind, channel)
                if action == "retry_visible_pending":
                    pending_ids = []
                    for item in items:
                        details = item.get("details") if isinstance(item.get("details"), dict) else {}
                        pending_id = str(details.get("pending_id") or "").strip()
                        if item.get("action") == "pending_pending" and pending_id and not item.get("handled"):
                            pending_ids.append(pending_id)
                    if not pending_ids:
                        return json.dumps({"status": "success", "message": "当前筛选结果没有待补发消息", "processed": 0, "delivered": 0}, ensure_ascii=False)
                    from plugins.intelligence_center.notifications import NotificationDispatcher
                    result = NotificationDispatcher.process_pending_delivery_ids(pending_ids[:50], limit=50)
                    return json.dumps({"status": "success", "message": f"已批量尝试补发 {len(pending_ids[:50])} 条，成功 {result.get('delivered', 0)} 条", **result}, ensure_ascii=False)
                handled = self._handled_map(root)
                now = datetime.datetime.now().isoformat(timespec="seconds")
                candidates = [item for item in items if not item.get("handled") and (item.get("status") in {"failed", "warning"} or item.get("action") == "pending_pending")]
                if action == "mute_visible_24h":
                    candidates = self._recent_items(candidates, 24)
                    reason = str(body.get("reason") or "同类问题 24 小时内已降噪")[:200]
                    action_name = "mute_visible_24h"
                else:
                    reason = str(body.get("reason") or "批量标记已处理")[:200]
                    action_name = "mark_visible_handled"
                for item in candidates[:200]:
                    handled[item.get("id")] = {"handled_at": now, "reason": reason, "action": action_name}
                self._save_handled(root, handled)
                return json.dumps({"status": "success", "message": f"已处理 {len(candidates[:200])} 条自愈记录", "updated": len(candidates[:200])}, ensure_ascii=False)
            return json.dumps({"status": "error", "message": "未知操作"}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[IntelligenceSelfHealing] POST error: {error}", exc_info=True)
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


def _platform_services():
    from plugins.intelligence_center.platform_features import ApprovalStore, NaturalTaskService, TemplateRecordingStore
    root = os.path.join(get_data_root(), "intelligence_center")
    return NaturalTaskService(root, conf()), ApprovalStore(root), TemplateRecordingStore(root)


def _approval_executor_registry():
    from intelligence_center.approval_execution import ApprovalExecutorRegistry
    registry = ApprovalExecutorRegistry()

    def send_email(preview, _item):
        recipient=str(preview.get("recipient") or "").strip()
        subject=str(preview.get("subject") or "").strip()
        body=str(preview.get("body") or "")
        if not recipient or not subject:
            raise ValueError("邮件审批内容缺少收件人或主题")
        _email_secretary_service()._send(recipient,subject,body)
        return {"success":True,"channel":"email","recipient":recipient,"subject":subject}

    registry.register("send_email",send_email,"发送已审批的邮件")

    def resume_tool_bundle(_preview, item):
        from intelligence_center.approval_broker import approval_broker
        resumed = approval_broker.resolve(item.get("id", ""), "approved")
        return {"success": True, "resumed": resumed,
                "message": "原任务已继续执行" if resumed else "原运行已结束，审批记录已保留"}

    registry.register("tool_bundle",resume_tool_bundle,"批准并继续原任务中的组合工具操作")

    def resume_remote_bridge_command(preview, item):
        return RemoteBridgeHandler._approve_command(preview, item)

    registry.register("remote_bridge_command", resume_remote_bridge_command, "批准远程 Bridge 指令并进入统一任务路由")
    registry.register("harness_policy_patch", lambda preview, item: HarnessEvolutionHandler._service().apply_approved_patch(preview, item), "批准后备份、应用并校验自我优化策略")
    return registry


class IntelligenceNaturalTaskHandler:
    @staticmethod
    def _with_learning_context(prompt):
        prompt = str(prompt or "").strip()
        try:
            from intelligence_center.home_learning import learning_prompt_context
            context = learning_prompt_context(os.path.join(get_data_root(), "intelligence_center"))
        except Exception:
            context = ""
        try:
            from intelligence_center.fact_store import get_fact_store
            store = get_fact_store(os.path.join(get_data_root(), "intelligence_center"))
            facts = []
            for fact_type in ("output_preference", "source_preference", "notification_preference", "reuse_pattern"):
                facts.extend(store.search("", fact_type, 5))
            if facts:
                fact_lines = []
                labels = {
                    "output_preference": "输出偏好",
                    "source_preference": "来源偏好",
                    "notification_preference": "通知偏好",
                    "reuse_pattern": "复用方法",
                }
                for item in facts[:12]:
                    fact_lines.append(f"- {labels.get(item.get('fact_type'), item.get('fact_type'))}：{item.get('content')}")
                context = (context + "\n\n" if context else "") + "【本地事实库偏好】\n" + "\n".join(fact_lines)
        except Exception:
            pass
        if not context:
            return prompt
        return f"{prompt}\n\n{context}\n请优先按用户原始需求创建任务；仅在需求不明确时参考以上偏好补全来源、输出方式和工具路线。"

    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            parser, _, _ = _platform_services()
            draft = parser.parse(self._with_learning_context(body.get("prompt", ""))) if not body.get("draft") else body["draft"]
            if body.get("action", "parse") == "parse":
                return json.dumps({"status": "success", "draft": draft}, ensure_ascii=False)
            if not draft.get("can_create", True):
                raise ValueError("还需补充：" + "、".join(draft.get("missing") or []))
            kind, payload = draft["kind"], draft["payload"]
            if not payload.get("notifications"):
                prompt_text = str(draft.get("prompt") or body.get("prompt") or "")
                if "web" in prompt_text.lower() or "当前Web" in prompt_text or "网页会话" in prompt_text:
                    payload["notifications"] = [{"type": "channel", "channel": "web", "receiver": str(body.get("session_id") or "web_user")}]
            if kind == "news": task = _news_assistant_service().save_task(payload)
            elif kind == "github": task = _github_monitor_service().save_task(payload)
            elif kind == "website": task = _website_monitor_service().save_task(payload)
            elif kind == "briefing": task = _daily_briefing_service().save_task(payload)
            elif kind == "email": task = _email_secretary_service().save_task(payload)
            else: task = _extended_task_service().save_task(payload)
            # Rebuild the canonical index immediately after creation.
            _automation_hub_service().list_tasks()
            return json.dumps({"status": "success", "task": task, "kind": kind}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


class IntelligenceDashboardHandler:
    def GET(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            _, approvals, _ = _platform_services(); hub = _automation_hub_service()
            task_data = hub.list_tasks(); record_result = hub.records(limit=5); records = record_result["items"]
            tasks = task_data["tasks"]
            return json.dumps({"status":"success","summary":{
                "tasks":len(tasks),"enabled":sum(1 for x in tasks if x.get("enabled")),
                "reports_today":sum(1 for x in records if x.get("date")==datetime.datetime.now().astimezone().strftime("%Y-%m-%d")),
                "pending_approvals":len(approvals.list("pending")),
                "failed":sum(1 for x in tasks if any(k in str(x.get("last_status", "")) for k in ("失败","异常","错误"))),
            },"recent_records":records[:5],"tasks":tasks},ensure_ascii=False)
        except Exception as error: return json.dumps({"status":"error","message":str(error)},ensure_ascii=False)


class AgentCapabilitySummaryHandler:
    """Lightweight capability overview for the common-functions home."""

    def GET(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            return json.dumps(self._build_payload(), ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            root = os.path.join(get_data_root(), "intelligence_center")
            body = json.loads(web.data() or b"{}")
            prefs = self._suggestion_preferences(root)
            action = str(body.get("action") or "").strip()
            target = str(body.get("target") or "").strip()
            if action not in {"open", "pin", "unpin", "dismiss", "dislike", "reset"}:
                raise ValueError("不支持的首页建议操作")
            pinned = set(prefs.get("pinned") or [])
            hidden = dict(prefs.get("hidden") or {})
            stats = dict(prefs.get("stats") or {})
            if action == "reset":
                pinned, hidden, stats = set(), {}, {}
            elif not target:
                raise ValueError("缺少建议编号")
            else:
                stats = self._record_suggestion_event(stats, target, action)
            if action == "open":
                hidden.pop(target, None)
            elif action == "pin":
                pinned.add(target); hidden.pop(target, None)
            elif action == "unpin":
                pinned.discard(target)
            elif action in {"dismiss", "dislike"}:
                hidden[target] = {
                    "reason": "不感兴趣" if action == "dislike" else "已关闭",
                    "at": datetime.datetime.now().astimezone().isoformat(timespec="seconds"),
                }
                pinned.discard(target)
            prefs = {
                "version": 1,
                "updated_at": datetime.datetime.now().astimezone().isoformat(timespec="seconds"),
                "pinned": sorted(pinned),
                "hidden": hidden,
                "stats": stats,
            }
            self._write_suggestion_preferences(root, prefs)
            return json.dumps({"status": "success", "preferences": prefs, **self._build_payload()}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    @classmethod
    def _build_payload(cls):
        root = os.path.join(get_data_root(), "intelligence_center")
        automation = cls._automation_summary()
        maintenance = cls._maintenance_summary()
        agent2 = cls._agent2_summary()
        channels = cls._channel_summary()
        agent_reach = cls._agent_reach_summary()
        scrapling = cls._scrapling_summary()
        artifacts = cls._artifact_summary(root)
        personal = cls._personal_signal(root)
        activity = cls._activity_signal()
        preferences = cls._suggestion_preferences(root)
        cards = [
            cls._card("automation", "AI 自动化", "fa-wand-magic-sparkles", automation["status"], automation["label"], automation["summary"], "intelligence", "打开自动化"),
            cls._card("agent2", "Agent 2.0", "fa-brain", agent2["status"], agent2["label"], agent2["summary"], "agent2", "查看能力"),
            cls._card("channels", "通知通道", "fa-tower-broadcast", channels["status"], channels["label"], channels["summary"], "channels", "配置通道"),
            cls._card("maintenance", "维护看板", "fa-stethoscope", maintenance["status"], maintenance["label"], maintenance["summary"], "maintenance", "查看维护"),
            cls._card("agent_reach", "互联网底座", "fa-satellite", agent_reach["status"], agent_reach["label"], agent_reach["summary"], "agent-reach", "检查来源"),
            cls._card("scrapling", "网页提取", "fa-file-lines", scrapling["status"], scrapling["label"], scrapling["summary"], "quick-learning", "快速学习"),
            cls._card("artifacts", "产物沉淀", "fa-box-archive", artifacts["status"], artifacts["label"], artifacts["summary"], "artifacts", "查看产物"),
        ]
        overall = "success"
        if any(item["status"] == "error" for item in cards):
            overall = "error"
        elif any(item["status"] == "warning" for item in cards):
            overall = "warning"
        quick_actions = [
            {"label": "一句话新建自动化", "target": "intelligence", "icon": "fa-plus", "tone": "primary"},
            {"label": "运行维护看板", "target": "maintenance", "icon": "fa-stethoscope", "tone": "cyan"},
            {"label": "配置通知通道", "target": "channels", "icon": "fa-bell", "tone": "amber"},
            {"label": "查看任务结果", "target": "artifacts", "icon": "fa-box-archive", "tone": "emerald"},
        ]
        suggestions = cls._apply_suggestion_preferences(cls._daily_suggestions(cards, overall, personal, activity), preferences)
        return {
            "status": "success",
            "overall": overall,
            "checked_at": datetime.datetime.now().isoformat(timespec="seconds"),
            "cards": cards,
            "quick_actions": quick_actions,
            "suggestions": suggestions,
            "personal_context": personal,
            "activity": activity,
            "suggestion_preferences": preferences,
        }

    @staticmethod
    def _card(key, title, icon, status, label, summary, target, action_label):
        return {"key": key, "title": title, "icon": icon, "status": status, "label": label, "summary": summary, "target": target, "action_label": action_label}

