class MissionControlHandler:
    """Read-only cockpit that combines automation, messages, approvals and artifacts."""

    def GET(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8'); web.header('Cache-Control', 'no-store')
        try:
            return json.dumps(self._build_payload(), ensure_ascii=False)
        except Exception as error:
            logger.error(f"[WebChannel] Mission control API error: {error}")
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8'); web.header('Cache-Control', 'no-store')
        try:
            body = json.loads(web.data() or b"{}")
            if str(body.get("action") or "") == "weixin_repair":
                result = self._run_weixin_repair_action(str(body.get("repair") or ""))
                return json.dumps({"status": "success", **result}, ensure_ascii=False)
            if str(body.get("action") or "") == "today_task_run":
                result = self._run_today_task(str(body.get("kind") or ""), str(body.get("task_id") or ""))
                return json.dumps({"status": "success", **result}, ensure_ascii=False)
            if str(body.get("action") or "") == "today_task_toggle":
                result = self._toggle_today_task(str(body.get("kind") or ""), str(body.get("task_id") or ""), bool(body.get("enabled")))
                return json.dumps({"status": "success", **result}, ensure_ascii=False)
            if str(body.get("action") or "") == "record_outcome":
                result = self._record_command_learning(
                    str(body.get("command") or ""),
                    body.get("decision") if isinstance(body.get("decision"), dict) else {},
                    str(body.get("outcome") or "planned"),
                    str(body.get("message") or ""),
                    source=str(body.get("source") or "web"),
                    channel=str(body.get("channel") or "web"),
                )
                return json.dumps({"status": "success", "learning": result}, ensure_ascii=False)
            command = str(body.get("command") or body.get("query") or "").strip()
            if not command:
                raise ValueError("请输入要执行的指令")
            result = self._route_external_command(
                command,
                source=str(body.get("source") or "web"),
                channel=str(body.get("channel") or "web"),
                metadata=body.get("metadata") if isinstance(body.get("metadata"), dict) else {},
            )
            return json.dumps({"status": "success", **result}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    @classmethod
    def _route_external_command(cls, command, source="web", channel="web", metadata=None, payload=None):
        """Route Web/WeChat/Remote commands through one safe Mission Control path.

        This does not grant extra permission. It only normalizes the route and
        records where the command came from so success/failure learning can be
        reused across entrances.
        """
        command = str(command or "").strip()
        if not command:
            raise ValueError("指令为空")
        payload = payload if isinstance(payload, dict) else cls._build_payload()
        decision = cls._decide_command(command, payload)
        decision["source"] = str(source or channel or "web")
        decision["source_channel"] = str(channel or source or "web")
        learning_route = cls._mission_learning_route(command, payload, decision)
        if learning_route:
            decision["learning_route"] = learning_route
            if decision.get("intent") in {"open_automation"} and learning_route.get("preferred_target"):
                decision["target"] = learning_route["preferred_target"]
                decision["message"] = learning_route.get("message") or decision.get("message") or "已按学习经验选择更合适的入口。"
        if isinstance(metadata, dict) and metadata:
            decision["metadata"] = {k: v for k, v in metadata.items() if isinstance(k, str)}
        cls._record_command_learning(
            command,
            decision,
            "planned",
            decision.get("message", ""),
            source=decision.get("source"),
            channel=decision.get("source_channel"),
            metadata=decision.get("metadata") if isinstance(decision.get("metadata"), dict) else {},
        )
        return {"decision": decision, "payload": payload}

    @classmethod
    def _mission_learning_route(cls, command, payload, decision=None):
        """Best-effort learned routing hints shared by Web, WeChat and Bridge.

        The result can only change safe UI routing priority. It must not grant
        permission, send messages, install tools, delete files or bypass
        approval.
        """
        text = str(command or "")
        lowered = text.lower()
        decision = decision if isinstance(decision, dict) else {}
        agent_learning = payload.get("agent_learning") if isinstance(payload, dict) else {}
        if not isinstance(agent_learning, dict):
            agent_learning = {}
        hints = []
        cautions = []
        preferred = ""

        def add_hint(value):
            value = str(value or "").strip()
            if value and value not in hints:
                hints.append(value)

        def add_caution(value):
            value = str(value or "").strip()
            if value and value not in cautions:
                cautions.append(value)

        def text_has(*tokens):
            return any(str(token).lower() in lowered for token in tokens)

        try:
            if text_has("新闻", "资讯", "搜索", "政策", "财税", "rss", "github", "网站"):
                preferred = "network-search"
                for item in agent_learning.get("recovery_paths") or []:
                    raw = f"{item.get('category') or ''} {item.get('action') or ''}".lower()
                    if any(token in raw for token in ("search", "empty", "搜索", "来源", "7天", "7 天")) and int(item.get("successes") or 0) > 0:
                        add_hint("搜索类任务优先复用空结果兜底：放宽时间范围/减少筛选词/切换来源")
                        break
            if text_has("微信", "企业微信", "助理小爱", "发送", "通知", "webhook", "邮箱"):
                for item in agent_learning.get("weixin_success_learning") or []:
                    label = item.get("label") or item.get("action") or ""
                    if label:
                        add_hint(f"微信端优先复用成功路径：{label}")
                        break
                for item in agent_learning.get("weixin_failure_learning") or []:
                    category = str(item.get("category") or "")
                    if category in {"send_failure", "model_auth", "email_config", "permission"}:
                        add_caution(item.get("recommended_action") or item.get("lesson") or "微信端存在历史失败，先走确定性工具，失败后再说明")
                        if not preferred:
                            preferred = "channels"
                        break
            if text_has("失败", "异常", "无内容", "重试", "修复", "恢复"):
                preferred = "failed_runs"
                if agent_learning.get("recovery_paths"):
                    add_hint("失败任务优先按历史有效恢复路径重试")
            if text_has("维护", "健康", "缓存", "日志", "体检"):
                preferred = "maintenance"
            for item in agent_learning.get("deprioritized_skills") or []:
                name = str(item.get("name") or "")
                if name and name.lower() in lowered:
                    add_caution(f"{name} 曾被回滚，本次降低激进修补优先级")
        except Exception as error:
            logger.debug(f"[MissionControl] learning route parse failed: {error}")

        if not hints and not cautions and not preferred:
            return {}
        target = preferred or decision.get("target") or ""
        message = ""
        if preferred and preferred != decision.get("target"):
            label = {
                "network-search": "网络搜索 Agent",
                "channels": "通道与连接",
                "failed_runs": "失败任务恢复",
                "maintenance": "维护看板",
            }.get(preferred, preferred)
            message = f"已按本机学习经验优先路由到「{label}」。"
        return {
            "preferred_target": preferred,
            "target": target,
            "hints": hints[:4],
            "cautions": cautions[:4],
            "message": message,
        }

    @classmethod
    def _build_payload(cls):
        root = os.path.join(get_data_root(), "intelligence_center")
        checked_at = datetime.datetime.now().astimezone().isoformat(timespec="seconds")
        capability = cls._safe("capability", AgentCapabilitySummaryHandler._build_payload, {})
        maintenance = cls._safe("maintenance", MaintenanceDashboardHandler._build_payload, {})
        tasks = cls._automation_tasks()
        runs = cls._recent_runs(root)
        cls._sync_quick_action_execution_outcomes(root, runs)
        artifacts = cls._recent_artifacts()
        approvals = cls._pending_approvals(root)
        inbox = cls._unread_inbox(root)
        remote_bridge = cls._remote_bridge_summary()
        todos = cls._mission_todos(capability, maintenance, runs, approvals, inbox, remote_bridge)
        today_tasks = cls._today_tasks(tasks, runs)
        agent_learning = cls._agent_learning_summary()
        failed_count = sum(1 for item in runs if item.get("status") in ("failed", "empty"))
        running_count = sum(1 for item in runs if item.get("status") == "running")
        instance_guard_alert = maintenance.get("instance_guard_alert") or {}
        summary = {
            "tasks": len(tasks),
            "enabled_tasks": sum(1 for item in tasks if item.get("enabled", True)),
            "pending_approvals": len(approvals),
            "unread_messages": int((inbox.get("summary") or {}).get("unread") or len(inbox.get("items") or [])),
            "recent_artifacts": len(artifacts),
            "recent_failures": failed_count,
            "running": running_count,
            "remote_pending_commands": remote_bridge.get("pending") or 0,
            "remote_routed_commands": remote_bridge.get("routed") or 0,
            "pending_memories": int((agent_learning.get("summary") or {}).get("pending_memories") or 0),
            "instance_guard_skips_today": int((maintenance.get("summary") or {}).get("instance_guard_skips_today") or 0),
            "instance_guard_skips_7d": int((maintenance.get("summary") or {}).get("instance_guard_skips_7d") or 0),
        }
        overall = capability.get("overall") or capability.get("status") or "warning"
        if failed_count or approvals or remote_bridge.get("pending") or instance_guard_alert.get("active"):
            overall = "warning" if overall != "error" else "error"
        return {
            "status": "success",
            "overall": overall,
            "checked_at": checked_at,
            "summary": summary,
            "cards": capability.get("cards") or [],
            "today_tasks": today_tasks,
            "quick_actions": cls._quick_actions(summary, todos, root, agent_learning),
            "recent_runs": runs[:8],
            "recent_artifacts": artifacts[:8],
            "pending_approvals": approvals[:5],
            "inbox": inbox,
            "remote_bridge": remote_bridge,
            "todos": todos[:8],
            "maintenance": {
                "status": maintenance.get("status") or "warning",
                "summary": maintenance.get("summary") or {},
                "latest": maintenance.get("latest") or {},
                "cache": maintenance.get("cache") or {},
                "notifications": maintenance.get("notifications") or {},
                "instance_guard_alert": instance_guard_alert,
            },
            "command_learning": cls._command_learning(root),
            "weixin_failure_learning": cls._weixin_failure_learning(),
            "weixin_success_learning": cls._weixin_success_learning(),
            "agent_learning": agent_learning,
            "personal_context": capability.get("personal_context") or {},
        }

    @staticmethod
    def _safe(label, func, fallback):
        try:
            value = func()
            return value if isinstance(value, dict) else fallback
        except Exception as error:
            logger.debug(f"[MissionControl] {label} unavailable: {error}")
            return fallback

    @staticmethod
    def _automation_tasks():
        try:
            result = _automation_hub_service().list_tasks()
            return result.get("tasks") or []
        except Exception as error:
            logger.debug(f"[MissionControl] tasks unavailable: {error}")
            return []

    @staticmethod
    def _today_tasks(tasks, runs):
        """Small, safe list for the daily workbench: enabled tasks + recent status."""
        latest_by_task = {}
        for run in runs or []:
            task_id = str(run.get("task_id") or "")
            if task_id and task_id not in latest_by_task:
                latest_by_task[task_id] = run
        output = []
        enabled = [item for item in (tasks or []) if item.get("enabled", True)]
        enabled = sorted(enabled, key=lambda item: item.get("next_run_at") or item.get("next_run") or item.get("created_at") or "", reverse=False)
        for item in enabled[:8]:
            task_id = str(item.get("id") or item.get("task_id") or "")
            latest = latest_by_task.get(task_id) or {}
            status = latest.get("status") or "success"
            label_map = {"success": "已启用", "failed": "最近失败", "empty": "最近无内容", "running": "运行中", "warning": "需关注"}
            next_run = item.get("next_run_at") or item.get("next_run") or item.get("schedule_text") or ""
            output.append({
                "id": task_id,
                "kind": item.get("kind") or item.get("task_type") or item.get("type") or "",
                "name": item.get("name") or item.get("title") or "未命名任务",
                "type": item.get("type_label") or item.get("kind_label") or item.get("task_type") or item.get("kind") or "自动化任务",
                "summary": latest.get("summary") or latest.get("result_summary") or item.get("description") or item.get("prompt") or "等待下一次执行",
                "status": status,
                "status_label": label_map.get(status, "已启用"),
                "next_run": next_run,
                "next_run_text": next_run or "待调度",
                "latest_run_id": latest.get("id") or "",
                "enabled": item.get("enabled", True),
            })
        return output

    @staticmethod
    def _automation_service_factory(kind):
        services = {
            "news": _news_assistant_service,
            "github": _github_monitor_service,
            "website": _website_monitor_service,
            "forex": _forex_query_service,
            "briefing": _daily_briefing_service,
            "social": _extended_task_service,
            "product": _extended_task_service,
            "ops": _extended_task_service,
            "email": _email_secretary_service,
            "maintenance": _maintenance_task_service,
        }
        return services.get(str(kind or ""))

    @classmethod
    def _run_today_task(cls, kind, task_id):
        kind = str(kind or "").strip()
        task_id = str(task_id or "").strip()
        if not kind or not task_id:
            raise ValueError("缺少任务类型或任务编号")
        factory = cls._automation_service_factory(kind)
        if not factory:
            raise ValueError(f"暂不支持在今日工作台直接执行该任务类型：{kind}")
        service = factory()
        result = service.run(task_id, "manual")
        run_id = str(result.get("run_id") or "")
        run = _automation_run_service().get(run_id) if run_id else {}
        return {
            "message": "任务已执行完成" if run.get("status") == "success" else (run.get("result_summary") or run.get("failure_reason") or run.get("empty_reason") or "任务已执行，结果已记录"),
            "run_id": run_id,
            "run": run,
            **result,
        }

    @classmethod
    def _toggle_today_task(cls, kind, task_id, enabled):
        kind = str(kind or "").strip()
        task_id = str(task_id or "").strip()
        if not kind or not task_id:
            raise ValueError("缺少任务类型或任务编号")
        task = _automation_hub_service().update_task(kind, task_id, {"enabled": bool(enabled)})
        return {
            "message": "任务已启用" if enabled else "任务已暂停",
            "task": _safe_intelligence_tasks([task])[0],
        }

    @classmethod
    def _recent_runs(cls, root):
        try:
            runs = _automation_run_service().list(limit=30, offset=0).get("items") or []
        except Exception:
            runs = MaintenanceDashboardHandler._automation_runs(root)
        runs = sorted(runs, key=lambda item: item.get("finished_at") or item.get("started_at") or item.get("created_at") or "", reverse=True)
        label_map = {"success": "成功", "failed": "失败", "empty": "无内容", "running": "运行中"}
        output = []
        for item in runs[:12]:
            actions = [str(x) for x in (item.get("recovery_actions") or []) if str(x).strip()]
            output.append({
                "id": item.get("id") or "",
                "task_id": item.get("task_id") or "",
                "task_name": item.get("task_name") or item.get("name") or "未命名任务",
                "kind": item.get("kind") or item.get("task_type") or "",
                "status": item.get("status") or "unknown",
                "status_label": label_map.get(item.get("status"), item.get("status") or "未知"),
                "trigger": item.get("trigger") or "",
                "at": item.get("finished_at") or item.get("started_at") or item.get("created_at") or "",
                "summary": item.get("result_summary") or item.get("error") or item.get("failure_reason") or item.get("empty_reason") or "暂无摘要",
                "recovery_summary": item.get("recovery_summary") or ("；".join(actions[:3]) if actions else ""),
                "notification_warning": bool(item.get("notification_failure") or item.get("web_fallback_notification")),
                "artifact_id": (item.get("artifact") or {}).get("id", ""),
            })
        return output

