class ToolConnectorsHandler:
    CONFIG_FILE = "tool_connectors.json"

    def _base_dir(self):
        base = os.path.join(get_data_root(), "integrations")
        os.makedirs(base, exist_ok=True)
        return base

    def _config_path(self):
        return os.path.join(self._base_dir(), self.CONFIG_FILE)

    def _load_tools(self):
        path = self._config_path()
        if not os.path.exists(path):
            return []
        try:
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            if isinstance(data, dict):
                data = data.get("tools", [])
            return data if isinstance(data, list) else []
        except Exception as error:
            logger.warning(f"[WebChannel] Tool connectors load failed: {error}")
            return []

    def _save_tools(self, tools):
        path = self._config_path()
        tmp = f"{path}.tmp"
        payload = {
            "version": 1,
            "updated_at": datetime.datetime.now().isoformat(timespec="seconds"),
            "tools": tools,
        }
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
        os.replace(tmp, path)
        self._sync_mcp_config(tools)

    def _clean_tool(self, raw, old=None):
        old = old or {}
        item = {
            "id": str(raw.get("id") or old.get("id") or f"tool_{uuid.uuid4().hex[:12]}"),
            "name": str(raw.get("name") or old.get("name") or "").strip(),
            "type": str(raw.get("type") or old.get("type") or "mcp").strip().lower(),
            "command": str(raw.get("command") or old.get("command") or "").strip(),
            "desc": str(raw.get("desc") or old.get("desc") or "").strip(),
            "tags": str(raw.get("tags") or old.get("tags") or "").strip(),
            "scopes": raw.get("scopes") if isinstance(raw.get("scopes"), list) else old.get("scopes", ["read"]),
            "enabled": bool(raw.get("enabled", old.get("enabled", True))),
            "created_at": old.get("created_at") or datetime.datetime.now().isoformat(timespec="seconds"),
            "updated_at": datetime.datetime.now().isoformat(timespec="seconds"),
        }
        item["type"] = "cli" if item["type"] == "cli" else "mcp"
        allowed = {"read", "write", "send", "execute"}
        item["scopes"] = [scope for scope in item["scopes"] if scope in allowed] or ["read"]
        if not item["name"]:
            raise ValueError("请填写工具名称")
        if not item["command"]:
            raise ValueError("请填写启动命令或 MCP 配置")
        return item

    def _mcp_path(self):
        try:
            from common.state_dir import mcp_config_file
            return str(mcp_config_file(base=_get_workspace_root()))
        except Exception:
            return os.path.join(_get_workspace_root(), "mcp.json")

    def _mcp_server_name(self, item):
        base = re.sub(r"[^A-Za-z0-9_.-]+", "-", item.get("name", "").strip()).strip("-").lower()
        return f"cow-{base or item['id']}"

    def _parse_mcp_config(self, item):
        text = item.get("command", "").strip()
        try:
            cfg = json.loads(text)
            if isinstance(cfg, dict):
                if "command" in cfg or "url" in cfg:
                    return cfg
                if "mcpServers" in cfg and isinstance(cfg["mcpServers"], dict):
                    first = next(iter(cfg["mcpServers"].values()), None)
                    if isinstance(first, dict):
                        return first
        except Exception:
            pass
        parts = text.split()
        if not parts:
            raise ValueError("MCP 配置为空")
        return {"command": parts[0], "args": parts[1:]}

    def _command_candidates(self, command):
        """Return likely executable paths for PATH-less desktop/runtime installs."""
        raw = str(command or "").strip().strip('"')
        if not raw:
            return []
        names = [raw]
        base_name = os.path.basename(raw)
        if os.name == "nt":
            extensions = ["", ".cmd", ".exe", ".bat"]
            if not os.path.splitext(raw)[1]:
                names = [raw + ext for ext in extensions]
            if base_name and base_name != raw and not os.path.splitext(base_name)[1]:
                names.extend([base_name + ext for ext in extensions])

        roots = []
        try:
            _activate_isolated_skill_runtime(_get_workspace_root())
        except Exception:
            pass
        for root in [
            os.path.dirname(sys.executable),
            os.path.join(_get_workspace_root(), ".venv", "Scripts"),
            os.path.join(_get_workspace_root(), ".skill-runtime", "node", "node_modules", ".bin"),
            os.path.join(_get_workspace_root(), ".skill-runtime", "bin"),
            os.path.join(_get_workspace_root(), ".skill-runtime", "node", "bin"),
        ]:
            if root:
                roots.append(root)
        for env_name in ("PATH", "Path"):
            for root in os.environ.get(env_name, "").split(os.pathsep):
                if root:
                    roots.append(root)

        candidates = []
        if os.path.isabs(raw):
            candidates.append(raw)
        for found_name in dict.fromkeys(names):
            found = shutil.which(found_name)
            if found:
                candidates.append(found)
            for root in dict.fromkeys(roots):
                candidates.append(os.path.abspath(os.path.join(root, found_name)))
        if raw.lower() in {"python", "python.exe"} and sys.executable:
            candidates.insert(0, sys.executable)
        return list(dict.fromkeys(candidates))

    def _find_command(self, command):
        for candidate in self._command_candidates(command):
            try:
                if os.path.isfile(candidate):
                    return candidate
            except Exception:
                continue
        return ""

    def _replace_command_head(self, item, resolved):
        updated = {**item}
        if item.get("type") == "mcp":
            cfg = self._parse_mcp_config(item)
            if cfg.get("command"):
                cfg["command"] = resolved
                updated["command"] = json.dumps(cfg, ensure_ascii=False)
            return updated
        parts = updated.get("command", "").split()
        if parts:
            parts[0] = f'"{resolved}"' if " " in resolved and not resolved.startswith('"') else resolved
            updated["command"] = " ".join(parts)
        return updated

    def _repair_item(self, item):
        head = self._command_head(item)
        if not head:
            return item, {"ok": False, "message": "未填写可修复的命令"}
        if re.match(r"https?://", head):
            return item, {"ok": True, "message": "远程地址无需本地修复"}
        resolved = self._find_command(head)
        if resolved:
            repaired = self._replace_command_head(item, resolved)
            repaired["updated_at"] = datetime.datetime.now().isoformat(timespec="seconds")
            return repaired, {"ok": True, "path": resolved, "message": "已找到本机可用运行时，并自动回写完整命令路径"}
        lowered = os.path.basename(head).lower()
        if lowered.startswith("agent-reach"):
            return item, {
                "ok": False,
                "repairable": True,
                "repair_action": "open_agent_reach",
                "repair_label": "打开 Agent-Reach 安装",
                "message": "当前未检测到 Agent-Reach；请在 Agent-Reach 互联网能力页安装/配置，安装完成后会自动纳入工具路由。",
            }
        return item, {"ok": False, "message": f"未找到可自动回写的本机命令：{head}"}

    def _read_mcp_root(self):
        path = self._mcp_path()
        if not os.path.exists(path):
            return {"mcpServers": {}}
        try:
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            if not isinstance(data, dict):
                return {"mcpServers": {}}
            if "mcpServers" in data and isinstance(data["mcpServers"], dict):
                return data
            if "mcp_servers" in data and isinstance(data["mcp_servers"], dict):
                return {"mcpServers": data["mcp_servers"]}
            if all(isinstance(v, dict) for v in data.values()):
                return {"mcpServers": data}
            return {"mcpServers": {}}
        except Exception as error:
            logger.warning(f"[WebChannel] MCP config read failed: {error}")
            return {"mcpServers": {}}

    def _sync_mcp_config(self, tools):
        root = self._read_mcp_root()
        servers = root.get("mcpServers") if isinstance(root.get("mcpServers"), dict) else {}
        managed_names = {self._mcp_server_name(item) for item in tools if item.get("type") == "mcp"}
        for name in list(servers.keys()):
            if name in managed_names:
                servers.pop(name, None)
        for item in tools:
            if item.get("type") != "mcp" or not item.get("enabled"):
                continue
            try:
                servers[self._mcp_server_name(item)] = self._parse_mcp_config(item)
            except Exception as error:
                logger.warning(f"[WebChannel] Skip invalid MCP connector {item.get('name')}: {error}")
        root["mcpServers"] = servers
        path = self._mcp_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = f"{path}.tmp"
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(root, handle, ensure_ascii=False, indent=2)
        os.replace(tmp, path)

    def _command_head(self, item):
        text = item.get("command", "").strip()
        if item.get("type") == "mcp":
            try:
                cfg = self._parse_mcp_config(item)
                return str(cfg.get("command") or cfg.get("url") or "").strip()
            except Exception:
                return ""
        if not text:
            return ""
        try:
            parts = shlex.split(text, posix=False)
            return parts[0].strip('"') if parts else ""
        except Exception:
            return text.split()[0].strip('"')

    def _check_item(self, item):
        head = self._command_head(item)
        if not head:
            return {"ok": False, "message": "未填写可检查的命令", "repairable": False}
        if re.match(r"https?://", head):
            return {"ok": True, "message": "远程 MCP 地址已配置，运行时连接可用性需实际调用验证。", "repairable": False}
        if os.path.isabs(head) and os.path.exists(head):
            return {"ok": True, "path": head, "message": "命令路径存在", "repairable": False}
        found = self._find_command(head)
        if found:
            return {"ok": True, "path": found, "message": "命令可用，可点击一键修复回写完整路径", "repairable": True, "repair_action": "rewrite_path", "repair_label": "回写完整路径"}
        lowered = os.path.basename(head).lower()
        hints = {
            "npx": ("请安装 Node.js，或确认 CowAgent 的 .skill-runtime/node 已初始化。", "install_runtime", "检查 Node 运行时"),
            "uvx": ("请安装 uv/uvx，或把 uvx 加入 PATH。", "install_uv", "查看 uvx 修复"),
            "python": ("当前后端未找到 Python；请使用 CowAgent 自带 venv 或安装 Python。", "rewrite_path", "回写 Python 路径"),
            "agent-reach": ("请先在 Agent-Reach 互联网能力中执行安装/更新。", "open_agent_reach", "打开 Agent-Reach 安装"),
        }
        message, action, label = hints.get(lowered, (f"当前后端未找到命令：{head}", "manual", "查看修复建议"))
        return {"ok": False, "message": message, "repairable": True, "repair_action": action, "repair_label": label}

    def _tool_stats(self, item, scores=None):
        try:
            if scores is None:
                from agent.tools.reliability import ToolReliability
                scores = ToolReliability().scores()
            names = [
                item.get("name", ""),
                self._mcp_server_name(item) if item.get("type") == "mcp" else "",
                self._command_head(item),
                f"tool-connector:{item.get('id','')}",
            ]
            for name in names:
                if name and name in scores:
                    return scores[name]
        except Exception:
            pass
        return {"score": 0.5, "success_rate": 0.5, "successes": 0, "total": 0, "recent_failures": 0}

    def _recommendation(self, item, check, stats):
        if not item.get("enabled"):
            return "未启用：不会自动优先选择。"
        if not check.get("ok"):
            return f"暂不推荐：{check.get('message', '运行条件未就绪')}"
        total = int(stats.get("total") or 0)
        if total <= 0:
            return "可试用：命令可用，但还没有历史成功率。"
        if stats.get("recent_failures", 0) >= 2:
            return "谨慎使用：最近连续失败较多，建议先检查配置。"
        if float(stats.get("success_rate") or 0) >= 0.75:
            return "优先推荐：历史成功率较高。"
        return "可用：有历史记录，按任务匹配度选择。"

    def _with_checks(self, tools):
        try:
            from agent.tools.reliability import ToolReliability
            scores = ToolReliability().scores()
        except Exception:
            scores = {}
        result = []
        for item in tools:
            check = self._check_item(item)
            stats = self._tool_stats(item, scores)
            result.append({
                **item,
                "check": check,
                "stats": stats,
                "recommendation": self._recommendation(item, check, stats),
                "mcp_server_name": self._mcp_server_name(item) if item.get("type") == "mcp" else "",
            })
        return result

    def GET(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            tools = self._load_tools()
            if not tools:
                now = datetime.datetime.now().isoformat(timespec="seconds")
                tools = [
                    {"id": "builtin_github_mcp", "name": "GitHub MCP", "type": "mcp", "command": '{"command":"npx","args":["-y","@modelcontextprotocol/server-github"]}', "desc": "读取 GitHub 仓库、Release、Issue 和 PR。", "tags": "GitHub, release, issue, 开源项目", "scopes": ["read"], "enabled": False, "created_at": now, "updated_at": now},
                    {"id": "builtin_agent_reach_cli", "name": "Agent-Reach CLI", "type": "cli", "command": "agent-reach doctor", "desc": "检查互联网来源能力，用于网页/RSS/GitHub/视频平台采集。", "tags": "agent-reach, RSS, GitHub, V2EX, 视频", "scopes": ["read", "execute"], "enabled": False, "created_at": now, "updated_at": now},
                ]
                self._save_tools(tools)
            return json.dumps({"status": "success", "tools": self._with_checks(tools), "mcp_config_path": self._mcp_path()}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[WebChannel] Tool connectors GET error: {error}")
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "save")
            tools = self._load_tools()
            if action == "save":
                raw = body.get("tool") if isinstance(body.get("tool"), dict) else body
                old = next((item for item in tools if item.get("id") == raw.get("id")), {})
                item = self._clean_tool(raw, old)
                index = next((idx for idx, current in enumerate(tools) if current.get("id") == item["id"]), -1)
                if index >= 0:
                    tools[index] = item
                else:
                    tools.append(item)
                self._save_tools(tools)
                return json.dumps({"status": "success", "tool": {**item, "check": self._check_item(item)}, "tools": self._with_checks(tools), "mcp_config_path": self._mcp_path(), "message": "工具配置已保存"}, ensure_ascii=False)
            if action == "toggle":
                target = str(body.get("id") or "")
                for item in tools:
                    if item.get("id") == target:
                        item["enabled"] = bool(body.get("enabled", not item.get("enabled")))
                        item["updated_at"] = datetime.datetime.now().isoformat(timespec="seconds")
                        break
                self._save_tools(tools)
                return json.dumps({"status": "success", "tools": self._with_checks(tools), "mcp_config_path": self._mcp_path(), "message": "工具状态已更新"}, ensure_ascii=False)
            if action == "delete":
                target = str(body.get("id") or "")
                tools = [item for item in tools if item.get("id") != target]
                self._save_tools(tools)
                return json.dumps({"status": "success", "tools": self._with_checks(tools), "mcp_config_path": self._mcp_path(), "message": "工具配置已删除"}, ensure_ascii=False)
            if action == "check":
                target = str(body.get("id") or "")
                item = next((item for item in tools if item.get("id") == target), None)
                if not item:
                    item = self._clean_tool(body.get("tool") or body)
                check = self._check_item(item)
                stats = self._tool_stats(item)
                return json.dumps({"status": "success", "check": check, "stats": stats, "recommendation": self._recommendation(item, check, stats), "tool": item}, ensure_ascii=False)
            if action == "repair":
                target = str(body.get("id") or "")
                index = next((idx for idx, current in enumerate(tools) if current.get("id") == target), -1)
                if index < 0:
                    return json.dumps({"status": "error", "message": "未找到工具配置"}, ensure_ascii=False)
                repaired, check = self._repair_item(tools[index])
                if check.get("ok"):
                    tools[index] = repaired
                    self._save_tools(tools)
                    return json.dumps({"status": "success", "tool": {**repaired, "check": self._check_item(repaired)}, "check": self._check_item(repaired), "tools": self._with_checks(tools), "mcp_config_path": self._mcp_path(), "message": check.get("message", "修复完成")}, ensure_ascii=False)
                return json.dumps({"status": "error", "check": check, "tools": self._with_checks(tools), "message": check.get("message", "当前工具需要手动处理")}, ensure_ascii=False)
            if action == "record_result":
                target = str(body.get("id") or "")
                item = next((item for item in tools if item.get("id") == target), None)
                if not item:
                    return json.dumps({"status": "error", "message": "未找到工具配置"}, ensure_ascii=False)
                success = bool(body.get("success"))
                try:
                    from agent.tools.audit import record_tool_run
                    record_tool_run(
                        f"tool-connector:{item.get('id','')}",
                        {"name": item.get("name"), "type": item.get("type"), "command": item.get("command")},
                        success,
                        status="success" if success else "error",
                        result=body.get("message") or ("手动标记成功" if success else "手动标记失败"),
                        error_code="" if success else "manual_failure",
                        intent="tool_connector",
                    )
                except Exception as audit_error:
                    logger.warning(f"[WebChannel] Tool connector audit record failed: {audit_error}")
                return json.dumps({"status": "success", "tools": self._with_checks(tools), "message": "工具经验已记录"}, ensure_ascii=False)
            if action == "sync":
                self._sync_mcp_config(tools)
                return json.dumps({"status": "success", "tools": self._with_checks(tools), "mcp_config_path": self._mcp_path(), "message": "MCP 配置已同步"}, ensure_ascii=False)
            if action == "recommend":
                task = str(body.get("task") or "")
                ranked = []
                enriched = self._with_checks(tools)
                tokens = set(re.findall(r"[a-z0-9_+-]{2,}", task.lower()))
                for run in re.findall(r"[\u4e00-\u9fff]+", task):
                    for width in (2, 3, 4):
                        tokens.update(run[i:i + width] for i in range(max(0, len(run) - width + 1)))
                for item in enriched:
                    if not item.get("enabled"):
                        continue
                    haystack = f"{item.get('name','')} {item.get('desc','')} {item.get('tags','')} {item.get('command','')}".lower()
                    fit = sum(1 for token in tokens if token and token in haystack)
                    stats = item.get("stats") or {}
                    score = fit + (0.8 if item.get("check", {}).get("ok") else -0.5) + float(stats.get("score") or 0.5)
                    ranked.append({**item, "match_score": round(score, 3)})
                ranked.sort(key=lambda item: (-item.get("match_score", 0), -float((item.get("stats") or {}).get("score", 0)), item.get("name", "")))
                return json.dumps({"status": "success", "recommendations": ranked[:5], "message": "已生成工具推荐"}, ensure_ascii=False)
            return json.dumps({"status": "error", "message": f"不支持的操作：{action}"}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[WebChannel] Tool connectors POST error: {error}")
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


class IntelligenceExplorationHandler:
    @staticmethod
    def _service():
        from intelligence_center.exploration_service import ExplorationService
        return ExplorationService(os.path.join(get_data_root(), "intelligence_center"))

    def GET(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try: return json.dumps({"status":"success","drafts":self._service().list()},ensure_ascii=False)
        except Exception as error:return json.dumps({"status":"error","message":str(error)},ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            body=json.loads(web.data() or b"{}"); action=body.get("action","analyze"); service=self._service()
            if action=="analyze": draft=service.analyze(body.get("url",""),body.get("goal",""),body.get("notes","")); return json.dumps({"status":"success","draft":draft},ensure_ascii=False)
            if action=="confirm":
                draft=service.confirm(body.get("id","")); _,_,store=_platform_services()
                template=store.save_template({"name":draft["name"],"description":draft.get("goal") or f"复刻 {draft['page_title']}","kind":"browser","prompt":draft.get("goal",""),"source_url":draft["url"],"steps":draft["steps"],"permissions":draft["permissions"],"risks":draft["risks"]})
                recording=store.save_recording({"name":draft["name"],"url":draft["url"],"steps":[x["description"] for x in draft["steps"]]})
                return json.dumps({"status":"success","draft":draft,"template":template,"recording":recording},ensure_ascii=False)
            raise ValueError("不支持的操作")
        except Exception as error:return json.dumps({"status":"error","message":str(error)},ensure_ascii=False)

    def DELETE(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try: self._service().delete(json.loads(web.data() or b"{}").get("id","")); return json.dumps({"status":"success"},ensure_ascii=False)
        except Exception as error:return json.dumps({"status":"error","message":str(error)},ensure_ascii=False)


