class MemoryWikiHandler:
    SECTIONS = [
        ("tree", "记忆树", "fa-sitemap", "agent2_service + fact_store"),
        ("profile", "用户画像", "fa-user-astronaut", "personal_agent_profile.json"),
        ("preferences", "偏好与边界", "fa-sliders", "personal_agent_profile.json"),
        ("memory", "长期记忆", "fa-brain", "memory files"),
        ("failure", "失败经验", "fa-triangle-exclamation", "agent2_service"),
        ("weixin", "微信学习", "fa-comments", "agent2_service"),
    ]

    @staticmethod
    def _root():
        return os.path.join(get_data_root(), "intelligence_center")

    @classmethod
    def _path(cls):
        return os.path.join(cls._root(), "memory_wiki.json")

    @staticmethod
    def _now():
        return datetime.datetime.now().astimezone().isoformat(timespec="seconds")

    @staticmethod
    def _read_json(path, default):
        try:
            if path and os.path.exists(path):
                with open(path, "r", encoding="utf-8") as handle:
                    return json.load(handle)
        except Exception:
            pass
        return default

    @staticmethod
    def _write_json(path, payload):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = f"{path}.tmp"
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
        os.replace(tmp, path)

    @staticmethod
    def _new_device_token():
        return base64.urlsafe_b64encode(os.urandom(32)).decode("ascii").rstrip("=")

    @staticmethod
    def _token_hash(token):
        token = str(token or "").strip()
        if not token:
            return ""
        return hashlib.sha256(token.encode("utf-8")).hexdigest()

    @classmethod
    def _store(cls):
        data = cls._read_json(cls._path(), {})
        if not isinstance(data, dict):
            data = {}
        data.setdefault("pages", {})
        data.setdefault("created_at", cls._now())
        return data

    @staticmethod
    def _lines(title, pairs):
        lines = [f"# {title}", ""]
        for name, value in pairs:
            if isinstance(value, list):
                text = "、".join(str(x) for x in value if str(x).strip()) or "未设置"
            else:
                text = str(value or "未设置")
            lines.append(f"## {name}")
            lines.append(text)
            lines.append("")
        return "\n".join(lines).strip() + "\n"

    @staticmethod
    def _compact_value(value, limit=120):
        if isinstance(value, list):
            value = "、".join(str(x) for x in value if str(x).strip())
        text = re.sub(r"\s+", " ", str(value or "")).strip()
        if len(text) <= limit:
            return text or "未设置"
        return text[:limit].rstrip("，。；、 ") + "…"

    @staticmethod
    def _list_lines(items, *, label_key="", content_key="", limit=8, empty="暂无记录。"):
        rows = []
        for item in list(items or [])[:limit]:
            if not isinstance(item, dict):
                text = re.sub(r"\s+", " ", str(item or "")).strip()
                if text:
                    rows.append(f"- {text}")
                continue
            label = str(item.get(label_key) or item.get("title") or item.get("type") or item.get("category") or "").strip()
            content = str(item.get(content_key) or item.get("content") or item.get("lesson") or item.get("message") or item.get("description") or item.get("action") or "").strip()
            if not label and not content:
                continue
            title = label or "记录"
            summary = re.sub(r"\s+", " ", content).strip()
            if len(summary) > 120:
                summary = summary[:120].rstrip("，。；、 ") + "…"
            rows.append(f"- **{title}**：{summary or '已记录'}")
        return rows or [empty]

    @classmethod
    def _profile_section(cls, profile):
        role = profile.get("custom_role") or profile.get("role") or "未设置"
        return cls._lines("用户画像", [
            ("称呼", profile.get("preferred_name")),
            ("主要角色", role),
            ("行业与领域", profile.get("industry")),
            ("主要目标", profile.get("goals")),
            ("工作时间", profile.get("work_hours")),
            ("其他自定义需求", profile.get("custom_needs")),
            ("最后更新", profile.get("updated_at")),
        ])

    @classmethod
    def _preference_section(cls, profile):
        return cls._lines("偏好与操作边界", [
            ("关注关键词", profile.get("preferred_keywords")),
            ("常用来源", profile.get("preferred_sources")),
            ("关注文件夹", profile.get("watched_folders")),
            ("输出偏好", profile.get("output_preferences")),
            ("邮件处理偏好", profile.get("email_preferences")),
            ("审批策略", profile.get("approval_policy")),
            ("操作边界", profile.get("boundaries")),
        ])

    @classmethod
    def _memory_tree_section(cls, profile, dashboard):
        role = profile.get("custom_role") or profile.get("role") or "未设置"
        facts = []
        fact_stats = {"total": 0, "by_type": {}}
        try:
            from intelligence_center.fact_store import get_fact_store
            service = get_fact_store(cls._root())
            fact_stats = service.stats()
            facts = service.search("", "", 10)
        except Exception:
            facts = []

        source_summary = cls._compact_value(profile.get("preferred_sources"), 180)
        keyword_summary = cls._compact_value(profile.get("preferred_keywords"), 180)
        email_pref = cls._compact_value(profile.get("email_preferences"), 180)
        output_pref = cls._compact_value(profile.get("output_preferences"), 180)
        approvals = cls._compact_value(profile.get("approval_policy") or profile.get("boundaries"), 180)

        failure_rows = cls._list_lines(
            dashboard.get("error_patterns") or [],
            label_key="title",
            content_key="lesson",
            limit=6,
            empty="- 暂无高频失败经验。",
        )
        recovery_rows = cls._list_lines(
            dashboard.get("recovery_patterns") or [],
            label_key="action",
            content_key="description",
            limit=6,
            empty="- 暂无可复用恢复路径。",
        )
        weixin_success_rows = cls._list_lines(
            dashboard.get("weixin_success_patterns") or [],
            label_key="label",
            content_key="lesson",
            limit=6,
            empty="- 暂无微信成功路径。",
        )
        weixin_failure_rows = cls._list_lines(
            dashboard.get("weixin_failure_patterns") or [],
            label_key="category",
            content_key="lesson",
            limit=6,
            empty="- 暂无微信失败路径。",
        )

        fact_type_names = {
            "learning_takeaway": "学习结论",
            "learning_point": "学习要点",
            "reuse_pattern": "复用方法",
            "preference": "偏好",
            "failure_lesson": "失败经验",
            "success_path": "成功路径",
            "knowledge": "知识",
        }
        fact_rows = []
        for item in facts:
            fact_type = fact_type_names.get(item.get("fact_type"), item.get("fact_type") or "事实")
            content = re.sub(r"\s+", " ", str(item.get("content") or "")).strip()
            if len(content) > 110:
                content = content[:110].rstrip("，。；、 ") + "…"
            link = f" [来源]({item.get('source_url')})" if item.get("source_url") else ""
            fact_rows.append(f"- **{fact_type}**：{content or '已记录'}{link}")
        if not fact_rows:
            fact_rows.append("- 暂无事实库记录。后续快速学习、失败恢复、微信任务和自动化执行会逐步沉淀。")

        by_type = fact_stats.get("by_type") if isinstance(fact_stats, dict) else {}
        by_type_text = "、".join(f"{fact_type_names.get(k, k)} {v} 条" for k, v in (by_type or {}).items()) or "暂无分类"
        lines = [
            "# 记忆树",
            "",
            f"生成时间：{cls._now()}",
            "",
            "## 一、我理解的用户",
            f"- **主要角色**：{role}",
            f"- **称呼**：{cls._compact_value(profile.get('preferred_name'), 60)}",
            f"- **行业与目标**：{cls._compact_value(profile.get('industry') or profile.get('goals'), 160)}",
            "",
            "## 二、默认偏好",
            f"- **关注词**：{keyword_summary}",
            f"- **常用来源**：{source_summary}",
            f"- **输出偏好**：{output_pref}",
            f"- **邮件整理偏好**：{email_pref}",
            f"- **审批边界**：{approvals}",
            "",
            "## 三、长期事实库",
            f"- 当前共沉淀 {fact_stats.get('total', 0) if isinstance(fact_stats, dict) else 0} 条事实：{by_type_text}",
            *fact_rows,
            "",
            "## 四、成功路径",
            "### 自动恢复 / 工具路径",
            *recovery_rows,
            "",
            "### 微信任务成功路径",
            *weixin_success_rows,
            "",
            "## 五、失败经验",
            *failure_rows,
            "",
            "### 微信失败路径",
            *weixin_failure_rows,
            "",
            "## 六、生效说明",
            "- 用户画像会影响任务创建、邮件筛选、简报关注方向和推荐动作。",
            "- 常用来源和关注词会优先带入网络搜索、行业动态、竞品监控和每日简报。",
            "- 成功路径会影响微信、总控台和自动化任务的工具选择顺序。",
            "- 失败经验会触发自动兜底、推荐重试参数和维护看板提醒。",
            "",
            "## 七、手动补充",
            "可以在这里补充你希望 Agent 长期记住的规则，例如：默认忽略哪些邮件、优先使用哪些数据源、哪些动作必须审批。",
        ]
        return "\n".join(lines).strip() + "\n"

    @classmethod
    def _memory_section(cls):
        workspace = conf().get("agent_workspace") or os.path.join(get_data_root(), "cow-workspace")
        roots = [
            os.path.join(get_data_root(), "memory"),
            os.path.join(workspace, "memory"),
            os.path.join(cls._root(), "memory"),
        ]
        seen, chunks = set(), []
        for root in roots:
            if not root or not os.path.isdir(root):
                continue
            for dirpath, dirnames, filenames in os.walk(root):
                dirnames[:] = [x for x in dirnames if x not in {".git", "__pycache__", "node_modules", "cache"}]
                for name in filenames:
                    if len(chunks) >= 12:
                        break
                    if not name.lower().endswith((".md", ".txt", ".json")):
                        continue
                    path = os.path.join(dirpath, name)
                    if path in seen:
                        continue
                    seen.add(path)
                    try:
                        rel = os.path.relpath(path, root)
                        with open(path, "r", encoding="utf-8", errors="ignore") as handle:
                            text = handle.read(1600).strip()
                        if text:
                            chunks.append(f"## {rel}\n\n{text}")
                    except Exception:
                        continue
        if not chunks:
            chunks.append("暂未发现可汇总的长期记忆文件。后续 Agent 在对话、任务、失败恢复中沉淀的内容会在这里形成 Wiki 索引。")
        fact_lines = cls._fact_store_memory_lines()
        if fact_lines:
            chunks.insert(0, fact_lines)
        return "# 长期记忆\n\n" + "\n\n".join(chunks) + "\n"

    @classmethod
    def _fact_store_memory_lines(cls):
        try:
            from intelligence_center.fact_store import get_fact_store
            service = get_fact_store(cls._root())
            stats = service.stats()
            items = service.search("", "", 12)
            if not items:
                return ""
            lines = [
                "## 本地事实库 fact_store",
                "",
                f"当前已沉淀 {stats.get('total', 0)} 条事实，包含：" + "、".join(f"{k} {v} 条" for k, v in (stats.get("by_type") or {}).items()),
                "",
            ]
            type_names = {
                "learning_takeaway": "学习结论",
                "learning_point": "学习要点",
                "reuse_pattern": "复用方法",
                "preference": "用户偏好",
                "failure_lesson": "失败经验",
                "success_path": "成功路径",
            }
            for item in items:
                label = type_names.get(item.get("fact_type"), item.get("fact_type") or "事实")
                tags = "、".join(item.get("tags") or [])
                source = item.get("source") or "本地学习"
                link = f" [来源]({item.get('source_url')})" if item.get("source_url") else ""
                lines.append(f"- **{label}**：{item.get('content')}{link}")
                lines.append(f"  来源：{source}" + (f"｜标签：{tags}" if tags else "") + f"｜更新时间：{str(item.get('updated_at') or '')[:19].replace('T',' ')}")
            return "\n".join(lines)
        except Exception as error:
            return f"## 本地事实库 fact_store\n\n事实库读取失败：{error}"

    @classmethod
    def _agent2_dashboard(cls):
        try:
            return Agent2Handler._service().dashboard()
        except Exception:
            return {}

    @classmethod
    def _failure_section(cls, dashboard):
        lines = ["# 失败经验", ""]
        items = list(dashboard.get("error_patterns") or [])[:20]
        recoveries = list(dashboard.get("recovery_patterns") or [])[:20]
        if items:
            lines.append("## 重复错误")
            for item in items:
                title = item.get("title") or item.get("signature") or item.get("message") or "未命名错误"
                count = item.get("count") or item.get("hits") or 1
                lesson = item.get("lesson") or item.get("suggestion") or item.get("status") or "待分析"
                lines.append(f"- {title}（出现 {count} 次）：{lesson}")
            lines.append("")
        if recoveries:
            lines.append("## 恢复路径")
            for item in recoveries:
                action = item.get("action") or item.get("label") or item.get("type") or "恢复动作"
                rate = item.get("success_rate")
                suffix = f"，成功率 {rate}" if rate is not None else ""
                lines.append(f"- {action}{suffix}：{item.get('description') or item.get('message') or '已记录'}")
            lines.append("")
        if len(lines) <= 2:
            lines.append("暂无达到阈值的失败经验。")
        return "\n".join(lines).strip() + "\n"

    @classmethod
    def _weixin_section(cls, dashboard):
        lines = ["# 微信学习", ""]
        failures = list(dashboard.get("weixin_failure_patterns") or [])[:20]
        successes = list(dashboard.get("weixin_success_patterns") or [])[:20]
        lines.append("## 成功路径")
        if successes:
            for item in successes:
                lines.append(f"- {item.get('label') or item.get('task_type') or '微信任务成功'}：{item.get('lesson') or item.get('action') or '下次优先复用'}")
        else:
            lines.append("暂无微信成功路径。")
        lines.append("")
        lines.append("## 失败路径")
        if failures:
            for item in failures:
                lines.append(f"- {item.get('category') or 'general'}：{item.get('lesson') or item.get('message') or '待分析'}")
        else:
            lines.append("暂无微信失败路径。")
        return "\n".join(lines).strip() + "\n"

    @classmethod
    def _generated_pages(cls):
        profile = cls._read_json(os.path.join(cls._root(), "personal_agent_profile.json"), {})
        dashboard = cls._agent2_dashboard()
        return {
            "tree": cls._memory_tree_section(profile, dashboard),
            "profile": cls._profile_section(profile),
            "preferences": cls._preference_section(profile),
            "memory": cls._memory_section(),
            "failure": cls._failure_section(dashboard),
            "weixin": cls._weixin_section(dashboard),
        }

    @classmethod
    def _payload(cls):
        store = cls._store()
        generated = cls._generated_pages()
        fact_payload = cls._fact_payload()
        pages = store.get("pages") if isinstance(store.get("pages"), dict) else {}
        history = store.get("history") if isinstance(store.get("history"), dict) else {}
        sections = []
        for section_id, title, icon, source in cls.SECTIONS:
            page = pages.get(section_id) or {}
            content = page.get("content") if isinstance(page, dict) else ""
            edited_at = page.get("updated_at") if isinstance(page, dict) else ""
            page_history = history.get(section_id) if isinstance(history.get(section_id), list) else []
            effective_summary = "当前使用人工编辑内容，会优先影响后续画像、偏好和任务上下文。" if content else "当前使用系统生成内容，来源于配置、运行记录和 Agent 2.0 学习结果。"
            sections.append({
                "id": section_id,
                "title": title,
                "icon": icon,
                "source": source,
                "content": content or generated.get(section_id, ""),
                "edited": bool(content),
                "effective": True,
                "effective_summary": effective_summary,
                "history": page_history[:12],
                "updated_at": edited_at or store.get("updated_at") or "",
            })
        return {"sections": sections, "updated_at": store.get("updated_at", ""), "path": cls._path(), "fact_store": fact_payload}

    @classmethod
    def _fact_payload(cls):
        try:
            from intelligence_center.fact_store import get_fact_store
            service = get_fact_store(cls._root())
            return {"stats": service.stats(), "items": service.search("", "", 30, include_disabled=True)}
        except Exception as error:
            return {"stats": {"version": 1, "total": 0, "by_type": {}}, "items": [], "error": str(error)}

    @classmethod
    def _remember_revision(cls, store, section_id, content, source):
        content = str(content or "")
        if not content.strip():
            return
        store.setdefault("history", {})
        revisions = store["history"].setdefault(section_id, [])
        if revisions and revisions[0].get("content") == content:
            return
        revisions.insert(0, {
            "id": f"rev-{uuid.uuid4().hex[:10]}",
            "source": source,
            "content": content,
            "created_at": cls._now(),
            "summary": re.sub(r"\s+", " ", content).strip()[:90],
        })
        store["history"][section_id] = revisions[:30]

    def GET(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            return json.dumps({"status": "success", **self._payload()}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def PUT(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            section_id = str(body.get("section_id") or "").strip()
            valid = {item[0] for item in self.SECTIONS}
            if section_id not in valid:
                raise ValueError("未知的 Wiki 页面")
            content = str(body.get("content") or "").strip()
            store = self._store()
            old_page = (store.get("pages") or {}).get(section_id) or {}
            old_content = old_page.get("content") if isinstance(old_page, dict) else ""
            generated_old = self._generated_pages().get(section_id, "")
            self._remember_revision(store, section_id, old_content or generated_old, "保存前版本")
            store.setdefault("pages", {})[section_id] = {"content": content, "updated_at": self._now()}
            store["updated_at"] = self._now()
            self._write_json(self._path(), store)
            return json.dumps({"status": "success", **self._payload()}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            if body.get("action") != "regenerate":
                raise ValueError("不支持的 Memory Wiki 操作")
            section_id = str(body.get("section_id") or "").strip()
            store = self._store()
            if section_id:
                old_page = (store.get("pages") or {}).get(section_id) or {}
                old_content = old_page.get("content") if isinstance(old_page, dict) else ""
                self._remember_revision(store, section_id, old_content, "重新生成前版本")
                store.setdefault("pages", {}).pop(section_id, None)
            else:
                for sid, page in (store.get("pages") or {}).items():
                    if isinstance(page, dict):
                        self._remember_revision(store, sid, page.get("content"), "全部重新生成前版本")
                store["pages"] = {}
            store["updated_at"] = self._now()
            self._write_json(self._path(), store)
            return json.dumps({"status": "success", **self._payload()}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


class FactStoreHandler:
    @staticmethod
    def _service():
        from intelligence_center.fact_store import get_fact_store
        return get_fact_store(os.path.join(get_data_root(), "intelligence_center"))

    @staticmethod
    def _source_trace(item):
        item = item if isinstance(item, dict) else {}
        metadata = item.get("metadata") if isinstance(item.get("metadata"), dict) else {}
        actions = []

        def add(label, kind, **payload):
            label = str(label or "").strip()
            if not label:
                return
            action = {"label": label, "kind": kind, **payload}
            key = json.dumps(action, ensure_ascii=False, sort_keys=True)
            if key not in seen:
                seen.add(key)
                actions.append(action)

        seen = set()
        source = str(item.get("source") or metadata.get("source") or "").strip()
        source_type = str(metadata.get("source_type") or "").strip().lower()
        source_id = str(metadata.get("source_id") or "").strip()
        source_url = str(item.get("source_url") or metadata.get("source_url") or "").strip()
        if source_url:
            add("查看原文 / 外部来源", "url", url=source_url)
        artifact_id = str(metadata.get("artifact_id") or metadata.get("source_artifact_id") or "").strip()
        if artifact_id:
            add("打开产物/交付物", "artifact", artifact_id=artifact_id)
        run_id = str(metadata.get("run_id") or metadata.get("latest_run_id") or "").strip()
        if run_id:
            add("打开执行会话", "automation_run", run_id=run_id)
        task_id = str(metadata.get("task_id") or "").strip()
        if task_id:
            add("打开自动化任务", "automation_task", task_id=task_id)
        session_id = str(metadata.get("session_id") or metadata.get("conversation_id") or "").strip()
        channel = str(metadata.get("channel") or source or "").strip().lower()
        if session_id:
            if source_type in {"wecom", "wecom_message"} or "wecom" in channel or "企业微信" in channel:
                add("打开企业微信会话", "weixin_session", session_id=session_id, channel="wecom")
            elif source_type in {"weixin", "weixin_message"} or "weixin" in channel or "微信" in channel:
                add("打开微信会话", "weixin_session", session_id=session_id, channel="weixin")
            else:
                add("打开相关会话", "chat_session", session_id=session_id)
        if source_type == "quick_learning" or source == "快速学习 Agent" or "快速学习" in source:
            add("打开快速学习 Agent", "common_function", function_id="quick-learning")
        if source_type in {"conversation_review", "conversation_preference", "user_message"} or source == "Agent 执行复盘" or str(metadata.get("extractor") or "").startswith("explicit_rule"):
            add("打开对话", "view", view="chat")
        if source_type in {"self_training", "agent2_learning", "skill_version_rollback"} or str(metadata.get("source") or "") == "self_training" or "自我训练" in source:
            add("打开 Agent 2.0 学习面板", "agent2")
        if source_type == "mission_control" or "总控台" in " ".join([source, " ".join(item.get("tags") or [])]):
            add("打开今日工作台", "view", view="mission-control")
        if source_type in {"automation_run", "automation"} and not run_id and source_id:
            add("打开执行会话", "automation_run", run_id=source_id)
        summary_parts = []
        if source:
            summary_parts.append(f"来源：{source}")
        if source_type:
            summary_parts.append(f"source_type={source_type}")
        if source_id:
            summary_parts.append(f"source_id={source_id}")
        if metadata:
            for key in ("artifact_id", "run_id", "task_id", "session_id", "intent", "target", "channel", "task_type", "outcome", "extractor", "article_title"):
                value = metadata.get(key)
                if value:
                    summary_parts.append(f"{key}={value}")
        return {
            "source": source or "本地学习",
            "source_url": source_url,
            "summary": "；".join(str(x) for x in summary_parts[:8]),
            "actions": actions,
            "metadata": metadata,
        }

    def GET(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            params = web.input(q="", type="", limit="20", include_disabled="1", id="")
            service = self._service()
            fact_id = str(params.id or "").strip()
            if fact_id:
                item = service.get(fact_id)
                if not item:
                    raise ValueError("事实不存在")
                return json.dumps({"status": "success", "item": item, "events": service.events(fact_id), "source_trace": self._source_trace(item), "stats": service.stats()}, ensure_ascii=False)
            include_disabled = str(params.include_disabled or "").lower() not in {"0", "false", "no"}
            items = service.search(str(params.q or ""), str(params.type or ""), int(params.limit or 20), include_disabled=include_disabled)
            return json.dumps({"status": "success", "stats": service.stats(), "items": items}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "").strip().lower()
            status = {
                "bulk_approve": "active",
                "bulk_confirm": "active",
                "bulk_enable": "active",
                "bulk_restore": "active",
                "bulk_disable": "disabled",
                "bulk_delete": "deleted",
                "approve": "active",
                "confirm": "active",
                "enable": "active",
                "restore": "active",
                "pending": "pending",
                "disable": "disabled",
                "delete": "deleted",
            }.get(action, action)
            service = self._service()
            ids = body.get("ids") if isinstance(body.get("ids"), list) else []
            ids = [str(item or "").strip() for item in ids if str(item or "").strip()]
            if ids:
                updated = []
                errors = []
                for fact_id in ids[:100]:
                    try:
                        updated.append(service.update_status(fact_id, status, str(body.get("reason") or "")))
                    except Exception as item_error:
                        errors.append({"id": fact_id, "message": str(item_error)})
                return json.dumps({"status": "success", "items": updated, "errors": errors, "stats": service.stats()}, ensure_ascii=False)
            fact_id = str(body.get("id") or body.get("fact_id") or "").strip()
            item = service.update_status(fact_id, status, str(body.get("reason") or ""))
            return json.dumps({"status": "success", "item": item, "stats": service.stats(), "events": service.events(fact_id)}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


