    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            token = str(body.pop("github_token", "") or "").strip()
            if token:
                conf()["github_api_token"] = token
                config_path = os.path.join(get_data_root(), "config.json")
                file_cfg = _read_config_file_for_write(); file_cfg["github_api_token"] = token
                with open(config_path, "w", encoding="utf-8") as handle: json.dump(file_cfg, handle, indent=4, ensure_ascii=False)
            task = _github_monitor_service().save_task(body)
            return json.dumps({"status": "success", "task": task}, ensure_ascii=False)
        except Exception as e: return json.dumps({"status": "error", "message": str(e)}, ensure_ascii=False)


