def _safe_intelligence_tasks(tasks):
    safe=json.loads(json.dumps(tasks,ensure_ascii=False))
    for task in safe:
        for target in task.get("notifications",[]) or []:
            if target.get("secret"): target["secret"]="已配置"
    return safe


