class PersonalTodosHandler:
    def GET(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            args = web.input(status="", include_archived="1")
            include_archived = str(args.include_archived or "1") not in {"0", "false", "False"}
            return json.dumps({"status":"success","todos":_personal_productivity_service().list_todos(args.status, include_archived)},ensure_ascii=False)
        except Exception as e:
            return json.dumps({"status":"error","message":str(e)},ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "create").strip()
            service = _personal_productivity_service()
            if action == "create":
                return json.dumps({"status":"success","todo":service.create_todo(body)},ensure_ascii=False)
            if action == "update":
                return json.dumps({"status":"success","todo":service.update_todo(body.get("id") or body.get("todo_id"), body)},ensure_ascii=False)
            if action == "toggle":
                return json.dumps({"status":"success","todo":service.update_todo(body.get("id") or body.get("todo_id"), {"completed": bool(body.get("completed"))})},ensure_ascii=False)
            if action == "delete":
                return json.dumps({"status":"success",**service.delete_todo(body.get("id") or body.get("todo_id"))},ensure_ascii=False)
            raise ValueError("不支持的任务清单操作")
        except Exception as e:
            return json.dumps({"status":"error","message":str(e)},ensure_ascii=False)


class PersonalRemindersHandler:
    def GET(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            return json.dumps({"status":"success","reminders":_personal_productivity_service().list_reminders()},ensure_ascii=False)
        except Exception as e:
            return json.dumps({"status":"error","message":str(e)},ensure_ascii=False)

    def POST(self):
        _require_auth(); web.header('Content-Type','application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = str(body.get("action") or "create").strip()
            service = _personal_productivity_service()
            if action == "create":
                payload = dict(body)
                if not payload.get("notifications"):
                    payload["source_channel"] = payload.get("source_channel") or "web"
                    payload["source_receiver"] = payload.get("source_receiver") or "web_user"
                return json.dumps({"status":"success","reminder":service.create_reminder(payload)},ensure_ascii=False)
            if action == "update":
                return json.dumps({"status":"success","reminder":service.update_reminder(body.get("id") or body.get("reminder_id"), body)},ensure_ascii=False)
            if action == "toggle":
                return json.dumps({"status":"success","reminder":service.toggle_reminder(body.get("id") or body.get("reminder_id"), bool(body.get("enabled")))},ensure_ascii=False)
            if action == "delete":
                return json.dumps({"status":"success",**service.delete_reminder(body.get("id") or body.get("reminder_id"))},ensure_ascii=False)
            if action == "run":
                return json.dumps({"status":"success",**service.run(body.get("id") or body.get("reminder_id"), "manual")},ensure_ascii=False)
            raise ValueError("不支持的提醒操作")
        except Exception as e:
            return json.dumps({"status":"error","message":str(e)},ensure_ascii=False)


