def _require_api_key():
    header = web.ctx.env.get("HTTP_AUTHORIZATION", "")
    token = header[7:].strip() if header.lower().startswith("bearer ") else ""
    key = _api_key_store().authenticate(token)
    if not key:
        web.header('Content-Type', 'application/json; charset=utf-8')
        raise web.unauthorized(json.dumps({"error": {"message": "无效或缺失的 API Key", "type": "authentication_error"}}, ensure_ascii=False))
    return key


class ApiAccessKeysHandler:
    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        return json.dumps({"status": "success", "keys": _api_key_store().list_keys()}, ensure_ascii=False)

    def POST(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            action = body.get("action", "create")
            if action == "create":
                key = _api_key_store().create(body.get("name", ""))
                return json.dumps({"status": "success", "key": key}, ensure_ascii=False)
            if action == "revoke":
                _api_key_store().revoke(body.get("id", ""))
                return json.dumps({"status": "success"}, ensure_ascii=False)
            raise ValueError("未知操作")
        except Exception as e:
            return json.dumps({"status": "error", "message": str(e)}, ensure_ascii=False)


