class PublicApiChatHandler:
    def POST(self):
        key = _require_api_key()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b"{}")
            messages = body.get("messages") or []
            prompt = "\n".join(str(item.get("content", "")) for item in messages if item.get("role") == "user").strip()
            if not prompt:
                raise ValueError("messages 中必须包含 user 内容")
            context = Context(ContextType.TEXT, prompt, {
                "channel_type": "api", "receiver": key["id"], "session_id": body.get("session_id") or f"api_{key['id']}", "isgroup": False,
            })
            from bridge.bridge import Bridge
            reply = Bridge().fetch_agent_reply(prompt, context) if conf().get("agent", True) else Bridge().fetch_reply_content(prompt, context)
            if not reply:
                raise RuntimeError("模型未返回内容")
            response_id = "chatcmpl-" + uuid.uuid4().hex
            return json.dumps({
                "id": response_id, "object": "chat.completion", "created": int(time.time()),
                "model": conf().get("model", ""),
                "choices": [{"index": 0, "message": {"role": "assistant", "content": str(reply.content)}, "finish_reason": "stop"}],
            }, ensure_ascii=False)
        except Exception as e:
            web.ctx.status = "400 Bad Request"
            return json.dumps({"error": {"message": str(e), "type": "invalid_request_error"}}, ensure_ascii=False)


