class SchedulerTargetsHandler:
    """List safe delivery destinations available to the scheduler creator."""

    @staticmethod
    def _current_weixin_target_entries(entries):
        """Return only currently usable Weixin notification targets.

        QR re-login can leave old approved owner rows in channel_access.json.
        Those rows are useful audit history but are no longer valid delivery
        targets.  Prefer receivers that still have persisted context_tokens;
        otherwise fall back to the newest QR owner/current credential identity.
        """
        try:
            from config import get_weixin_credentials_path
            from channel.weixin.weixin_channel import _load_credentials
            creds = _load_credentials(get_weixin_credentials_path()) or {}
        except Exception:
            creds = {}
        context_tokens = creds.get("context_tokens") if isinstance(creds, dict) else {}
        token_ids = {str(key).strip() for key, value in (context_tokens or {}).items()
                     if str(key).strip() and str(value or "").strip()}
        current_owner = str((creds or {}).get("user_id") or "").strip()

        def sort_key(entry):
            return str(entry.get("last_seen_at") or entry.get("approved_at") or entry.get("created_at") or "")

        approved = [entry for entry in entries if str(entry.get("user_id") or "").strip()]
        token_entries = [entry for entry in approved if str(entry.get("user_id") or "").strip() in token_ids]
        if token_entries:
            pool = token_entries
        else:
            owner_entries = [entry for entry in approved if str(entry.get("user_id") or "").strip() == current_owner]
            pool = owner_entries or [entry for entry in approved if entry.get("role") == "owner"] or approved
        pool = sorted(pool, key=sort_key, reverse=True)
        result, seen = [], set()
        for entry in pool:
            user_id = str(entry.get("user_id") or "").strip()
            if user_id in seen:
                continue
            seen.add(user_id)
            result.append(entry)
            # For QR-managed Weixin push, one current admin is enough.  Other
            # manual recipients can still be typed manually if needed.
            if entry.get("role") == "owner":
                break
        return result

    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            active = ChannelsHandler._active_channel_set()
            local_config = conf()
            email_configured = bool(
                str(local_config.get("email_smtp_host") or "").strip()
                and str(local_config.get("email_smtp_username") or "").strip()
                and str(local_config.get("email_smtp_password") or "")
            )
            email_default = str(local_config.get("email_default_recipient") or "").strip()
            targets = [{
                "channel": "web", "channel_label": "当前网页会话", "receiver": "web_user",
                "receiver_name": "本地用户", "is_group": False, "kind": "current",
            }]
            if "weixin" in active:
                from channel.channel_access_service import get_channel_access_service
                access = get_channel_access_service().list("weixin", "approved", "")
                for entry in self._current_weixin_target_entries(access.get("entries", [])):
                    targets.append({
                        "channel": "weixin", "channel_label": "微信",
                        "receiver": entry.get("user_id", ""),
                        "receiver_name": entry.get("display_name") or ("微信管理员" if entry.get("role") == "owner" else "微信用户"),
                        "is_group": False, "kind": "known",
                    })
            configured_webhook = str(conf().get("webhook_url") or "").strip()
            if configured_webhook:
                targets.append({
                    "channel": "webhook", "channel_label": "Webhook",
                    "receiver": "configured_webhook", "receiver_name": "已配置接收地址",
                    "is_group": False, "kind": "configured",
                })
            if email_configured and email_default:
                targets.append({
                    "channel": "email", "channel_label": "邮箱",
                    "receiver": email_default, "receiver_name": "默认收件人",
                    "is_group": False, "kind": "configured",
                })
            labels = {
                "feishu": "飞书", "dingtalk": "钉钉", "wecom_bot": "企业微信机器人",
                "wechatcom_app": "企业微信应用", "wechat_kf": "微信客服",
                "wechatmp": "微信公众号", "telegram": "Telegram", "slack": "Slack",
                "discord": "Discord", "email": "邮箱",
            }
            manual_channels = [{"channel": name, "label": labels.get(name, name)} for name in sorted(active)
                               if name not in ("web", "weixin", "webhook")]
            if not configured_webhook:
                manual_channels.append({"channel": "webhook", "label": "Webhook 地址"})
            if email_configured and not any(item.get("channel") == "email" for item in manual_channels):
                manual_channels.append({"channel": "email", "label": "邮箱地址"})
            return json.dumps({"status": "success", "targets": targets,
                               "manual_channels": manual_channels}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


class SchedulerHandler:
    @staticmethod
    def _quality_warnings(task: dict) -> list:
        action = task.get("action") or {}
        text = " ".join([
            str(task.get("name") or ""),
            str(action.get("task_description") or ""),
            str(action.get("content") or ""),
        ])
        warnings = []
        is_news = any(token in text for token in ("新闻", "热点", "早报", "简报", "资讯", "行业动态", "AI新闻", "AI 新闻"))
        if is_news and "链接：完整URL" in text:
            warnings.append("旧输出格式：链接会被运行时自动改为标题后超链接")
        if is_news and "当前条件下暂无合格结果" in text:
            warnings.append("旧空结果规则：运行时会先尝试扩大来源/时间范围")
        if is_news and not any(token in text for token in ("AI", "科技", "创业", "财税", "行业", "国内", "国际", "上海", "政策")):
            warnings.append("查询主题偏泛，建议补充关注方向")
        if task.get("last_run_status") == "empty":
            warnings.append("最近一次暂无内容，后续同日空结果会合并并停止重复通知")
        if task.get("last_run_status") == "skipped_duplicate":
            warnings.append("检测到重复任务，建议保留一条即可")
        return warnings

    @staticmethod
    def _history_from_tasks(tasks: list, hidden_ids=None) -> list:
        items = []
        seen = set()
        hidden_ids = hidden_ids or set()
        for task in tasks or []:
            task_id = str(task.get("id") or "")
            task_name = str(task.get("name") or task_id or "未命名任务")
            for item in task.get("run_history") or []:
                if not isinstance(item, dict):
                    continue
                run_id = str(item.get("id") or "")
                if not run_id:
                    run_id = f"{task_id}-{item.get('started_at') or item.get('finished_at') or uuid.uuid4().hex[:8]}"
                if run_id in seen or run_id in hidden_ids:
                    continue
                seen.add(run_id)
                normalized = dict(item)
                normalized.setdefault("id", run_id)
                normalized.setdefault("task_id", task_id)
                normalized.setdefault("task_name", task_name)
                normalized.setdefault("trigger", "scheduled")
                normalized.setdefault("started_at", item.get("finished_at") or task.get("last_run_at") or "")
                normalized.setdefault("status", item.get("status") or "unknown")
                normalized.setdefault("summary", item.get("summary") or task.get("last_result_summary") or task.get("last_error") or "")
                items.append(normalized)

            # Backfill older task records that only have “latest run” fields.
            latest_specs = [
                (
                    task.get("last_manual_run_id") or "",
                    "manual",
                    task.get("last_manual_run_started_at") or task.get("last_manual_run_at") or "",
                    task.get("last_manual_run_finished_at") or task.get("last_manual_run_at") or "",
                    task.get("last_manual_run_status") or "",
                    task.get("last_manual_run_summary") or "",
                ),
                (
                    "",
                    "scheduled",
                    task.get("last_run_at") or "",
                    task.get("last_run_at") or "",
                    task.get("last_run_status") or "",
                    task.get("last_result_summary") or task.get("last_error") or "",
                ),
            ]
            for run_id, trigger, started_at, finished_at, status, summary in latest_specs:
                if not (started_at or finished_at or status or summary):
                    continue
                run_id = run_id or f"latest-{trigger}-{task_id}-{started_at or finished_at}"
                if run_id in seen or run_id in hidden_ids:
                    continue
                seen.add(run_id)
                items.append({
                    "id": run_id,
                    "task_id": task_id,
                    "task_name": task_name,
                    "trigger": trigger,
                    "started_at": started_at or finished_at,
                    "finished_at": finished_at or started_at,
                    "status": status or "unknown",
                    "summary": summary,
                    "artifact_path": task.get("last_artifact_path") or "",
                    "readonly": True,
                })
        items.sort(key=lambda x: str(x.get("started_at") or x.get("finished_at") or ""), reverse=True)
        return items[:200]

    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            from agent.tools.scheduler.task_store import TaskStore
            workspace_root = _get_workspace_root()
            store_path = os.path.join(workspace_root, "scheduler", "tasks.json")
            store = TaskStore(store_path)
            tasks = store.list_tasks()
            for task in tasks:
                task["quality_warnings"] = self._quality_warnings(task)
            hidden_path = os.path.join(workspace_root, "scheduler", "hidden_history.json")
            hidden_ids = set()
            try:
                with open(hidden_path, "r", encoding="utf-8") as handle:
                    hidden_ids = {str(x) for x in (json.load(handle).get("ids") or []) if str(x).strip()}
            except Exception:
                hidden_ids = set()
            history = [_attach_execution_audit(dict(item), max_items=8) for item in self._history_from_tasks(tasks, hidden_ids)]
            return json.dumps({"status": "success", "tasks": tasks, "history": history}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Scheduler API error: {e}")
            return json.dumps({"status": "error", "message": str(e)})

    @staticmethod
    def _task_preflight(task: dict, next_run) -> dict:
        action = task.get("action") or {}
        channel_type = str(action.get("channel_type") or "web").strip()
        receiver = str(action.get("receiver") or ("web_user" if channel_type == "web" else "")).strip()
        receiver_name = str(action.get("receiver_name") or receiver or "接收目标").strip()
        warnings = []
        checks = []
        try:
            health = ChannelHealthHandler._channel_health(channel_type)
        except Exception as error:
            health = {"channel": channel_type, "label": channel_type or "未知通道", "ok": False,
                      "configured": False, "active": False, "level": "error", "message": str(error)}
        if channel_type == "web":
            health.update({"ok": True, "configured": True, "active": True, "level": "success", "message": "将写入 Web 消息中心。"})
        status = "success" if health.get("ok") else ("warning" if health.get("configured") or health.get("active") else "error")
        if not receiver:
            status = "error"
            warnings.append("缺少接收人，保存前需要选择或填写接收目标")
        if channel_type != "web" and status != "success":
            warnings.append(f"{health.get('label') or channel_type} 当前不可直接发送：{health.get('message') or '状态未知'}；失败时会先保存到 Web 并进入补发队列")
        checks.append({
            "name": "通知通道",
            "channel": channel_type,
            "label": health.get("label") or channel_type,
            "receiver": receiver,
            "receiver_name": receiver_name,
            "status": status,
            "message": health.get("message") or "",
            "next_action": health.get("next_action") or "",
        })
        if channel_type != "web":
            checks.append({
                "name": "兜底保存",
                "channel": "web",
                "label": "Web 消息中心",
                "receiver": "web_user",
                "receiver_name": "本地消息中心",
                "status": "success",
                "message": "外部通道不可用时，结果仍会保存在 Web 消息中心和运行记录。",
            })
        decision = {}
        try:
            from intelligence_center.decision_engine import decision_engine
            schedule_preview = {
                "next_run": next_run.strftime("%Y-%m-%d %H:%M") if next_run else "",
                "schedule_type": (task.get("schedule") or {}).get("type") or "",
            }
            decision = decision_engine().task_preflight(task, checks, schedule_preview)
            for item in decision.get("missing_items") or []:
                if item == "weixin_session_refresh":
                    warning = "绿微信会话需要刷新：结果会先保存到 Web，并在会话刷新后补发"
                else:
                    warning = f"预检发现 {item} 存在风险"
                if warning not in warnings:
                    warnings.append(warning)
        except Exception:
            decision = {}
        next_text = next_run.strftime("%Y-%m-%d %H:%M:%S") if next_run else "未知"
        return {
            "next_run_at": next_run.isoformat() if next_run else "",
            "next_run_text": next_text,
            "channel": channel_type,
            "receiver": receiver,
            "receiver_name": receiver_name,
            "checks": checks,
            "warnings": warnings,
            "decision": decision,
            "fallback": {"channel": "web", "label": "Web 消息中心", "available": True},
            "status": "warning" if warnings else "success",
            "summary": f"下次执行：{next_text}；发送到：{health.get('label') or channel_type} / {receiver_name}",
        }

    def POST(self):
        _require_auth(); web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body=json.loads(web.data() or b"{}");name=str(body.get("name") or "").strip();content=str(body.get("content") or "").strip();action_type=body.get("action_type","agent_task");schedule_type=body.get("schedule_type","interval")
            if not name or not content:raise ValueError("任务名称和执行内容不能为空")
            if action_type not in ("agent_task","send_message"):raise ValueError("不支持的任务内容类型")
            if schedule_type=="cron":
                expression=str(body.get("cron") or "").strip()
                if len(expression.split()) not in (5,6):raise ValueError("Cron 表达式应包含 5 或 6 段")
                schedule={"type":"cron","expression":expression}
            elif schedule_type=="interval":
                seconds=int(body.get("interval_seconds") or 0)
                if seconds<60:raise ValueError("执行间隔不能少于 1 分钟")
                schedule={"type":"interval","seconds":seconds}
            elif schedule_type=="once":
                run_at=str(body.get("run_at") or "").strip()
                if not run_at:raise ValueError("请选择执行时间")
                schedule={"type":"once","run_at":run_at}
            else:raise ValueError("不支持的调度类型")
            from agent.tools.scheduler.task_store import TaskStore
            from agent.tools.scheduler.scheduler_service import SchedulerService
            workspace_root=_get_workspace_root();store=TaskStore(os.path.join(workspace_root,"scheduler","tasks.json"));now=datetime.datetime.now();task_id=uuid.uuid4().hex[:8]
            channel_type=str(body.get("channel_type") or "web").strip()
            receiver=str(body.get("receiver") or ("web_user" if channel_type=="web" else "")).strip()
            receiver_name=str(body.get("receiver_name") or receiver or "接收目标").strip()
            is_group=bool(body.get("is_group",False))
            active=ChannelsHandler._active_channel_set()
            email_configured=bool(str(conf().get("email_smtp_host") or "").strip() and str(conf().get("email_smtp_username") or "").strip() and str(conf().get("email_smtp_password") or ""))
            if channel_type!="web" and channel_type!="webhook" and not (channel_type=="email" and email_configured) and channel_type not in active:raise ValueError("所选消息通道尚未接入或未启用")
            if not receiver:raise ValueError("请选择或填写消息接收目标")
            if channel_type=="webhook":
                webhook_url=str(conf().get("webhook_url") or "").strip() if receiver=="configured_webhook" else receiver
                from intelligence_center.safe_network import validate_outbound_url
                validate_outbound_url(webhook_url,allow_private=bool(conf().get("allow_private_webhooks",False)))
            if channel_type=="weixin":
                from channel.channel_access_service import get_channel_access_service
                approved=get_channel_access_service().list("weixin","approved","").get("entries",[])
                if not any(item.get("user_id")==receiver for item in approved):raise ValueError("该微信用户尚未授权")
            action={"type":action_type,"receiver":receiver,"receiver_name":receiver_name,"is_group":is_group,"channel_type":channel_type,"notify_session_id":str(body.get("session_id") or receiver)}
            if channel_type=="webhook" and receiver!="configured_webhook":action["webhook_url"]=receiver
            action["task_description" if action_type=="agent_task" else "content"]=content
            if action_type=="agent_task" and body.get("silent"):action["silent"]=True
            task={"id":task_id,"name":name,"enabled":True,"created_at":now.isoformat(),"updated_at":now.isoformat(),"schedule":schedule,"action":action}
            next_run=SchedulerService(store,lambda task:None)._calculate_next_run(task,now)
            if next_run is None:raise ValueError("无法计算下一次执行时间，请检查时间或 Cron 表达式")
            task["next_run_at"]=next_run.isoformat()
            preview=self._task_preflight(task,next_run)
            if bool(body.get("preview_only")) or str(body.get("action") or "").strip()=="preview":
                return json.dumps({"status":"success","task":task,"preview":preview},ensure_ascii=False)
            task["preflight_preview"]=preview;store.add_task(task)
            return json.dumps({"status":"success","task":task,"preview":preview},ensure_ascii=False)
        except Exception as e:return json.dumps({"status":"error","message":str(e)},ensure_ascii=False)


