class SchedulerStatusHandler:
    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            params = web.input(task_id="")
            task_id = str(params.get("task_id") or "").strip()
            if not task_id:
                return json.dumps({"status": "error", "message": "task_id required"}, ensure_ascii=False)
            from agent.tools.scheduler.task_store import TaskStore
            workspace_root = _get_workspace_root()
            store_path = os.path.join(workspace_root, "scheduler", "tasks.json")
            store = TaskStore(store_path)
            task = store.get_task(task_id)
            if not task:
                return json.dumps({"status": "error", "message": f"Task '{task_id}' not found"}, ensure_ascii=False)
            running = False
            try:
                from agent.tools.scheduler.integration import get_scheduler_service
                service = get_scheduler_service()
                running = bool(service and task_id in getattr(service, "_running_tasks", set()))
            except Exception:
                running = False
            return json.dumps({
                "status": "success",
                "task": task,
                "running": running,
                "last_run_status": task.get("last_run_status") or "",
                "last_result_summary": task.get("last_result_summary") or task.get("last_error") or "",
                "last_artifact_path": task.get("last_artifact_path") or "",
                "last_run_at": task.get("last_run_at") or "",
                "last_manual_run_at": task.get("last_manual_run_at") or "",
                "quality_warnings": task.get("quality_warnings") or TaskStore._quality_warnings(task),
            }, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Scheduler status error: {e}")
            return json.dumps({"status": "error", "message": str(e)}, ensure_ascii=False)


