class HistoryHandler:
    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            params = web.input(session_id='', page='1', page_size='20')
            session_id = params.session_id.strip()
            if not session_id:
                return json.dumps({"status": "error", "message": "session_id required"})

            from agent.memory import get_conversation_store
            store = get_conversation_store()
            result = store.load_history_page(
                session_id=session_id,
                page=int(params.page),
                page_size=int(params.page_size),
            )
            for msg in result.get("messages") or []:
                if msg.get("role") != "assistant":
                    continue
                _add_subagent_displays(msg.get("steps"))
                artifacts = _artifacts_from_steps(msg.get("steps"), session_id)
                if artifacts:
                    msg["artifacts"] = artifacts
            return json.dumps({"status": "success", **result}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] History API error: {e}")
            return json.dumps({"status": "error", "message": str(e)})


class MessageDeleteHandler:
    def POST(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            data = json.loads(web.data())
            session_id = data.get('session_id', '').strip()
            user_seq = data.get('user_seq')
            delete_user = data.get('delete_user', True)
            cascade = data.get('cascade', False)
            
            if not session_id or user_seq is None:
                return json.dumps({"status": "error", "message": "session_id and user_seq required"})
            
            # 1. Delete from database
            from agent.memory import get_conversation_store
            store = get_conversation_store()
            deleted = store.delete_message_pair(session_id, int(user_seq), delete_user=delete_user, cascade=cascade)

            # 2. Sync agent's in-memory context so its next turn sees the
            # same history as the DB. Handled by the agent_bridge helper.
            try:
                from bridge.bridge import Bridge
                Bridge().get_agent_bridge().sync_session_messages_from_store(session_id)
            except Exception as sync_err:
                logger.warning(f"[WebChannel] Failed to sync agent memory: {sync_err}")

            return json.dumps({"status": "success", "deleted": deleted}, ensure_ascii=False)
        except Exception as e:
            logger.error(f"[WebChannel] Message delete error: {e}")
            return json.dumps({"status": "error", "message": str(e)})


class LogsHandler:
    def GET(self):
        _require_auth()
        web.header('Content-Type', 'text/event-stream; charset=utf-8')
        web.header('Cache-Control', 'no-cache')
        web.header('X-Accel-Buffering', 'no')

        log_path = os.path.join(get_data_root(), "run.log")

        def generate():
            if not os.path.isfile(log_path):
                yield b"data: {\"type\": \"error\", \"message\": \"run.log not found\"}\n\n"
                return

            # Read last 200 lines for initial display
            try:
                with open(log_path, 'r', encoding='utf-8', errors='replace') as f:
                    lines = f.readlines()
                tail_lines = lines[-200:]
                chunk = ''.join(tail_lines)
                payload = json.dumps({"type": "init", "content": chunk}, ensure_ascii=False)
                yield f"data: {payload}\n\n".encode('utf-8')
            except Exception as e:
                yield f"data: {{\"type\": \"error\", \"message\": \"{e}\"}}\n\n".encode('utf-8')
                return

            # Tail new lines
            try:
                with open(log_path, 'r', encoding='utf-8', errors='replace') as f:
                    f.seek(0, 2)  # seek to end
                    deadline = time.time() + 600  # 10 min max
                    while time.time() < deadline:
                        line = f.readline()
                        if line:
                            payload = json.dumps({"type": "line", "content": line}, ensure_ascii=False)
                            yield f"data: {payload}\n\n".encode('utf-8')
                        else:
                            yield b": keepalive\n\n"
                            time.sleep(1)
            except GeneratorExit:
                return
            except Exception:
                return

        return generate()


class LogsSnapshotHandler:
    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        web.header('Cache-Control', 'no-store')
        try:
            lines = max(20, min(1000, int(web.input(lines='300').lines)))
            log_path = os.path.join(get_data_root(), "run.log")
            if not os.path.isfile(log_path):
                return json.dumps({"status":"success","content":"日志文件尚未生成。"}, ensure_ascii=False)
            with open(log_path, 'r', encoding='utf-8', errors='replace') as handle:
                content = ''.join(handle.readlines()[-lines:])
            return json.dumps({"status":"success","content":content,"updated_at":time.time()}, ensure_ascii=False)
        except Exception as error:
            return json.dumps({"status":"error","message":str(error)}, ensure_ascii=False)


class StorageRetentionHandler:
    """Manage local data retention and perform a safe age-based cleanup."""

    DEFAULTS = {
        "conversations": 180,
        "logs": 30,
        "uploads": 30,
        "artifacts": 180,
        "cache": 7,
        "auto_cleanup_enabled": True,
    }

    @classmethod
    def _path(cls):
        return os.path.join(get_data_root(), "storage_retention.json")

    @classmethod
    def _read(cls):
        values = dict(cls.DEFAULTS)
        try:
            with open(cls._path(), "r", encoding="utf-8") as handle:
                saved = json.load(handle)
            for key in values:
                if key == "auto_cleanup_enabled":
                    values[key] = bool(saved.get(key, values[key]))
                else:
                    values[key] = max(0, min(3650, int(saved.get(key, values[key]))))
        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            pass
        return values

    def GET(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        return json.dumps({"status": "success", "settings": self._read()}, ensure_ascii=False)

    def PUT(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b'{}')
            values = self._read()
            for key in values:
                if key in body:
                    if key == "auto_cleanup_enabled":
                        values[key] = bool(body[key])
                    else:
                        values[key] = max(0, min(3650, int(body[key])))
            with open(self._path(), "w", encoding="utf-8") as handle:
                json.dump(values, handle, ensure_ascii=False, indent=2)
            cleaned = self._cleanup(values)
            logger.info(f"[Storage] Retention saved; cleanup={cleaned}")
            return json.dumps({"status": "success", "settings": values, "cleaned": cleaned}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[Storage] Retention update failed: {error}")
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b'{}')
            values = self._read()
            scopes = body.get("scopes") or []
            if not isinstance(scopes, list):
                raise ValueError("清理范围格式不正确")
            scopes = [str(item) for item in scopes if str(item) in self.DEFAULTS and str(item) != "auto_cleanup_enabled"]
            if not scopes:
                raise ValueError("请选择至少一个清理范围")
            mode = str(body.get("mode") or "expired")
            cleaned = self._cleanup(values, scopes=scopes, force_cache_all=(mode == "all_cache"))
            logger.info(f"[Storage] Manual cleanup scopes={scopes}; cleaned={cleaned}")
            return json.dumps({"status": "success", "settings": values, "cleaned": cleaned}, ensure_ascii=False)
        except Exception as error:
            logger.error(f"[Storage] Manual cleanup failed: {error}")
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    @classmethod
    def _remove_old_files(cls, roots, keep_days, force_all=False):
        removed = 0
        if not force_all and not keep_days:
            return removed
        now = time.time()
        cutoff_ts = now - keep_days * 86400 if keep_days else now
        for root in roots:
            if not os.path.isdir(root):
                continue
            root_real = os.path.realpath(root)
            for current, dirs, names in os.walk(root, topdown=False):
                current_real = os.path.realpath(current)
                if not (current_real == root_real or current_real.startswith(root_real + os.sep)):
                    continue
                for name in names:
                    path = os.path.join(current, name)
                    try:
                        if force_all or os.path.getmtime(path) < cutoff_ts:
                            os.remove(path)
                            removed += 1
                    except OSError:
                        continue
                for name in dirs:
                    path = os.path.join(current, name)
                    try:
                        if not os.listdir(path):
                            os.rmdir(path)
                    except OSError:
                        continue
        return removed

    @classmethod
    def _cache_roots(cls):
        workspace_root = _get_workspace_root()
        data_root = get_data_root()
        return [
            os.path.join(data_root, "cache"),
            os.path.join(data_root, "tmp"),
            os.path.join(data_root, "temp"),
            os.path.join(workspace_root, ".cache"),
            os.path.join(workspace_root, "cache"),
            os.path.join(workspace_root, "agent_reach_tmp"),
            os.path.join(workspace_root, ".agent-reach-tmp"),
        ]

    @classmethod
    def _cleanup(cls, values, scopes=None, force_cache_all=False):
        scopes = set(scopes or ["conversations", "logs", "uploads", "artifacts", "cache"])
        result = {"conversations": 0, "logs": 0, "uploads": 0, "artifacts": 0, "cache": 0}
        days = values.get("conversations", 0)
        if "conversations" in scopes and days:
            from agent.memory import get_conversation_store
            result["conversations"] = get_conversation_store().cleanup_old_sessions(days, include_web=True)

        log_days = values.get("logs", 0)
        log_path = os.path.join(get_data_root(), "run.log")
        if "logs" in scopes and log_days and os.path.isfile(log_path):
            cutoff = datetime.datetime.now() - datetime.timedelta(days=log_days)
            with open(log_path, "r", encoding="utf-8", errors="replace") as handle:
                lines = handle.readlines()
            kept, removed = [], 0
            stamp = re.compile(r"^\[[A-Z]+\]\[(\d{4}-\d{2}-\d{2})")
            keep_line = True
            for line in lines:
                match = stamp.match(line)
                if match:
                    keep_line = datetime.datetime.strptime(match.group(1), "%Y-%m-%d") >= cutoff.replace(hour=0, minute=0, second=0, microsecond=0)
                if keep_line:
                    kept.append(line)
                else:
                    removed += 1
            if removed:
                with open(log_path, "w", encoding="utf-8") as handle:
                    handle.writelines(kept)
            result["logs"] = removed

        targets = {
            "uploads": [os.path.join(get_data_root(), "uploads")],
            "artifacts": [os.path.join(os.getcwd(), "intelligence_center", "reports")],
        }
        for kind, roots in targets.items():
            keep_days = values.get(kind, 0)
            if kind not in scopes:
                continue
            result[kind] = cls._remove_old_files(roots, keep_days)
        if "cache" in scopes:
            result["cache"] = cls._remove_old_files(
                cls._cache_roots(),
                values.get("cache", 0),
                force_all=force_cache_all,
            )
        return result


class FileSearchRootsHandler:
    """Manage the explicit directories available to local file search."""

    def GET(self):
        _require_auth()
        from common.local_file_index import get_local_file_index
        index = get_local_file_index()
        permission_map = conf().get("file_search_root_permissions") or {}
        entries = [
            {
                "path": str(path),
                "permission": str(permission_map.get(os.path.realpath(str(path)), "read")),
            }
            for path in index.roots()
        ]
        web.header('Content-Type', 'application/json; charset=utf-8')
        return json.dumps({
            "status": "success",
            "roots": [str(path) for path in index.roots()],
            "entries": entries,
            "file_count": index.count(),
            "refreshing": index.is_refreshing(),
        }, ensure_ascii=False)

    def PUT(self):
        _require_auth()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            body = json.loads(web.data() or b'{}')
            raw_entries = body.get("entries")
            if raw_entries is None:
                raw_entries = [{"path": path, "permission": "read"} for path in (body.get("roots") or [])]
            if not isinstance(raw_entries, list):
                raise ValueError("目录列表格式不正确")
            raw_roots = [entry.get("path") if isinstance(entry, dict) else entry for entry in raw_entries]
            if not isinstance(raw_roots, list):
                raise ValueError("目录列表格式不正确")
            roots = []
            permissions = {}
            for index, raw in enumerate(raw_roots):
                path = os.path.realpath(os.path.expanduser(str(raw or "").strip()))
                if not path or not os.path.isdir(path):
                    raise ValueError(f"目录不存在：{raw}")
                if path not in roots:
                    roots.append(path)
                entry = raw_entries[index] if index < len(raw_entries) else {}
                permission = str(entry.get("permission", "read")) if isinstance(entry, dict) else "read"
                permissions[path] = "read_write" if permission == "read_write" else "read"
            file_cfg = _read_config_file_for_write()
            file_cfg["file_search_roots"] = roots
            file_cfg["file_search_root_permissions"] = permissions
            with open(os.path.join(get_data_root(), "config.json"), "w", encoding="utf-8") as handle:
                json.dump(file_cfg, handle, ensure_ascii=False, indent=4)
            conf()["file_search_roots"] = roots
            conf()["file_search_root_permissions"] = permissions
            from common.local_file_index import get_local_file_index
            index = get_local_file_index()
            index.start_background_refresh()
            logger.info(f"[FileIndex] authorized roots updated: {len(roots)}")
            return json.dumps({
                "status": "success",
                "roots": roots,
                "entries": [{"path": path, "permission": permissions[path]} for path in roots],
                "refreshing": True,
            }, ensure_ascii=False)
        except Exception as error:
            logger.warning(f"[FileIndex] root update failed: {error}")
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)

    def POST(self):
        """Open the native Windows directory picker for the local web UI.

        Browsers deliberately do not expose an absolute local directory path.
        The Electron client has its own IPC picker; this endpoint provides the
        same local-only experience when CowAgent is opened at 127.0.0.1.
        """
        _require_sensitive_local_access()
        web.header('Content-Type', 'application/json; charset=utf-8')
        try:
            if os.name != "nt":
                raise ValueError("当前系统请直接输入完整目录路径")
            import subprocess
            script = (
                "Add-Type -AssemblyName System.Windows.Forms;"
                "$owner=New-Object System.Windows.Forms.Form;"
                "$owner.TopMost=$true;"
                "$owner.ShowInTaskbar=$false;"
                "$owner.Opacity=0;"
                "$owner.Width=1;$owner.Height=1;"
                "$owner.StartPosition='CenterScreen';"
                "$owner.Show();$owner.Activate();"
                "$dialog=New-Object System.Windows.Forms.FolderBrowserDialog;"
                "$dialog.Description='选择允许 CowAgent 访问的目录';"
                "$dialog.ShowNewFolderButton=$false;"
                "if($dialog.ShowDialog($owner) -eq [System.Windows.Forms.DialogResult]::OK){"
                "[Console]::OutputEncoding=[System.Text.Encoding]::UTF8;"
                "Write-Output $dialog.SelectedPath};"
                "$owner.Close();$owner.Dispose()"
            )
            creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
            result = subprocess.run(
                ["powershell.exe", "-NoProfile", "-STA", "-Command", script],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=120,
                creationflags=creationflags,
            )
            if result.returncode != 0:
                raise RuntimeError((result.stderr or "目录选择器打开失败").strip())
            path = (result.stdout or "").strip()
            if path:
                path = os.path.realpath(path)
                if not os.path.isdir(path):
                    raise ValueError("所选目录不存在")
            return json.dumps({"status": "success", "path": path}, ensure_ascii=False)
        except subprocess.TimeoutExpired:
            return json.dumps({"status": "error", "message": "目录选择已超时"}, ensure_ascii=False)
        except Exception as error:
            logger.warning(f"[FileIndex] directory picker failed: {error}")
            return json.dumps({"status": "error", "message": str(error)}, ensure_ascii=False)


class LogsDownloadHandler:
    """Serve the full run.log as a file download for offline troubleshooting.

    The /api/logs stream only replays the last 200 lines; this returns the whole
    file so users can attach it to a bug report.
    """

    def GET(self):
        _require_auth()
        log_path = os.path.join(get_data_root(), "run.log")
        if not os.path.isfile(log_path):
            raise web.notfound()

        try:
            with open(log_path, 'rb') as f:
                data = f.read()
        except Exception as e:
            logger.error(f"[WebChannel] Log download error: {e}")
            raise web.internalerror()

        # Timestamped name so multiple downloads don't overwrite each other.
        fname = f"cowagent-{time.strftime('%Y%m%d-%H%M%S')}.log"
        web.header('Content-Type', 'text/plain; charset=utf-8')
        web.header('Content-Disposition', f'attachment; filename="{fname}"')
        web.header('Content-Length', str(len(data)))
        web.header('Cache-Control', 'no-store')
        return data


class AssetsHandler:
    def GET(self, file_path):  # 修改默认参数
        try:
            # 如果请求是/static/，需要处理
            if file_path == '':
                # 返回目录列表...
                pass

            # 获取当前文件的绝对路径
            current_dir = os.path.dirname(os.path.abspath(__file__))
            static_dir = os.path.join(current_dir, 'static')

            full_path = os.path.normpath(os.path.join(static_dir, file_path))

            # 安全检查：确保请求的文件在static目录内
            if not os.path.abspath(full_path).startswith(os.path.abspath(static_dir)):
                logger.error(f"Security check failed for path: {full_path}")
                raise web.notfound()

            if not os.path.exists(full_path) or not os.path.isfile(full_path):
                # Browsers routinely probe optional asset variants (e.g. a
                # .ttf fallback declared alongside .woff2 in @font-face);
                # logging these as errors floods the console with harmless
                # noise. Keep it at debug level — real misconfigurations
                # will still surface via the network panel.
                logger.debug(f"Static file not found: {full_path}")
                raise web.notfound()

            # 设置正确的Content-Type
            content_type = mimetypes.guess_type(full_path)[0]
            if content_type:
                web.header('Content-Type', content_type)
            else:
                # 默认为二进制流
                web.header('Content-Type', 'application/octet-stream')

            # 读取并返回文件内容
            with open(full_path, 'rb') as f:
                return f.read()

        except web.HTTPError:
            # The 404 path above already logged at debug; re-raise as-is so
            # web.py returns the original status to the client.
            raise
        except Exception as e:
            logger.error(f"Error serving static file: {e}", exc_info=True)
            raise web.notfound()


def _workspace_service(session_id: str = None, agent_id: str = None):
    from agent.workspace.service import WorkspaceService
    return WorkspaceService(_get_workspace_root(session_id, agent_id))


# System assets (memory / knowledge / persona files) always live in state_root,
# never in a project dir. When a session has a project open, a relative ref to
# one of these resolves against the project and misses; we fall back to the
# system directory so preview/@ still work.
_SYSTEM_ASSET_PREFIXES = ("memory/", "memory\\", "knowledge/", "knowledge\\")
_SYSTEM_ASSET_FILES = ("MEMORY.md", "AGENT.md", "USER.md", "RULE.md")


def _is_system_asset_rel(rel_path: str) -> bool:
    """True if a relative path points at a state_root-anchored system asset."""
    p = (rel_path or "").lstrip("./")
    return p in _SYSTEM_ASSET_FILES or p.startswith(_SYSTEM_ASSET_PREFIXES)


def _system_workspace_service():
    from agent.workspace.service import WorkspaceService
    from common.state_dir import state_root_str
    return WorkspaceService(state_root_str())


def _decorate_entry(svc, entry: dict) -> dict:
    """Attach the URLs the frontend needs to preview or download an entry."""
    if entry.get("is_dir"):
        return entry
    abs_path = entry.get("abs_path") or os.path.join(svc.root, entry["path"])
    entry["abs_path"] = abs_path
    entry["raw_url"] = f"/api/file?path={quote(abs_path)}"
    entry["preview_url"] = _build_preview_url(abs_path)
    return entry


